prompt --application/shared_components/navigation/lists/database_menu_access
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(8047725125209598197)
,p_name=>'DATABASE_MENU_ACCESS'
,p_static_id=>'database-menu-access'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Dynamic Menu with Role-Based Access and Individual Icons */',
'',
'WITH ROLE_ACCESS AS',
'(',
'    SELECT S.SUBMENU_NO,',
'           S.SUBMENU_ID,',
'           S.MENU_NO,',
'           S.SUBMENU_NAME,',
'           S.APEX_PAGE_NO,',
'           S.SUBMENU_TYPE,',
'           S.HIDE_FROM_MENU,',
'           S.SL_NO,',
'           S.SUBMENU_ICON',
'      FROM SA_USER U',
'           JOIN SA_GRANTOBJECT G',
'             ON G.ROLE_NO = U.ROLE_NO',
'            AND G.CAN_VIEW = 1',
'            AND G.ACTIVE_FLAG = 1',
'           JOIN SA_SUBMENU S',
'             ON S.SUBMENU_NO = G.SUBMENU_NO',
'     WHERE U.USER_NO = :G_USER_NO',
'       AND S.HIDE_FROM_MENU = 0',
'       AND S.ACTIVE_FLAG = 1',
'       AND S.SUBMENU_TYPE IN (''F'', ''R'')',
')',
'SELECT LEVEL AS LEVEL_NO,',
'       OBJECT_NAME AS LABEL,',
'',
'       CASE',
'           WHEN CONNECT_BY_ISLEAF = 1',
'           THEN ''f?p=&APP_ID.:''',
'                || RAW_PAGE_NO',
'                || '':&APP_SESSION.:::''',
'                || RAW_CHILD_ITEM',
'       END AS TARGET,',
'',
'       CASE',
'           WHEN LEVEL = 1',
'           THEN DECODE(PARENT_ITEM, ''0'', CHILD_ITEM, PARENT_ITEM)',
'           ELSE CHILD_ITEM',
'       END AS VALUE,',
'',
'       /* Individual menu icon */',
'       SUBMENU_ICON AS IMAGE,',
'',
'       OBJECT_ID,',
'       PARENT_ITEM,',
'       CHILD_ITEM',
'',
'  FROM',
'       (',
'           /* Submenu / Page */',
'           SELECT TO_CHAR(R.MENU_NO) AS PARENT_ITEM,',
'                  ''P_'' || TO_CHAR(R.APEX_PAGE_NO) AS CHILD_ITEM,',
'                  TO_CHAR(R.APEX_PAGE_NO) AS RAW_PAGE_NO,',
'                  ''P_'' || TO_CHAR(R.APEX_PAGE_NO) AS RAW_CHILD_ITEM,',
'                  R.SUBMENU_NAME AS OBJECT_NAME,',
'                  F_MODULE_SL(R.MENU_NO)',
'                      + (NVL(R.SL_NO, 0.01) / 100) AS DISPLAY_ORDER,',
'                  R.SUBMENU_ID AS OBJECT_ID,',
'                  R.SL_NO,',
'                  R.SUBMENU_ICON AS SUBMENU_ICON',
'             FROM ROLE_ACCESS R',
'',
'           UNION ALL',
'',
'           /* Parent Menu */',
'           SELECT TO_CHAR(',
'                      DECODE(M.PARENT_MENU_NO, NULL, 0, M.PARENT_MENU_NO)',
'                  ) AS PARENT_ITEM,',
'                  TO_CHAR(M.MENU_NO) AS CHILD_ITEM,',
'                  NULL AS RAW_PAGE_NO,',
'                  TO_CHAR(M.MENU_NO) AS RAW_CHILD_ITEM,',
'                  M.MENU_NAME AS OBJECT_NAME,',
'                  F_MODULE_SL(M.MENU_NO) AS DISPLAY_ORDER,',
'                  M.MENU_ID AS OBJECT_ID,',
'                  M.SL_NO,',
'                  M.MENU_ICON AS SUBMENU_ICON',
'             FROM SA_MENU M',
'            WHERE M.ACTIVE_FLAG = 1',
'              AND EXISTS',
'                  (',
'                      SELECT 1',
'                        FROM ROLE_ACCESS R',
'                       WHERE R.MENU_NO = M.MENU_NO',
'                  )',
'       )',
' START WITH PARENT_ITEM = ''0''',
'CONNECT BY PRIOR CHILD_ITEM = PARENT_ITEM',
' ORDER SIBLINGS BY SL_NO;'))
,p_version_scn=>'SH256:dVYfU7xxorw1fdtGOs87SSzyNaN-57DPTPMh3GEWTOo'
,p_updated_on=>wwv_flow_imp.dz('20261015125716Z')
,p_updated_by=>'ADMIN'
);
end;
/
