,p_static_id=>'lov-12-product'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT P.PRODUCT_NO,',
'         P.PRODUCT_CODE || '' - '' || P.PRODUCT_NAME     PRODUCT_NAME,',
'         P.DESCRIPTION,',
'         P.UOM_NO,',
'         U.UOM_NAME,',
'         C.CONVERT_UOM_NO,',
'         CU.UOM_NAME                                   AS CONVERT_UOM_NAME,',
'         C.CONVERSION_FACTOR,',
'         P.PURCHASE_RATE,',
'         P.SALES_RATE',
'    FROM MST_PRODUCT P',
'         LEFT JOIN MST_UOM U ON U.UOM_NO = P.UOM_NO',
'         LEFT JOIN MST_UOM_CONVERSION C',
'             ON C.PRODUCT_NO = P.PRODUCT_NO AND C.ACTIVE_FLAG = ''1''',
'         LEFT JOIN MST_UOM CU ON CU.UOM_NO = C.CONVERT_UOM_NO',
'   WHERE P.ACTIVE_FLAG = 1',
