prompt --application/shared_components/user_interface/lovs/lov_17_product
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(18608649872017486415)
,p_lov_name=>'LOV_17_PRODUCT'
,p_static_id=>'lov-17-product'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT P.PRODUCT_NO,',
'       P.PRODUCT_NAME,',
'       P.DESCRIPTION,',
'       TO_CHAR(NVL(S.STOCK_QTY,0),''FM999G999G990D000'')',
'       || '' '' || U.UOM_NAME AS STOCK',
'  FROM MST_PRODUCT P',
'  JOIN MST_UOM U',
'    ON U.UOM_NO = P.UOM_NO',
'   AND U.ACTIVE_FLAG = ''1''',
'  LEFT JOIN',
'  (',
'      SELECT PRODUCT_NO,',
'             SUM(NVL(QTY_IN,0)) -',
'             SUM(NVL(QTY_OUT,0)) AS STOCK_QTY',
'        FROM TRN_STOCK_LEDGER',
'       GROUP BY PRODUCT_NO',
'  ) S',
'    ON S.PRODUCT_NO = P.PRODUCT_NO',
' WHERE P.ACTIVE_FLAG = 1',
' ORDER BY P.PRODUCT_NAME;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'PRODUCT_NO'
,p_display_column_name=>'PRODUCT_NAME'
,p_version_scn=>'SH256:28tfbUIWZtQ7tXzcN6jib7vBgd3_pD5C-mwODrI1VMo'
