begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(11458084852907489770)
,p_lov_name=>'LOV_21_INVOICE'
,p_static_id=>'lov-21-invoice'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT O.ORDER_CODE',
'       || '' - ''',
'       || TO_CHAR(O.ORDER_DATE,''DD-MON-YYYY'') AS ORDER_CODE,',
'',
'       O.ORDER_NO,',
'',
'       O.CUSTOMER_NO,',
'',
'       C.CUSTOMER_NAME,',
'',
'       C.MOBILE_NO,',
'',
'       C.ADDRESS,',
'',
'       O.ORDER_DATE,',
'',
'       O.REMARKS,',
'',
'       NVL(',
'           (',
'               SELECT SUM(D.TOTAL_AMOUNT)',
'                 FROM TRN_SALES_ORDER_DTL D',
'                WHERE D.ORDER_NO = O.ORDER_NO',
'           ),',
'           0',
'       ) TOTAL_AMOUNT',
'',
'FROM TRN_SALES_ORDER_MST O',
'JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = O.CUSTOMER_NO',
'',
'WHERE EXISTS',
'(',
'    SELECT 1',
'      FROM TRN_SALES_ORDER_DTL D',
'     WHERE D.ORDER_NO = O.ORDER_NO',
'       AND NVL(D.BALANCE_QTY,0) > 0',
')',
'OR O.ORDER_NO = :P21_ORDER_NO',
'',
'ORDER BY O.ORDER_NO DESC;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'ORDER_NO'
,p_display_column_name=>'ORDER_CODE'
