,p_static_id=>'lov-304-invoice-list'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/29/2026 5:47:36 PM (QP5 v5.388) */',
'  SELECT M.INVOICE_NO                                AS INVOICE_NO,',
'         M.INVOICE_CODE                              AS DOC_CODE,',
'         TO_CHAR (M.INVOICE_DATE, ''DD-MON-YYYY'')     AS DOC_DATE,',
'         NVL (M.TOTAL_AMOUNT, 0)                     AS INVOICE_AMOUNT,',
'         NVL (M.RECEIVED_AMOUNT, 0)                  AS RECEIVED_AMOUNT,',
'         NVL (M.DUE_AMOUNT, 0)                         AS DUE_AMOUNT,',
'         NVL (M.DUE_AMOUNT, 0)    AS PAYMENT_AMOUNT',
'    FROM TRN_SALES_INVOICE_MST M',
'   WHERE M.CUSTOMER_NO = :P304_PARTY_NO AND NVL (M.DUE_AMOUNT, 0) > 0',
'',
'ORDER BY M.INVOICE_DATE DESC;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'INVOICE_NO'
