prompt --application/shared_components/security/authentications/database_user_authentication
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(8047979869825607624)
,p_name=>'DATABASE_USER_AUTHENTICATION'
,p_static_id=>'database-user-authentication'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'authentication_function', 'CUSTOM_AUTH',
  'enable_legacy_attributes', 'N')).to_clob
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 10/15/2026 1:16:05 PM (QP5 v5.388) */',
'FUNCTION CUSTOM_AUTH (P_USERNAME IN VARCHAR2, P_PASSWORD IN VARCHAR2)',
'    RETURN BOOLEAN',
'AS',
'    v_user_info    NUMBER := 0;',
'    V_ISVALIDATE   VARCHAR (100);',
'    v_user_no      NUMBER;',
'BEGIN',
'    SELECT F_PASSWORD (P_USERNAME, P_PASSWORD) INTO V_ISVALIDATE FROM DUAL;',
'',
'    SELECT                                                   --COUNT(USER_NO),',
'           USER_NO, USER_TYPE,UPPER(USER_NAME),UPPER(USER_ID)',
'      INTO                                                      --v_user_info,',
'           :G_USER_NO, :G_USER_TYPE,:G_USER_NAME,:G_USER_CODE',
'      FROM SA_USER',
'     WHERE UPPER (USER_ID) = UPPER (P_USERNAME) AND USER_PWD = P_PASSWORD --V_ISVALIDATE',
'                                                                         -- GROUP BY USER_NO',
'                                                                         ;',
'',
'    -- APEX_UTIL.SET_SESSION_STATE(''G_USER'',v_user_no);',
'    -- :G_USER := G_USER_NAME(v_user_no);',
'    RETURN TRUE;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        RETURN FALSE;',
'END;'))
,p_invalid_session_type=>'LOGIN'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_version_scn=>'SH256:a1-cxWsFLGrxt6rYiWweJG4M6lkwZewoFUzV4S_rmnE'
,p_created_on=>wwv_flow_imp.dz('20260819114359Z')
,p_updated_on=>wwv_flow_imp.dz('20261015134602Z')
,p_created_by=>'WKSP_WSPOS'
,p_updated_by=>'ADMIN'
);
end;
