prompt --application/pages/page_00001
begin
wwv_flow_imp_page.create_page(
 p_id=>1
,p_name=>'Home'
,p_alias=>'HOME'
,p_step_title=>'Dealer Inventory & Sales Management System'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'/* =================================',
'   COMPACT POS DASHBOARD',
'   PROFESSIONAL DESIGN',
'   ================================= */',
'',
'.pos-dashboard {',
'    width: 100%;',
'    color: #1e293b;',
'    font-family: inherit;',
'    box-sizing: border-box;',
'}',
'',
'.pos-dashboard *,',
'.pos-dashboard *::before,',
'.pos-dashboard *::after {',
'    box-sizing: border-box;',
'}',
'',
'/* =================================',
'   WELCOME HEADER',
'   GREETING LEFT | CLOCK CENTER | DATE RIGHT',
'   ================================= */',
'',
'.pos-dash-welcome {',
'    display: grid !important;',
'    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) !important;',
'    align-items: center !important;',
'    gap: 10px;',
'    width: 100%;',
'    padding: 8px 12px;',
'    margin-bottom: 8px;',
'    border: 1px solid #e5eaf2;',
'    border-radius: 9px;',
'    background: linear-gradient(110deg, #ffffff, #f3f7ff);',
'    box-shadow: 0 2px 6px rgba(30, 64, 120, .04);',
'}',
'',
'/* GREETING - LEFT */',
'',
'.pos-welcome-left {',
'    grid-column: 1;',
'    justify-self: start;',
'    min-width: 0;',
'}',
'',
'.pos-welcome-title {',
'    color: #1e3a5f;',
'    font-size: 19px;',
'    font-weight: 750;',
'    line-height: 1.3;',
'}',
'',
'.pos-wave {',
'    display: inline-block;',
'    font-size: 17px;',
'    margin-left: 3px;',
'    transform-origin: 70% 70%;',
'    animation: pos-wave-animation 2.5s infinite;',
'}',
'',
'@keyframes pos-wave-animation {',
'    0%, 60%, 100% { transform: rotate(0deg); }',
'    10%, 30% { transform: rotate(14deg); }',
'    20%, 40% { transform: rotate(-8deg); }',
'}',
'',
'.pos-welcome-subtitle {',
'    margin-top: 3px;',
'    color: #64748b;',
'    font-size: 11px;',
'    line-height: 1.4;',
'}',
'',
'/* =================================',
'   DIGITAL CLOCK - EXACT CENTER',
'   ================================= */',
'',
'.pos-digital-clock {',
'    grid-column: 2;',
'    justify-self: center !important;',
'    align-self: center !important;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    gap: 7px;',
'',
'    width: max-content;',
'    min-width: 160px;',
'    margin: 0 !important;',
'    padding: 5px 10px;',
'',
'    background: linear-gradient(135deg, #f5f3ff, #eef6ff);',
'    border: 1px solid #e0e7ff;',
'    border-radius: 8px;',
'    box-shadow: 0 1px 4px rgba(79, 70, 229, .05);',
'}',
'',
'/* CLOCK ICON */',
'',
'.pos-clock-icon {',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    flex: 0 0 29px;',
'    width: 29px;',
'    height: 29px;',
'',
'    color: #6554d9;',
'    background: #e5e1ff;',
'    border-radius: 7px;',
'    font-size: 14px;',
'}',
'',
'/* CLOCK CONTENT */',
'',
'.pos-clock-content {',
'    display: grid;',
'    grid-template-columns: auto auto;',
'    align-items: baseline;',
'    column-gap: 4px;',
'}',
'',
'.pos-clock-time {',
'    color: #312e81;',
'    font-family: Consolas, "Courier New", monospace;',
'    font-size: 17px;',
'    font-weight: 800;',
'    line-height: 20px;',
'    letter-spacing: 0;',
'    font-variant-numeric: tabular-nums;',
'    white-space: nowrap;',
'}',
'',
'.pos-clock-period {',
'    color: #7c3aed;',
'    font-size: 9px;',
'    font-weight: 800;',
'}',
'',
'.pos-clock-day {',
'    grid-column: 1 / -1;',
'    margin-top: 1px;',
'    color: #7b83a6;',
'    font-size: 8px;',
'    font-weight: 800;',
'    letter-spacing: 1px;',
'    line-height: 10px;',
'}',
'',
'/* =================================',
'   DATE - RIGHT',
'   ================================= */',
'',
'.pos-welcome-date {',
'    grid-column: 3;',
'    justify-self: end !important;',
'    align-self: center !important;',
'',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    gap: 7px;',
'    flex-shrink: 0;',
'',
'    margin: 0 !important;',
'    padding: 6px 9px;',
'',
'    border: 1px solid #e1e9f5;',
'    border-radius: 7px;',
'    background: #fff;',
'    color: #2563eb;',
'    font-size: 12px;',
'}',
'',
'.pos-welcome-date .fa {',
'    color: #2563eb;',
'    font-size: 12px;',
'}',
'',
'.pos-date-value {',
'    color: #334155;',
'    font-size: 11px;',
'    font-weight: 700;',
'    white-space: nowrap;',
'}',
'',
'/* =================================',
'   KPI GRID - FOUR CARDS PER ROW',
'   ================================= */',
'',
'.pos-kpi-grid {',
'    display: grid;',
'    grid-template-columns: repeat(4, minmax(0, 1fr));',
'    gap: 8px;',
'    width: 100%;',
'    margin-bottom: 8px;',
'}',
'',
'/* =================================',
'   COMPACT KPI CARD',
'   ================================= */',
'',
'.pos-kpi {',
'    display: flex;',
'    align-items: center;',
'    gap: 9px;',
'',
'    min-width: 0;',
'    min-height: 58px;',
'    padding: 8px 10px;',
'',
'    position: relative;',
'    overflow: hidden;',
'',
'    border: 1px solid var(--kpi-border, #e8edf4);',
'    border-radius: 8px;',
'    background: #fff;',
'',
'    box-shadow: 0 2px 5px rgba(15, 23, 42, .035);',
'    transition: box-shadow .2s ease, transform .2s ease;',
'}',
'',
'.pos-kpi:hover {',
'    box-shadow: 0 4px 10px rgba(15, 23, 42, .08);',
'    transform: translateY(-1px);',
'}',
'',
'.pos-kpi::after {',
'    content: "";',
'    position: absolute;',
'    top: 0;',
'    right: 0;',
'    width: 3px;',
'    height: 100%;',
'    background: var(--kpi-color, #64748b);',
'}',
'',
'/* KPI ICON */',
'',
'.pos-kpi-icon {',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'',
'    flex: 0 0 32px;',
'    width: 32px;',
'    height: 32px;',
'',
'    border-radius: 7px;',
'    background: var(--kpi-bg, #f1f5f9);',
'    color: var(--kpi-color, #475569);',
'    font-size: 15px;',
'}',
'',
'/* KPI TEXT */',
'',
'.pos-kpi-content {',
'    flex: 1;',
'    min-width: 0;',
'}',
'',
'.pos-kpi-label {',
'    margin-bottom: 3px;',
'    color: var(--kpi-color, #64748b);',
'    font-size: 10px;',
'    font-weight: 700;',
'    line-height: 1.35;',
'}',
'',
'.pos-kpi-value {',
'    color: var(--kpi-color, #172b4d);',
'    font-size: 15px;',
'    font-weight: 750;',
'    line-height: 1.3;',
'    overflow-wrap: anywhere;',
'    font-variant-numeric: tabular-nums;',
'}',
'',
'/* =================================',
'   KPI THEME COLORS',
'   ================================= */',
'',
'.kpi-green {',
'    --kpi-color: #13845d;',
'    --kpi-bg: #e8f8f0;',
'    --kpi-border: #c8efd7;',
'}',
'',
'.kpi-blue {',
'    --kpi-color: #245fce;',
'    --kpi-bg: #eaf2ff;',
'    --kpi-border: #d3e3ff;',
'}',
'',
'.kpi-orange {',
'    --kpi-color: #c66a10;',
'    --kpi-bg: #fff3e5;',
'    --kpi-border: #f9e4b8;',
'}',
'',
'.kpi-purple {',
'    --kpi-color: #7950bd;',
'    --kpi-bg: #f1eaff;',
'    --kpi-border: #e3d4ff;',
'}',
'',
'.kpi-teal {',
'    --kpi-color: #0d8379;',
'    --kpi-bg: #e2f8f5;',
'    --kpi-border: #c4eeea;',
'}',
'',
'.kpi-indigo {',
'    --kpi-color: #4f46c8;',
'    --kpi-bg: #ecebff;',
'    --kpi-border: #d9dcff;',
'}',
'',
'.kpi-red {',
'    --kpi-color: #cf3838;',
'    --kpi-bg: #ffeded;',
'    --kpi-border: #fecaca;',
'}',
'',
'.kpi-return {',
'    --kpi-color: #b45309;',
'    --kpi-bg: #fff4df;',
'    --kpi-border: #f5e4b5;',
'}',
'',
'/* =================================',
'   FOOTER NOTE',
'   ================================= */',
'',
'.pos-dash-note {',
'    display: flex;',
'    align-items: center;',
'    gap: 6px;',
'',
'    padding: 6px 9px;',
'    margin-top: 2px;',
'',
'    border: 1px solid #e5eaf2;',
'    border-radius: 7px;',
'    background: #f8fafc;',
'',
'    color: #64748b;',
'    font-size: 10px;',
'    line-height: 1.4;',
'}',
'',
'.pos-dash-note .fa {',
'    color: #2563eb;',
'    font-size: 12px;',
'    flex-shrink: 0;',
'}',
'',
'/* =================================',
'   TABLET',
'   ================================= */',
'',
'@media (max-width: 1100px) {',
'    .pos-kpi-grid {',
'        grid-template-columns: repeat(2, minmax(0, 1fr));',
'    }',
'',
'    .pos-dash-welcome {',
'        gap: 7px;',
'        padding: 7px 9px;',
'    }',
'',
'    .pos-welcome-title {',
'        font-size: 17px;',
'    }',
'',
'    .pos-clock-time {',
'        font-size: 15px;',
'    }',
'}',
'',
'/* =================================',
'   MOBILE HEADER',
'   GREETING + DATE ON TOP',
'   CLOCK CENTERED BELOW',
'   ================================= */',
'',
'@media (max-width: 600px) {',
'    .pos-dash-welcome {',
'        grid-template-columns: minmax(0, 1fr) auto !important;',
'        row-gap: 8px;',
'        column-gap: 6px;',
'        padding: 9px 10px;',
'    }',
'',
'    .pos-welcome-left {',
'        grid-column: 1;',
'        grid-row: 1;',
'        justify-self: start;',
'    }',
'',
'    .pos-welcome-title {',
'        font-size: 16px;',
'    }',
'',
'    .pos-welcome-subtitle {',
'        font-size: 10px;',
'    }',
'',
'    .pos-welcome-date {',
'        grid-column: 2;',
'        grid-row: 1;',
'        justify-self: end !important;',
'        padding: 5px 7px;',
'    }',
'',
'    .pos-date-value {',
'        font-size: 10px;',
'    }',
'',
'    .pos-digital-clock {',
'        grid-column: 1 / -1;',
'        grid-row: 2;',
'        justify-self: center !important;',
'    }',
'',
'    .pos-kpi-grid {',
'        grid-template-columns: repeat(2, minmax(0, 1fr));',
'        gap: 7px;',
'    }',
'',
'    .pos-kpi {',
'        min-height: 53px;',
'        gap: 7px;',
'        padding: 7px 8px;',
'    }',
'',
'    .pos-kpi-icon {',
'        flex-basis: 28px;',
'        width: 28px;',
'        height: 28px;',
'        font-size: 13px;',
'    }',
'',
'    .pos-kpi-label {',
'        font-size: 9px;',
'    }',
'',
'    .pos-kpi-value {',
'        font-size: 12px;',
'    }',
'}',
'',
'/* =================================',
'   SMALL MOBILE',
'   ================================= */',
'',
'@media (max-width: 380px) {',
'    .pos-dash-welcome {',
'        grid-template-columns: minmax(0, 1fr) !important;',
'    }',
'',
'    .pos-welcome-left {',
'        grid-column: 1;',
'        grid-row: 1;',
'    }',
'',
'    .pos-welcome-date {',
'        grid-column: 1;',
'        grid-row: 2;',
'        justify-self: start !important;',
'    }',
'',
'    .pos-digital-clock {',
'        grid-column: 1;',
'        grid-row: 3;',
'        justify-self: center !important;',
'    }',
'',
'    .pos-kpi-grid {',
'        gap: 6px;',
'    }',
'',
'    .pos-kpi {',
'        gap: 5px;',
'        padding: 6px;',
'    }',
'',
'    .pos-kpi-icon {',
'        flex-basis: 25px;',
'        width: 25px;',
'        height: 25px;',
'        font-size: 12px;',
'    }',
'',
'    .pos-kpi-value {',
'        font-size: 11px;',
'    }',
'}',
''))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
