 p_id=>wwv_flow_imp.id(8032872439836477886)
,p_plug_name=>'Dealer Inventory & Sales Management System'
,p_static_id=>'dealer-inventory-sales-management-system'
,p_region_template_options=>'#DEFAULT#:t-HeroRegion--noPadding:t-Form--slimPadding:t-Form--stretchInputs'
,p_plug_template=>2675494171183407654
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
