wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(20469602839467539)
,p_chart_id=>wwv_flow_imp.id(20469525274467538)
,p_static_id=>'new_1'
,p_seq=>10
,p_name=>'New'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH CHART_DATA AS',
'(',
'    SELECT',
'        ''Sales'' AS LABEL,',
'        NVL(SUM(TOTAL_AMOUNT), 0) AS VALUE',
'    FROM WKSP_WSPOS.TRN_SALES_INVOICE_MST',
'    WHERE INVOICE_DATE >= TRUNC(SYSDATE)',
'      AND INVOICE_DATE < TRUNC(SYSDATE) + 1',
'',
'    UNION ALL',
'',
'    SELECT',
'        ''Purchase'' AS LABEL,',
'        NVL(SUM(TOTAL_AMOUNT), 0) AS VALUE',
'    FROM WKSP_WSPOS.TRN_PURCHASE_MST',
'    WHERE PURCHASE_DATE >= TRUNC(SYSDATE)',
'      AND PURCHASE_DATE < TRUNC(SYSDATE) + 1',
'      AND APPROVAL_STATUS = ''A''',
'',
'    UNION ALL',
'',
'    SELECT',
'        ''Return'' AS LABEL,',
'        NVL(SUM(D.TOTAL_AMOUNT), 0) AS VALUE',
'    FROM WKSP_WSPOS.TRN_CUSTOMER_RETURN_MST M',
'    JOIN WKSP_WSPOS.TRN_CUSTOMER_RETURN_DTL D',
'      ON D.RETURN_NO = M.RETURN_NO',
'    WHERE M.RETURN_DATE >= TRUNC(SYSDATE)',
'      AND M.RETURN_DATE < TRUNC(SYSDATE) + 1',
'      AND M.APPROVAL_STATUS = ''A''',
')',
'SELECT LABEL, VALUE',
'FROM CHART_DATA',
'ORDER BY VALUE DESC;'))
,p_items_value_column_name=>'VALUE'
,p_items_label_column_name=>'LABEL'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
,p_created_on=>wwv_flow_imp.dz('20261015111507Z')
,p_updated_on=>wwv_flow_imp.dz('20261015111507Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
