wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8034953009540538123)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P_SAVE_MENU'
,p_static_id=>'p-save-menu'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' BEGIN',
'',
'    IF :P2_MENU_NO IS NULL',
'    THEN',
'        INSERT INTO SA_MENU (MENU_NO,',
'                                    MENU_ID,',
'                                    MENU_NAME,',
'                                    DESCRIPTION,',
'                                    PARENT_MENU_NO,',
'                                    SL_NO,',
'                                    APP_ID,',
'                                    MENU_ICON,',
'                                    SS_CREATOR,',
'                                    SS_CREATED_ON)',
'             VALUES ( S_SA_MENU.NEXTVAL,',
'                     :P2_MENU_ID,',
'                     :P2_MENU_NAME,',
'                     :P2_DESCRIPTION,',
'                     :P2_PARENT_MENU_NO,',
'                     :P2_SL_NO,',
'                     :P2_APP_ID,',
'                     :P2_MENU_ICON,',
'                     :G_USER_NO,',
'                     --to_date(TO_CHAR (SYSDATE, ''DD-MON-YYYY HH24:MI:SS''))',
'                     SYSDATE',
'                    )',
'                      RETURNING MENU_NO into :P2_MENU_NO;',
'                --   :P1011_GREYFABSEND_NO := V_GREYFABSEND_NO;',
'    ELSE',
'        UPDATE SA_MENU',
'           SET MENU_ID = :P2_MENU_ID,',
'               MENU_NAME = :P2_MENU_NAME,',
'               DESCRIPTION = :P2_DESCRIPTION,',
'               PARENT_MENU_NO =:P2_PARENT_MENU_NO,',
'               SL_NO =:P2_SL_NO,',
'               MENU_ICON = :P2_MENU_ICON,',
'               SS_MODIFIER = :G_USER_NO',
'               WHERE MENU_NO =:P2_MENU_NO;',
