 p_id=>wwv_flow_imp.id(8034944816752538105)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(24034016306736744558)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SUB-MENU-ENTRY - Save Interactive Grid Data'
,p_static_id=>'sub-menu-entry-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 7/3/2024 10:40:52 AM (QP5 v5.326) */',
'DECLARE ',
'V_PK_NO NUMBER ;',
'',
'BEGIN',
'    CASE :APEX$ROW_STATUS',
'        WHEN ''C''',
'        THEN',
'        SELECT MAX(NVL(SUBMENU_NO,0))+1 INTO V_PK_NO FROM SA_SUBMENU;',
'            INSERT INTO SA_SUBMENU (SUBMENU_NO,',
'                                    APEX_PAGE_NO,',
'                                    SUBMENU_ID,',
'                                    MENU_NO,',
'                                    SUBMENU_NAME,',
'                                    SUBMENU_TYPE,',
'                                    ACTIVE_FLAG,',
'                                    HIDE_FROM_MENU,',
'                                    DESCROPTION,',
'                                    SUBMENU_ICON,',
'                                    SL_NO)',
'                 VALUES (V_PK_NO,',
'                         :APEX_PAGE_NO,',
'                         :P2_MENU_ID ||''-''||:SUBMENU_TYPE || LPAD(:APEX_PAGE_NO, 4, ''0''),',
'                         :P2_MENU_NO,',
'                         :SUBMENU_NAME,',
'                         :SUBMENU_TYPE,',
'                         :ACTIVE_FLAG,',
'                         :HIDE_FROM_MENU,',
'                         :DESCROPTION,',
'                         :SUBMENU_ICON,',
'                         :SL_NO)',
'              RETURNING SUBMENU_NO',
'                   INTO :SUBMENU_NO;',
'        WHEN ''U''',
'        THEN',
'            UPDATE SA_SUBMENU',
'               SET APEX_PAGE_NO = :APEX_PAGE_NO,',
'                   SUBMENU_ID   = :P2_MENU_ID ||''-''||:SUBMENU_TYPE || LPAD(:APEX_PAGE_NO, 4, ''0''),',
'                   SUBMENU_NAME = :SUBMENU_NAME,',
'                   SUBMENU_TYPE = :SUBMENU_TYPE,',
'                   ACTIVE_FLAG = :ACTIVE_FLAG,',
'                   HIDE_FROM_MENU = :HIDE_FROM_MENU,',
'                   DESCROPTION = :DESCROPTION,',
'                   SUBMENU_ICON = :SUBMENU_ICON,',
'                   SL_NO        = :SL_NO',
'             WHERE SUBMENU_NO = :SUBMENU_NO;',
'        WHEN ''D''',
'        THEN',
'            DELETE SA_SUBMENU',
'             WHERE SUBMENU_NO = :SUBMENU_NO;',
'    END CASE;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8034944816752538105
);
end;
