,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  S.SUBMENU_NO,',
'  S.SUBMENU_ID,',
'  S.MENU_NO,',
'  S.SUBMENU_NAME,',
'  S.SUBMENU_TYPE,',
'  S.ACTIVE_FLAG,',
'  S.CAN_VIEW,',
'  S.CAN_MODIFY,',
'  S.CAN_REMOVE,',
'  S.CAN_CREATE',
'FROM SA_SUBMENU S',
'WHERE NOT EXISTS (',
'  SELECT 1 ',
'  FROM SA_GRANTOBJECT G',
'  WHERE G.SUBMENU_NO = S.SUBMENU_NO',
'    AND G.USER_NO = TO_NUMBER(REGEXP_SUBSTR(:P4_P_USER_NO, ''\d+''))',
');',
