,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(24286731061622956339)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Supplier Setup'
,p_static_id=>'initialize-form-supplier-setup'
,p_internal_uid=>8111264929230426309
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8111272596661426323)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'BEGIN',
'    IF :P5_CATEGORY_NO IS NULL',
'    THEN',
'        INSERT INTO MST_PRODUCT_CATEGORY (CATEGORY_NO,',
'                                          CATEGORY_CODE,',
'                                          CATEGORY_NAME,',
'                                          ACTIVE_FLAG,',
'                                          CREATED_BY,',
'                                          CREATED_DATE)',
'             VALUES (SEQ_CATEGORY_NO.NEXTVAL,',
'                     ''CAT'' || LPAD (SEQ_CATEGORY_NO.NEXTVAL, 4, ''0''),',
'                     :P5_CATEGORY_NAME,',
'                     NVL ( :P5_ACTIVE_FLAG, ''Y''),',
'                     :APP_USER,',
'                     SYSDATE);',
'',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Product Category has been saved successfully.'';',
'    ELSE',
'        UPDATE MST_PRODUCT_CATEGORY',
'           SET CATEGORY_NAME = :P5_CATEGORY_NAME,',
'               ACTIVE_FLAG = :P5_ACTIVE_FLAG,',
'               UPDATED_BY = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE CATEGORY_NO = :P5_CATEGORY_NO;',
'',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Product Category has been updated successfully.'';',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8111272596661426323
);
end;
