wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(8068830215791255927)
,p_plug_name=>'SUPPLIER SUMMERY'
,p_static_id=>'entry'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/1/2026 4:19:12 PM (QP5 v5.388) */',
'DECLARE',
'    v_html                CLOB;',
'',
'    v_total_supplier      NUMBER := 0;',
'    v_active_supplier     NUMBER := 0;',
'    v_inactive_supplier   NUMBER := 0;',
'    v_total_due           NUMBER := 0;',
'    v_total_payment       NUMBER := 0;',
'BEGIN',
'    /* ============================================================',
'       SUPPLIER COUNT',
'       ============================================================ */',
'',
'    SELECT COUNT (*),',
'           NVL (SUM (CASE WHEN ACTIVE_FLAG = 1 THEN 1 ELSE 0 END), 0),',
'           NVL (SUM (CASE WHEN ACTIVE_FLAG = 0 THEN 1 ELSE 0 END), 0)',
'      INTO v_total_supplier, v_active_supplier, v_inactive_supplier',
'      FROM MST_SUPPLIER;',
'',
'',
'    /* ============================================================',
'       TOTAL DUE & TOTAL PAYMENT',
'       ============================================================ */',
'',
'    SELECT NVL (SUM (DUE_AMOUNT), 0), NVL (SUM (PAID_AMOUNT), 0)',
'      INTO v_total_due, v_total_payment',
'      FROM TRN_PURCHASE_MST;',
'',
'',
'    /* ============================================================',
'       HTML',
'       ============================================================ */',
'',
'    v_html :=',
'           ''<style>',
'',
'        .cust-kpi-wrapper {',
'            display:grid;',
'            grid-template-columns:repeat(5,1fr);',
'            gap:12px;',
'            width:100%;',
'            box-sizing:border-box;',
'        }',
'',
'        .cust-kpi-card {',
'            height:64px;',
'            min-height:64px;',
'            border:1px solid #dfe5eb;',
'            border-radius:8px;',
'            padding:8px 13px;',
'            box-sizing:border-box;',
'',
'            display:flex;',
'            align-items:center;',
'            gap:11px;',
'',
'            background:#fff;',
'        }',
'',
'        .cust-kpi-icon {',
'            width:34px;',
'            height:34px;',
'            min-width:34px;',
'',
'            border-radius:7px;',
'',
'            display:flex;',
'            align-items:center;',
'            justify-content:center;',
'',
'            font-size:15px;',
'        }',
'',
'        .cust-kpi-content {',
'            min-width:0;',
'        }',
'',
'        .cust-kpi-title {',
'            font-size:12px;',
'            line-height:15px;',
'            color:#6b7a8c;',
'            margin:0 0 2px 0;',
'            font-weight:400;',
'        }',
'',
'        .cust-kpi-value {',
'            font-size:19px;',
'            line-height:21px;',
'            font-weight:700;',
'            margin:0;',
'        }',
'',
'',
'        /* TOTAL SUPPLIERS */',
'',
'        .cust-total {',
'            background:#f7fafc;',
'        }',
'',
'        .cust-total .cust-kpi-icon {',
'            background:#e8f1fa;',
'            color:#286596;',
'        }',
'',
'        .cust-total .cust-kpi-value {',
'            color:#286596;',
'        }',
'',
'',
'        /* ACTIVE SUPPLIERS */',
'',
'        .cust-active {',
'            background:#f7fbf8;',
'        }',
'',
'        .cust-active .cust-kpi-icon {',
'            background:#e8f6ec;',
'            color:#21894d;',
'        }',
'',
'        .cust-active .cust-kpi-value {',
'            color:#21894d;',
'        }',
'',
'',
'        /* INACTIVE SUPPLIERS */',
'',
'        .cust-inactive {',
'            background:#fff8f8;',
'        }',
'',
'        .cust-inactive .cust-kpi-icon {',
'            background:#fdeaea;',
'            color:#d03930;',
'        }',
'',
'        .cust-inactive .cust-kpi-value {',
'            color:#d03930;',
'        }',
'',
'',
'        /* TOTAL DUE */',
'',
'        .cust-due {',
'            background:#fffdf7;',
'        }',
'',
'        .cust-due .cust-kpi-icon {',
'            background:#fff3d6;',
'            color:#bd7b16;',
'        }',
'',
'        .cust-due .cust-kpi-value {',
'            color:#bd7b16;',
'        }',
'',
'',
'        /* TOTAL PAYMENT */',
'',
'        .cust-payment {',
'            background:#f7f9ff;',
