wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(12002527358732043)
,p_plug_name=>'SUPPLIER SUMMERY'
,p_static_id=>'new'
,p_region_name=>'SUPPLIER_DETAILS'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/1/2026 4:32:11 PM (QP5 v5.388) */',
'/* ============================================================',
'   SUPPLIER DETAILS CARD',
'   ============================================================ */',
'',
'DECLARE',
'    v_html             CLOB;',
'',
'    v_supplier_name    VARCHAR2 (300);',
'    v_supplier_code    VARCHAR2 (50);',
'    v_mobile           VARCHAR2 (50);',
'    v_email            VARCHAR2 (200);',
'    v_address          VARCHAR2 (500);',
'    v_status           VARCHAR2 (20);',
'    v_since            VARCHAR2 (30);',
'',
'    v_orders           NUMBER := 0;',
'    v_total_purchase   NUMBER := 0;',
'    v_due_amount       NUMBER := 0;',
'BEGIN',
'    /* ============================================================',
'       NO SUPPLIER SELECTED',
'       ============================================================ */',
'',
'    IF :P7_SUPPLIER_NO IS NULL',
'    THEN',
'        RETURN ''',
'        <style>',
'',
'            .cust-empty{',
'                height:150px;',
'                display:flex;',
'                flex-direction:column;',
'                align-items:center;',
'                justify-content:center;',
'                color:#9aa5b1;',
'                font-size:13px;',
'                text-align:center;',
'            }',
'',
'            .cust-empty i{',
'                font-size:30px;',
'                margin-bottom:8px;',
'                color:#cbd2da;',
'            }',
'',
'        </style>',
'',
'        <div class="cust-empty">',
'',
'            <i class="fa fa-user"></i>',
'',
'            <div>Select a Supplier to view details</div>',
'',
'        </div>'';',
'    END IF;',
'',
'',
'    /* ============================================================',
'       SUPPLIER INFORMATION',
'       ============================================================ */',
'',
'    SELECT SUPPLIER_NAME,',
'           SUPPLIER_CODE,',
'           MOBILE_NO,',
'           EMAIL_ADDRESS,',
'           ADDRESS,',
'           CASE WHEN ACTIVE_FLAG = 1 THEN ''ACTIVE'' ELSE ''INACTIVE'' END,',
'           TO_CHAR (CREATED_DATE, ''DD-Mon-YYYY'')',
'      INTO v_supplier_name,',
'           v_supplier_code,',
'           v_mobile,',
'           v_email,',
'           v_address,',
'           v_status,',
'           v_since',
'      FROM MST_SUPPLIER',
'     WHERE SUPPLIER_NO = :P7_SUPPLIER_NO;',
'',
'',
'    /* ============================================================',
'       PURCHASE SUMMARY',
'       ============================================================ */',
'',
'    SELECT COUNT (*), NVL (SUM (TOTAL_AMOUNT), 0), NVL (SUM (DUE_AMOUNT), 0)',
'      INTO v_orders, v_total_purchase, v_due_amount',
'      FROM TRN_PURCHASE_MST',
'     WHERE SUPPLIER_NO = :P7_SUPPLIER_NO;',
'',
'',
'    /* ============================================================',
'       HTML',
'       ============================================================ */',
'',
'    v_html :=',
'           ''<style>',
'',
'        .customer-mini-card{',
'            width:100%;',
'            background:#ffffff;',
'            border:1px solid #e3e7ec;',
'            border-radius:9px;',
'            overflow:hidden;',
'            box-sizing:border-box;',
'            font-family:Arial,sans-serif;',
'        }',
'',
'',
'        /* EMPTY */',
'',
'        .cust-empty{',
'            height:150px;',
'            display:flex;',
'            flex-direction:column;',
'            align-items:center;',
'            justify-content:center;',
'            color:#9aa5b1;',
'            font-size:13px;',
'            text-align:center;',
'        }',
'',
'        .cust-empty i{',
'            font-size:30px;',
'            margin-bottom:8px;',
'            color:#cbd2da;',
'        }',
'',
'',
'        /* HEADER */',
'',
'        .cust-head{',
'            padding:10px 12px;',
'            border-bottom:1px solid #edf0f3;',
'            display:flex;',
'            align-items:center;',
'            justify-content:space-between;',
'            gap:8px;',
'        }',
'',
'',
'        .cust-profile{',
'            display:flex;',
'            align-items:center;',
'            min-width:0;',
'        }',
'',
'',
'        .cust-avatar{',
'            width:38px;',
'            height:38px;',
'            min-width:38px;',
'            border-radius:50%;',
'            background:#e5f7f4;',
'            color:#14877f;',
'            display:flex;',
'            align-items:center;',
'            justify-content:center;',
'            font-size:14px;',
'            font-weight:700;',
'            margin-right:9px;',
'        }',
'',
'',
'        .cust-name{',
'            font-size:14px;',
'            font-weight:700;',
'            color:#172033;',
'            white-space:nowrap;',
'            overflow:hidden;',
'            text-overflow:ellipsis;',
'        }',
'',
'',
'        .cust-code{',
'            font-size:10px;',
'            color:#8a94a3;',
'            margin-top:2px;',
'        }',
'',
'',
'        /* STATUS */',
'',
'        .cust-status{',
'            font-size:9px;',
'            font-weight:700;',
'            padding:4px 8px;',
'            border-radius:10px;',
'            white-space:nowrap;',
'        }',
'',
'',
'        .cust-active{',
'            background:#e5f8ee;',
'            color:#16834b;',
'        }',
'',
'',
'        .cust-inactive{',
'            background:#fdecec;',
'            color:#c93636;',
'        }',
'',
'',
'        /* INFORMATION */',
'',
'        .cust-info{',
'            padding:7px 12px;',
'            border-bottom:1px solid #edf0f3;',
'        }',
'',
'',
'        .cust-info-row{',
'            display:flex;',
'            align-items:center;',
'            gap:8px;',
'            margin:6px 0;',
'            color:#5f6b79;',
'            font-size:11px;',
'        }',
'',
'',
'        .cust-info-row i{',
'            width:15px;',
'            text-align:center;',
'            color:#8c98a7;',
'            font-size:11px;',
'        }',
'',
'',
'        .cust-info-text{',
'            overflow:hidden;',
'            text-overflow:ellipsis;',
'            white-space:nowrap;',
'        }',
'',
'',
'        /* SUMMARY */',
'',
'        .cust-summary{',
'            display:grid;',
'            grid-template-columns:1fr 1fr 1fr;',
'            gap:7px;',
'            padding:8px 12px;',
'        }',
'',
'',
'        .cust-stat{',
'            background:#f7f9fc;',
'            border-radius:6px;',
'            padding:7px 9px;',
'        }',
'',
'',
'        .cust-stat-label{',
'            font-size:8px;',
'            color:#7b8796;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.3px;',
'        }',
'',
'',
'        .cust-stat-value{',
'            margin-top:3px;',
'            font-size:12px;',
'            font-weight:700;',
'            color:#172033;',
'        }',
'',
'',
'        /* PURCHASE */',
'',
'        .cust-purchase{',
'            color:#286596;',
'        }',
'',
'',
'        /* DUE */',
'',
'        .cust-due{',
'            color:#bd7b16;',
'        }',
'',
'',
'        /* ORDERS */',
'',
'        .cust-orders{',
'            color:#14877f;',
'        }',
'',
'',
'        @media(max-width:600px){',
'',
'            .cust-name{',
'                max-width:140px;',
'            }',
'',
'            .cust-summary{',
'                grid-template-columns:1fr 1fr;',
'            }',
'',
'            .cust-stat:last-child{',
'                grid-column:span 2;',
'            }',
'',
'        }',
'',
'    </style>',
'',
'',
'    <div class="customer-mini-card">',
'',
'',
'        <!-- HEADER -->',
'',
'        <div class="cust-head">',
'',
'            <div class="cust-profile">',
'',
'                <div class="cust-avatar">''',
'        || UPPER (SUBSTR (v_supplier_name, 1, 1))',
'        || ''</div>',
'',
'                <div>',
'',
'                    <div class="cust-name">''',
'        || APEX_ESCAPE.HTML (v_supplier_name)',
'        || ''</div>',
'',
'                    <div class="cust-code">''',
'        || APEX_ESCAPE.HTML (v_supplier_code)',
'        || '' &bull; Since ''',
'        || v_since',
'        || ''</div>',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <div class="cust-status ''',
'        || CASE',
'               WHEN v_status = ''ACTIVE'' THEN ''cust-active''',
'               ELSE ''cust-inactive''',
'           END',
'        || ''">''',
'        || v_status',
'        || ''</div>',
'',
'        </div>',
'',
'',
'        <!-- SUPPLIER INFORMATION -->',
'',
'        <div class="cust-info">',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-phone"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_mobile, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-envelope"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_email, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'            <div class="cust-info-row">',
'',
'                <i class="fa fa-map-marker"></i>',
'',
'                <span class="cust-info-text">''',
'        || APEX_ESCAPE.HTML (NVL (v_address, ''-''))',
'        || ''</span>',
'',
'            </div>',
'',
'',
'        </div>',
'',
'',
'        <!-- SUMMARY -->',
'',
'        <div class="cust-summary">',
'',
'',
'            <!-- PURCHASE -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Total Purchase',
'                </div>',
'',
'                <div class="cust-stat-value cust-purchase">',
'',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_total_purchase,',
'                    ''FM999999999999990D00'',',
'                    ''NLS_NUMERIC_CHARACTERS=''''.,'''''')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- DUE -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Due Amount',
'                </div>',
'',
'                <div class="cust-stat-value cust-due">',
'',
unistr('                    \09F3 '''),
'        || TO_CHAR (v_due_amount,',
'                    ''FM999999999999990D00'',',
'                    ''NLS_NUMERIC_CHARACTERS=''''.,'''''')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'            <!-- ORDERS -->',
'',
'            <div class="cust-stat">',
'',
'                <div class="cust-stat-label">',
'                    Total Purchases',
'                </div>',
'',
'                <div class="cust-stat-value cust-orders">',
'',
'                    ''',
'        || TO_CHAR (v_orders, ''FM999999999999990'')',
'        || ''',
'',
'                </div>',
'',
'            </div>',
'',
'',
'        </div>',
'',
'',
'    </div>'';',
'',
'',
'    RETURN v_html;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        RETURN ''',
'        <div class="cust-empty">',
'',
'            <i class="fa fa-user-times"></i>',
'',
'            <div>Supplier not found</div>',
'',
'        </div>'';',
'    WHEN OTHERS',
'    THEN',
'        RETURN ''',
'        <div class="cust-empty">',
'',
'            <i class="fa fa-exclamation-circle"></i>',
'',
'            <div>Unable to load supplier details</div>',
'',
'        </div>'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P7_SUPPLIER_NO'
,p_created_on=>wwv_flow_imp.dz('20260831111451Z')
,p_updated_on=>wwv_flow_imp.dz('20260901163404Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
