wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8068831674916255941)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P7_SUPPLIER_NO IS NULL THEN',
'',
'        INSERT INTO MST_SUPPLIER',
'        (',
'            SUPPLIER_NO,',
'            SUPPLIER_CODE,',
'            SUPPLIER_NAME,',
'            CONTACT_PERSON,',
'            MOBILE_NO,',
'            EMAIL_ADDRESS,',
'            ADDRESS,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_SUPPLIER_NO.NEXTVAL,',
'           ''SUP'' || LPAD(SEQ_SUPPLIER_NO.NEXTVAL,4,''0''),',
'            :P7_SUPPLIER_NAME,',
'            :P7_CONTACT_PERSON,',
'            :P7_MOBILE_NO,',
'            :P7_EMAIL_ADDRESS,',
'            :P7_ADDRESS,',
'            NVL(:P7_ACTIVE_FLAG,''Y''),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Supplier saved successfully.'';',
'',
'    ELSE',
'',
'        UPDATE MST_SUPPLIER',
'           SET ',
'               SUPPLIER_NAME  = :P7_SUPPLIER_NAME,',
'               CONTACT_PERSON = :P7_CONTACT_PERSON,',
'               MOBILE_NO      = :P7_MOBILE_NO,',
'               EMAIL_ADDRESS  = :P7_EMAIL_ADDRESS,',
'               ADDRESS        = :P7_ADDRESS,',
'               ACTIVE_FLAG    = :P7_ACTIVE_FLAG,',
'               UPDATED_BY     = :APP_USER,',
'               UPDATED_DATE   = SYSDATE',
'         WHERE SUPPLIER_NO = :P7_SUPPLIER_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Supplier updated successfully.'';',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8252968279474032)
,p_internal_uid=>8068831674916255941
);
end;
