wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(16175475513232530063)
,p_plug_name=>'Register'
,p_static_id=>'CUSTOMER_REPORT'
,p_region_name=>'CUSTOMER_REPORT'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_grid_column_span=>8
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       C.CUSTOMER_NO,',
'       C.CUSTOMER_CODE,',
'       C.CUSTOMER_NAME,',
'       C.CONTACT_PERSON,',
'       C.MOBILE_NO,',
'       C.EMAIL_ADDRESS,',
'       C.ADDRESS,',
'       C.ACTIVE_FLAG,',
'       DECODE(',
'           C.ACTIVE_FLAG,',
'           1, ''Active'',',
'           0, ''Inactive''',
'       ) AS STATUS,',
'',
'       NVL(D.DUE_AMOUNT, 0) AS DUE_AMOUNT,',
'',
'       CASE',
'           WHEN NVL(D.DUE_AMOUNT, 0) > 0',
unistr('           THEN ''\26A0 Due'''),
unistr('           ELSE ''\2713 Clear'''),
'       END AS DUE_STATUS,',
'',
'       C.CREATED_BY,',
'       C.CREATED_DATE,',
'       C.UPDATED_BY,',
'       C.UPDATED_DATE',
'',
'  FROM MST_CUSTOMER C',
'',
'  LEFT JOIN',
'  (',
'      SELECT',
'             CUSTOMER_NO,',
'             SUM(NVL(DUE_AMOUNT, 0)) AS DUE_AMOUNT',
'        FROM TRN_SALES_INVOICE_MST',
'       GROUP BY CUSTOMER_NO',
'  ) D',
'    ON D.CUSTOMER_NO = C.CUSTOMER_NO',
'',
' WHERE',
'       (',
'           :P8_DUE_FILTER IS NULL',
'           OR :P8_DUE_FILTER = ''''',
'           OR',
'           (',
'               :P8_DUE_FILTER = ''DUE''',
'               AND NVL(D.DUE_AMOUNT, 0) > 0',
'           )',
'       )',
'',
' ORDER BY',
'       C.CUSTOMER_NAME'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P8_DUE_FILTER'
