'            background:#fffdf7;',
'        }',
'',
'        .cust-due .cust-kpi-icon {',
'            background:#fff3d6;',
'            color:#bd7b16;',
'        }',
'',
'        .cust-due .cust-kpi-value {',
'            color:#bd7b16;',
'        }',
'',
'',
'        /* TOTAL RECEIVED */',
'',
