wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8106661993832274161)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P8_CUSTOMER_NO IS NULL THEN',
'',
'        INSERT INTO MST_CUSTOMER',
'        (',
'            CUSTOMER_NO,',
'            CUSTOMER_CODE,',
'            CUSTOMER_NAME,',
'            CONTACT_PERSON,',
'            MOBILE_NO,',
'            EMAIL_ADDRESS,',
'            ADDRESS,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_CUSTOMER_NO.NEXTVAL,',
'               ''CUS'' || LPAD(SEQ_CUSTOMER_NO.NEXTVAL,4,''0''),',
'            :P8_CUSTOMER_NAME,',
'            :P8_CONTACT_PERSON,',
'            :P8_MOBILE_NO,',
'            :P8_EMAIL_ADDRESS,',
'            :P8_ADDRESS,',
'            NVL(:P8_ACTIVE_FLAG,''Y''),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Customer information has been saved successfully.'';',
'',
'    ELSE',
'',
'        UPDATE MST_CUSTOMER',
'           SET ',
'               CUSTOMER_NAME  = :P8_CUSTOMER_NAME,',
'               CONTACT_PERSON = :P8_CONTACT_PERSON,',
'               MOBILE_NO      = :P8_MOBILE_NO,',
'               EMAIL_ADDRESS  = :P8_EMAIL_ADDRESS,',
'               ADDRESS        = :P8_ADDRESS,',
'               ACTIVE_FLAG    = :P8_ACTIVE_FLAG,',
'               UPDATED_BY     = :APP_USER,',
'               UPDATED_DATE   = SYSDATE',
'         WHERE CUSTOMER_NO = :P8_CUSTOMER_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Customer information has been updated successfully.'';',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8257482856491562)
,p_internal_uid=>8106661993832274161
,p_updated_on=>wwv_flow_imp.dz('20260901162158Z')
,p_updated_by=>'ADMIN'
);
end;
