wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8129056810661016221)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(40537135959392022345)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Supplier Setup'
,p_static_id=>'initialize-form-supplier-setup'
,p_internal_uid=>8129056810661016221
