wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(16807050088670628304)
,p_plug_name=>'Current Stock'
,p_static_id=>'register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM',
'(',
'    SELECT',
'           P.PRODUCT_NO,',
'           P.PRODUCT_CODE,',
'           P.PRODUCT_NAME,',
'           C.CATEGORY_NAME,',
'',
'           /* Product / Base UOM */',
'           BASE_UOM.UOM_NAME AS BASE_UOM,',
'',
'           /* Stock UOM */',
'           NVL(',
'               STOCK_UOM.UOM_NAME,',
'               BASE_UOM.UOM_NAME',
'           ) AS STOCK_UOM,',
'',
'           /* Conversion */',
'',
'/* Correct UOM Conversion */',
'CASE',
'    WHEN UC.CONVERSION_FACTOR IS NOT NULL',
'         AND UC.CONVERSION_FACTOR > 0',
'    THEN',
'        ''1 '' ||',
'        STOCK_UOM.UOM_NAME ||',
'        '' = '' ||',
'        TO_CHAR(UC.CONVERSION_FACTOR) ||',
'        '' '' ||',
'        BASE_UOM.UOM_NAME',
'    ELSE',
'        ''1 '' ||',
'        BASE_UOM.UOM_NAME ||',
'        '' = 1 '' ||',
'        BASE_UOM.UOM_NAME',
'END AS UOM_CONVERSION,',
'',
'',
'',
'           /* Purchase Rate per Base UOM */',
'           NVL(P.PURCHASE_RATE,0) AS PURCHASE_RATE,',
'',
'           /* Purchase Rate per Stock UOM */',
'           ROUND(',
'               NVL(P.PURCHASE_RATE,0)',
'               /',
'               NULLIF(',
'                   NVL(UC.CONVERSION_FACTOR,1),',
'                   0',
'               ),',
'               2',
'           ) AS STOCK_RATE,',
'',
'           /* Existing Product Sales Rate */',
'           NVL(P.SALES_RATE,0) AS SALES_RATE,',
'',
'           /* Minimum Stock */',
'           NVL(P.MIN_STOCK_QTY,0) AS MIN_STOCK_QTY,',
'',
'           /* Stock In */',
'           NVL(',
'               SUM(NVL(L.QTY_IN,0)),',
'               0',
'           ) AS STOCK_IN,',
'',
'           /* Stock Out */',
'           NVL(',
'               SUM(NVL(L.QTY_OUT,0)),',
'               0',
'           ) AS STOCK_OUT,',
'',
'           /* Current Stock */',
'           NVL(',
'               SUM(NVL(L.QTY_IN,0))',
'               -',
'               SUM(NVL(L.QTY_OUT,0)),',
'               0',
'           ) AS CURRENT_STOCK,',
'',
'           /* Stock Value */',
'           ROUND(',
'               NVL(',
'                   SUM(NVL(L.QTY_IN,0))',
'                   -',
'                   SUM(NVL(L.QTY_OUT,0)),',
'                   0',
'               )',
'               *',
'               (',
'                   NVL(P.PURCHASE_RATE,0)',
'                   /',
'                   NULLIF(',
'                       NVL(UC.CONVERSION_FACTOR,1),',
'                       0',
'                   )',
'               ),',
'               2',
'           ) AS STOCK_VALUE,',
'',
'           /* Stock Status */',
'           CASE',
'               WHEN NVL(',
'                        SUM(NVL(L.QTY_IN,0))',
'                        -',
'                        SUM(NVL(L.QTY_OUT,0)),',
'                        0',
'                    ) <= 0',
'               THEN',
'                   ''<span style="',
'                       display:inline-block;',
'                       background:#fee2e2;',
'                       color:#b91c1c;',
'                       border:1px solid #fecaca;',
'                       padding:2px 8px;',
'                       border-radius:12px;',
'                       font-size:11px;',
'                       font-weight:600;',
'                       white-space:nowrap;">',
'                       Out of Stock',
'                    </span>''',
'',
'               WHEN NVL(',
'                        SUM(NVL(L.QTY_IN,0))',
'                        -',
'                        SUM(NVL(L.QTY_OUT,0)),',
'                        0',
'                    ) < NVL(P.MIN_STOCK_QTY,0)',
'               THEN',
'                   ''<span style="',
'                       display:inline-block;',
'                       background:#fef3c7;',
'                       color:#b45309;',
'                       border:1px solid #fde68a;',
'                       padding:2px 8px;',
'                       border-radius:12px;',
'                       font-size:11px;',
'                       font-weight:600;',
'                       white-space:nowrap;">',
'                       Low Stock',
'                    </span>''',
'',
'               ELSE',
'                   ''<span style="',
'                       display:inline-block;',
'                       background:#dcfce7;',
'                       color:#15803d;',
'                       border:1px solid #bbf7d0;',
'                       padding:2px 8px;',
'                       border-radius:12px;',
'                       font-size:11px;',
'                       font-weight:600;',
'                       white-space:nowrap;">',
'                       Available',
'                    </span>''',
'           END AS STOCK_STATUS,',
'',
'           /* Status Icon */',
'           CASE',
'               WHEN NVL(',
'                        SUM(NVL(L.QTY_IN,0))',
'                        -',
'                        SUM(NVL(L.QTY_OUT,0)),',
'                        0',
'                    ) <= 0',
'               THEN',
'                   ''<span class="fa fa-times-circle"',
'                          style="',
'                              color:#dc2626;',
'                              font-size:13px;',
'                              vertical-align:middle;',
'                              line-height:1;"',
'                          title="Out of Stock">',
'                    </span>''',
'',
'               WHEN NVL(',
'                        SUM(NVL(L.QTY_IN,0))',
'                        -',
'                        SUM(NVL(L.QTY_OUT,0)),',
'                        0',
'                    ) < NVL(P.MIN_STOCK_QTY,0)',
'               THEN',
'                   ''<span class="fa fa-exclamation-triangle"',
'                          style="',
'                              color:#f59e0b;',
'                              font-size:13px;',
'                              vertical-align:middle;',
'                              line-height:1;"',
'                          title="Low Stock">',
'                    </span>''',
'',
'               ELSE',
'                   ''<span class="fa fa-check-circle"',
'                          style="',
'                              color:#16a34a;',
'                              font-size:13px;',
'                              vertical-align:middle;',
'                              line-height:1;"',
'                          title="Available">',
'                    </span>''',
'           END AS STATUS_ICON',
'',
'    FROM MST_PRODUCT P',
'',
'    /* Category */',
'    LEFT JOIN MST_PRODUCT_CATEGORY C',
'           ON C.CATEGORY_NO = P.CATEGORY_NO',
'',
'    /* Stock Ledger */',
'    LEFT JOIN TRN_STOCK_LEDGER L',
'           ON L.PRODUCT_NO = P.PRODUCT_NO',
'',
'    /* UOM Conversion */',
'    LEFT JOIN MST_UOM_CONVERSION UC',
'           ON UC.PRODUCT_NO = P.PRODUCT_NO',
'          AND UC.BASE_UOM_NO = P.UOM_NO',
'          AND UC.ACTIVE_FLAG = ''1''',
'          AND UC.CONVERSION_FACTOR > 0',
'',
'    /* Base UOM */',
'    LEFT JOIN MST_UOM BASE_UOM',
'           ON BASE_UOM.UOM_NO = P.UOM_NO',
'',
'    /* Stock / Convert UOM */',
'    LEFT JOIN MST_UOM STOCK_UOM',
'           ON STOCK_UOM.UOM_NO = UC.CONVERT_UOM_NO',
'',
'    WHERE (:P10_CATEGORY_NO IS NULL',
'           OR P.CATEGORY_NO = :P10_CATEGORY_NO)',
'',
'      AND (:P10_PRODUCT_NO IS NULL',
'           OR P.PRODUCT_NO = :P10_PRODUCT_NO)',
'',
'    GROUP BY',
'           P.PRODUCT_NO,',
'           P.PRODUCT_CODE,',
'           P.PRODUCT_NAME,',
'           C.CATEGORY_NAME,',
'           BASE_UOM.UOM_NAME,',
'           STOCK_UOM.UOM_NAME,',
'           UC.CONVERSION_FACTOR,',
'           P.PURCHASE_RATE,',
'           P.SALES_RATE,',
'           P.MIN_STOCK_QTY',
')',
'WHERE',
'(',
'       :P10_STATUS IS NULL',
'',
'    OR (',
'        :P10_STATUS = ''A''',
'        AND CURRENT_STOCK >= MIN_STOCK_QTY',
'    )',
'',
'    OR (',
'        :P10_STATUS = ''L''',
'        AND CURRENT_STOCK > 0',
'        AND CURRENT_STOCK < MIN_STOCK_QTY',
'    )',
'',
'    OR (',
'        :P10_STATUS = ''O''',
'        AND CURRENT_STOCK <= 0',
'    )',
')',
'ORDER BY PRODUCT_NAME;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P10_CATEGORY_NO,P10_PRODUCT_NO,P10_STATUS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
