,p_is_default=>'Y'
,p_report_columns=>'PRODUCT_CODE:PRODUCT_NAME:CATEGORY_NAME:PURCHASE_RATE:SALES_RATE:MIN_STOCK_QTY:BASE_UOM:STOCK_UOM:STOCK_IN:STOCK_OUT:CURRENT_STOCK:UOM_CONVERSION:STOCK_RATE:STOCK_VALUE:STOCK_STATUS:STATUS_ICON'
