,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select M.PURCHASE_NO,',
'       M.PURCHASE_CODE,',
'       M.PURCHASE_DATE,',
'       M.SUPPLIER_NO,',
'       M.REMARKS,',
'       M.ACTIVE_FLAG,',
'       M.APPROVAL_STATUS,',
'       DECODE(M.APPROVAL_STATUS,''A'',''Approved'',''P'',''Pending'')APPROVAL,',
'       M.APPROVED_BY,',
'       M.APPROVED_DATE,',
'       M.PURCHASE_STATUS,',
'       M.RECEIVED_BY,',
'       M.RECEIVED_DATE,',
'       V.VOUCHER_CODE VOUCHER_NO,',
'       M.PAID_AMOUNT,',
'       M.DUE_AMOUNT,',
'       M.PAYMENT_STATUS,',
'       M.TOTAL_AMOUNT,',
'       S.MOBILE_NO,',
'       S.ADDRESS',
'  from TRN_PURCHASE_MST M,ACC_VOUCHER_MST V ,MST_SUPPLIER S   ',
'  WHERE M.VOUCHER_NO = V.VOUCHER_NO(+)',
'  AND M.SUPPLIER_NO = S.SUPPLIER_NO(+)'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
);
