wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8293111900604552013)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(16561534052090589351)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DETAILS ENTRY - Save Interactive Grid Data'
,p_static_id=>'details-entry-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    V_STATUS VARCHAR2(1);',
'',
'BEGIN',
'',
'    ----------------------------------------------------',
'    -- Approval Validation',
'    ----------------------------------------------------',
'    BEGIN',
'        SELECT APPROVAL_STATUS',
'          INTO V_STATUS',
'          FROM TRN_PURCHASE_MST',
'         WHERE PURCHASE_NO = :P12_PURCHASE_NO;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            V_STATUS := ''P'';',
'    END;',
'',
'    IF V_STATUS = ''A'' THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Approved purchase cannot be modified or deleted.''',
'        );',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- INSERT',
'    ----------------------------------------------------',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'        INSERT INTO TRN_PURCHASE_DTL',
'        (',
'            PURCHASE_DTL_NO,',
'            PURCHASE_NO,',
'            PRODUCT_NO,',
'            UOM_NO,',
'            PURCHASE_QTY,',
'            PURCHASE_RATE,',
'            PACK_QTY,',
'            BASE_QTY,',
'            BASE_RATE,',
'            TOTAL_AMOUNT,',
'            RECEIVED_QTY,',
'            BALANCE_QTY,',
'            REMARKS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_PURCHASE_DTL_NO.NEXTVAL,',
'            :P12_PURCHASE_NO,',
'            :PRODUCT_NO,',
'            :UOM_NO,',
'            :PURCHASE_QTY,',
'            :PURCHASE_RATE,',
'            :PACK_QTY,',
'            :BASE_QTY,',
'            :BASE_RATE,',
'            :TOTAL_AMOUNT,',
'            0,',
'            :BASE_QTY,',
'            :REMARKS,',
'            :APP_USER,',
'            SYSDATE',
'        )',
'        RETURNING PURCHASE_DTL_NO',
'             INTO :PURCHASE_DTL_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail saved successfully.'';',
'',
'    ----------------------------------------------------',
'    -- UPDATE',
'    ----------------------------------------------------',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'        UPDATE TRN_PURCHASE_DTL',
'           SET PRODUCT_NO    = :PRODUCT_NO,',
'               UOM_NO        = :UOM_NO,',
'               PURCHASE_QTY  = :PURCHASE_QTY,',
'               PURCHASE_RATE = :PURCHASE_RATE,',
'               PACK_QTY      = :PACK_QTY,',
'               BASE_QTY      = :BASE_QTY,',
'               BASE_RATE     = :BASE_RATE,',
'               TOTAL_AMOUNT  = :TOTAL_AMOUNT,',
'               BALANCE_QTY   = :BASE_QTY - NVL(RECEIVED_QTY,0),',
'               REMARKS       = :REMARKS,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE PURCHASE_DTL_NO = :PURCHASE_DTL_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail updated successfully.'';',
'',
'    ----------------------------------------------------',
'    -- DELETE',
'    ----------------------------------------------------',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'        DELETE',
'          FROM TRN_PURCHASE_DTL',
'         WHERE PURCHASE_DTL_NO = :PURCHASE_DTL_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Purchase detail deleted successfully.'';',
'',
'    END IF;',
'',
'    ----------------------------------------------------',
'    -- Update Header Total',
'    ----------------------------------------------------',
'    PKG_PURCHASE.UPDATE_TOTAL(:P12_PURCHASE_NO);',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RAISE_APPLICATION_ERROR(-20001, SQLERRM);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8292978620846895922)
,p_internal_uid=>8293111900604552013
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(18574585735790404015)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PACK_FACTOR'
,p_static_id=>'get-pack-factor'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    V_FACTOR NUMBER := 1;',
'',
'BEGIN',
'',
'    BEGIN',
'',
'        SELECT C.CONVERSION_FACTOR',
'          INTO V_FACTOR',
'          FROM MST_UOM_CONVERSION C',
'         WHERE C.PRODUCT_NO     = TO_NUMBER(APEX_APPLICATION.G_X01)',
'           AND C.CONVERT_UOM_NO = TO_NUMBER(APEX_APPLICATION.G_X02)',
'           AND C.ACTIVE_FLAG = ''Y'';',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'',
'            V_FACTOR := 1;',
'',
'    END;',
'',
'    HTP.P(V_FACTOR);',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>18574585735790404015
);
