wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(8293114631953552040)
,p_plug_name=>'PURCHASE_MST'
,p_static_id=>'register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT *',
'FROM',
'(',
'    SELECT',
'           M.PURCHASE_NO,',
'           M.PURCHASE_CODE,',
'           M.PURCHASE_DATE,',
'',
'           S.SUPPLIER_NAME,',
'',
'           M.TOTAL_AMOUNT,',
'           M.PAID_AMOUNT,',
'           M.DUE_AMOUNT,',
'',
'           CASE M.PAYMENT_STATUS',
'                WHEN ''UP'' THEN ''Unpaid''',
'                WHEN ''PP'' THEN ''Partially Paid''',
'                WHEN ''P''  THEN ''Paid''',
'           END AS PAYMENT_STATUS,',
'',
'           V.VOUCHER_CODE,',
'',
'           CASE M.APPROVAL_STATUS',
'                WHEN ''P'' THEN ''Pending''',
'                WHEN ''A'' THEN ''Approved''',
'                WHEN ''R'' THEN ''Rejected''',
'           END AS APPROVAL_STATUS,',
'',
'           M.CREATED_BY,',
'           M.CREATED_DATE,',
'           M.APPROVED_BY,',
'           M.APPROVED_DATE',
'',
'      FROM TRN_PURCHASE_MST M',
'',
'      JOIN MST_SUPPLIER S',
'        ON S.SUPPLIER_NO = M.SUPPLIER_NO',
'',
' LEFT JOIN ACC_VOUCHER_MST V',
'        ON V.VOUCHER_NO = M.VOUCHER_NO',
'',
'     WHERE ( :P13_STATUS = ''ALL''',
'          OR M.APPROVAL_STATUS = :P13_STATUS )',
'',
'     ORDER BY M.PURCHASE_NO DESC',
');'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P13_STATUS'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
