'',
'            width: 29px;',
'',
'            height: 29px;',
'',
'            border: 1px solid #dbe2ea;',
'',
'            border-radius: 5px;',
'',
'            background: #ffffff;',
'',
'            color: #64748b;',
'',
'            cursor: pointer;',
'',
'            font-size: 11px;',
'',
'            transition:',
'                all .15s ease;',
'        }',
'',
'',
'        .invoice-print-btn button:hover {',
'',
'            background: #2563eb;',
'',
'            color: #ffffff;',
'',
'            border-color: #2563eb;',
'',
'        }',
'',
'',
'        /* =========================================',
'           HEADER',
'           ========================================= */',
'',
'        .inv-header {',
'',
'            display: flex;',
'',
'            justify-content:',
'                space-between;',
