wwv_flow_imp_page.create_page(
 p_id=>16
,p_name=>'Purchase Approval'
,p_alias=>'PURCHASE-APPROVAL'
,p_step_title=>'Purchase Approval'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function f_openModal(purchaseNo){',
'',
'    apex.item("P16_PURCHASE_NO").setValue(purchaseNo);',
'',
'    openModal(''purchase_approve'');',
'',
'    apex.region(''purchase-detail'').refresh();',
'',
'}',
'',
'function approvePurchase(pPurchaseNo) {',
'',
'    apex.message.confirm(',
'        "Are you sure you want to approve this purchase?",',
'        function(okPressed) {',
'',
'            if (!okPressed) {',
'                return;',
'            }',
'',
'            apex.server.process(',
'                "APPROVE_PURCHASE",',
'                {',
'                    x01: pPurchaseNo',
'                },',
'                {',
'                    dataType: "text",',
'',
'                    success: function(pData) {',
'',
'                        if (pData.trim() === "SUCCESS") {',
'',
'                            /* Close Approval Modal */',
'                            closeModal("purchase_approve");',
'',
'                            /* Refresh Base Page Register */',
'                            apex.region("purchase-register").refresh();',
'',
'                        } else {',
'',
'                            apex.message.alert(pData);',
'',
'                        }',
'                    },',
'',
'                    error: function() {',
'',
'                        apex.message.alert(',
'                            "Unable to process request."',
'                        );',
'',
'                    }',
'                }',
'            );',
'        }',
'    );',
'}',
'',
'function rejectPurchase(pPurchaseNo){',
'',
'    if(!confirm(''Are you sure you want to reject this purchase?'')){',
'        return;',
'    }',
'',
'    apex.server.process(',
'        "REJECT_PURCHASE",',
'        {',
'            x01: pPurchaseNo',
'        },',
'        {',
'            dataType: "text",',
'            success: function(pData){',
'',
'                if(pData === "SUCCESS"){',
'',
'                    apex.message.showPageSuccess(',
'                        "Purchase rejected successfully."',
'                    );',
'',
'                     apex.region(''purchase-detail'').refresh();',
'                    apex.region(''purchase-register'').refresh();',
'',
'                }else{',
'',
'                    apex.message.alert(pData);',
'',
'                }',
'            },',
'            error: function(){',
'',
'                apex.message.alert(',
'                    "Unable to process request."',
'                );',
'',
'            }',
'        }',
'    );',
'',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'21'
,p_last_updated_on=>wwv_flow_imp.dz('20260908124244Z')
,p_last_updated_by=>'ADMIN'
);
