wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(16479660018293923)
,p_name=>'INVOICE_SUMMERY'
,p_static_id=>'new_1'
,p_region_name=>'INVOICE_SUMMERY'
,p_parent_plug_id=>wwv_flow_imp.id(17018187578027628311)
,p_template=>2102002977963900996
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH X AS',
'(',
'    SELECT',
'           I.INVOICE_NO,',
'           I.INVOICE_CODE,',
'           I.INVOICE_DATE,',
'           SUM(NVL(D.SALES_QTY,0)) AS INVOICE_QTY,',
'           SUM(NVL(D.TOTAL_AMOUNT,0)) AS INVOICE_AMOUNT,',
'           ROW_NUMBER() OVER',
'           (',
'               ORDER BY I.INVOICE_DATE DESC,',
'                        I.INVOICE_NO DESC',
'           ) AS RN',
'    FROM TRN_SALES_INVOICE_DTL D',
'         JOIN TRN_SALES_INVOICE_MST I',
'           ON I.INVOICE_NO = D.INVOICE_NO',
'    WHERE 1 = 1',
'      -- AND I.CUSTOMER_NO = :P17_CUSTOMER_NO',
'    GROUP BY',
'           I.INVOICE_NO,',
'           I.INVOICE_CODE,',
'           I.INVOICE_DATE',
')',
'SELECT RN SL,',
'       INVOICE_NO,',
'       INVOICE_CODE,',
'       INVOICE_DATE,',
'       INVOICE_QTY,',
'       INVOICE_AMOUNT',
'FROM X',
'WHERE RN <= 3',
'ORDER BY INVOICE_DATE DESC,',
'         INVOICE_NO DESC;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P17_PRODUCT_NO'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260913155148Z')
,p_updated_on=>wwv_flow_imp.dz('20260913164705Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
