wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(17018187578027628311)
,p_plug_name=>'SALES DTL '
,p_static_id=>'register_1'
,p_region_name=>'sales_dtl'
,p_parent_plug_id=>wwv_flow_imp.id(11518958736620411)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_grid_column_span=>9
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (',
'SELECT D.ORDER_DTL_NO,',
'       D.ORDER_NO,',
'       D.PRODUCT_NO,',
'       P.DESCRIPTION,',
'       P.BRAND_NO,',
'       P.PRODUCT_NAME,',
'       P.PRODUCT_CODE,',
'       D.UOM_NO,',
'       U.UOM_NAME,',
'       D.PACK_QTY,',
'       D.ORDER_QTY,',
'       D.BASE_QTY,',
'       D.SALES_RATE,',
'       D.BASE_RATE,',
'       D.TOTAL_AMOUNT,',
'       D.INVOICED_QTY,',
'       D.DELIVERED_QTY,',
'       D.BALANCE_QTY,',
'       D.DISCOUNT_PERCENT,',
'       D.DISCOUNT_AMOUNT,',
'       D. NET_AMOUNT,',
'       NVL(STK.STOCK_QTY, 0) AS STOCK_QTY,',
'       D.REMARKS,',
'       CASE',
'           WHEN M.ORDER_STATUS = ''P'' THEN ''UD''',
'           ELSE ''X''',
'       END AS ROW_STATUS,',
'       NULL AS DELETE_ROW',
'  FROM TRN_SALES_ORDER_DTL D',
'  JOIN TRN_SALES_ORDER_MST M',
'    ON M.ORDER_NO = D.ORDER_NO',
'  JOIN MST_PRODUCT P',
'    ON P.PRODUCT_NO = D.PRODUCT_NO',
'  LEFT JOIN MST_UOM U',
'    ON U.UOM_NO = D.UOM_NO',
'  LEFT JOIN',
'  (',
'      SELECT PRODUCT_NO,',
'             SUM(NVL(QTY_IN, 0))',
'             - SUM(NVL(QTY_OUT, 0)) AS STOCK_QTY',
'        FROM TRN_STOCK_LEDGER',
'       GROUP BY PRODUCT_NO',
'  ) STK',
'    ON STK.PRODUCT_NO = D.PRODUCT_NO',
' WHERE D.ORDER_NO = :P17_ORDER_NO',
'',
' ORDER BY D.ORDER_DTL_NO);'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P17_ORDER_NO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
