wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(20930157849815001)
,p_event_id=>wwv_flow_imp.id(20470747315467550)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '',
    '(function () {',
    '    var $received = $("#P17_RECEIVED_AMOUNT");',
    '    var $save = $("#pb-save");',
    '',
    '    if (window.posPaymentValidationBound) {',
    '        return;',
    '    }',
    '    window.posPaymentValidationBound = true;',
    '',
    '    var paymentConfirmed = false;',
    '    var confirming = false;',
    '',
    '    function validatePayment() {',
    '        var netPay = parseFloat(',
    '            String($v("P17_PAYABLE_AMOUNT") || "0").replace(/,/g, "")',
    '        ) || 0;',
    '',
    '        var receivedAmnt = parseFloat(',
    '            String($v("P17_RECEIVED_AMOUNT") || "0").replace(/,/g, "")',
    '        ) || 0;',
    '',
    '        var $return = $("#P17_RETURN_AMOUNT");',
    '',
    '        $received.removeClass("received-error received-ok");',
    '        $return.removeClass("change-ok change-zero");',
    '',
    '        if (receivedAmnt < netPay) {',
    '            $received.addClass("received-error");',
    '            $s("P17_RETURN_AMOUNT", "0.00");',
    '            $return.addClass("change-zero");',
    '',
    '            apex.message.alert(',
    '                "Received Amount cannot be less than Payable Amount.",',
    '                function () {',
    '                    $received.focus().select();',
    '                }',
    '            );',
    '            return;',
    '        }',
    '',
    '        $received.addClass("received-ok");',
    '',
    '        var change = receivedAmnt - netPay;',
    '        $s("P17_RETURN_AMOUNT", change.toFixed(2));',
    '',
    '        $return.addClass(change > 0 ? "change-ok" : "change-zero");',
    '',
    '        confirming = true;',
    '',
    '        apex.message.confirm(',
    unistr('            "\D83D\DCB0 PAYMENT CONFIRMATION\005Cn\005Cn" +'),
    '            "Payable Amount  : " + netPay.toFixed(2) + "\n" +',
    '            "Received Amount : " + receivedAmnt.toFixed(2) + "\n" +',
    '            "Change Amount   : " + change.toFixed(2) + "\n\n" +',
    '            "Confirm Payment?",',
    '            function (ok) {',
    '                confirming = false;',
    '',
    '                if (ok) {',
    '                    paymentConfirmed = true;',
    '',
    '                    /*',
    '                     * Submit the existing APEX Save button',
    '                     * only after confirmation.',
    '                     */',
    '                    $save[0].click();',
    '                } else {',
    '                    $received.focus().select();',
    '                }',
    '            }',
    '        );',
    '    }',
    '',
    '    /* Enter key: validate without submitting the page */',
    '    $received.on("keydown.posPayment", function (event) {',
    '        if (event.key === "Enter") {',
    '            event.preventDefault();',
    '            event.stopPropagation();',
    '            validatePayment();',
    '        }',
    '    });',
    '',
    '    /*',
    '     * Capture Save click before APEX''s normal submit handler.',
    '     */',
    '    $save[0].addEventListener("click", function (event) {',
    '        if (paymentConfirmed) {',
    '            paymentConfirmed = false;',
    '            return; // Allow normal APEX submit',
    '        }',
    '',
    '        event.preventDefault();',
    '        event.stopImmediatePropagation();',
    '',
    '        if (!confirming) {',
    '            validatePayment();',
    '        }',
    '    }, true);',
    '})();',
    '')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20261015164503Z')
,p_updated_on=>wwv_flow_imp.dz('20261015164737Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
