,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var e = this.browserEvent;',
    '',
    'if (!e || e.key !== "Enter") {',
    '    return;',
    '}',
    '',
    'e.preventDefault();',
    'e.stopPropagation();',
    '',
    'var netPay = parseFloat($v("P17_PAYABLE_AMOUNT")) || 0;',
    'var receivedAmnt = parseFloat($v("P17_RECEIVED_AMOUNT")) || 0;',
    '',
    'var $received = $("#P17_RECEIVED_AMOUNT");',
    'var $return = $("#P17_RETURN_AMOUNT");',
    '',
    '/* Remove Previous Colors */',
    '$received.removeClass("received-error received-ok");',
    '$return.removeClass("change-ok change-zero");',
    '',
    '/* =================================',
    '   RECEIVED LESS THAN PAYABLE',
    '   ================================= */',
    '',
    'if (receivedAmnt < netPay) {',
    '',
    '    $received.addClass("received-error");',
    '',
    '    $s("P17_RETURN_AMOUNT", "0.00");',
    '',
    '    $return.addClass("change-zero");',
    '',
    '    setTimeout(function () {',
    '        $received.focus();',
    '        $received.select();',
    '    }, 100);',
    '',
    '    return;',
    '}',
    '',
    '/* =================================',
    '   RECEIVED AMOUNT OK',
    '   ================================= */',
    '',
    '$received.addClass("received-ok");',
    '',
    '/* =================================',
    '   CALCULATE CHANGE',
    '   ================================= */',
    '',
    'var returnAmnt = receivedAmnt - netPay;',
    '',
    '$s(',
    '    "P17_RETURN_AMOUNT",',
    '    returnAmnt.toFixed(2)',
    ');',
    '',
    '/* =================================',
    '   CHANGE COLOR',
    '   ================================= */',
    '',
    'if (returnAmnt > 0) {',
    '    $return.addClass("change-ok");',
    '} else {',
    '    $return.addClass("change-zero");',
    '}',
    '',
    '/* =================================',
    '   PAYMENT CONFIRMATION',
    '   ================================= */',
    '',
    'var confirmMessage =',
    unistr('    "\D83D\DCB0 PAYMENT CONFIRMATION\005Cn\005Cn" +'),
    unistr('    "\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\005Cn" +'),
    unistr('    "\D83D\DCB3 Payable Amount   :  " + netPay.toFixed(2) + "\005Cn" +'),
    unistr('    "\D83D\DCB5 Received Amount  :  " + receivedAmnt.toFixed(2) + "\005Cn" +'),
    unistr('    "\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\2501\005Cn" +'),
    unistr('    "\D83D\DFE2 Change Amount    :  " + returnAmnt.toFixed(2) + "\005Cn" +'),
    '',
    '    "Confirm Payment?";',
    '',
    'apex.message.confirm(',
    '    confirmMessage,',
    '    function (ok) {',
    '',
    '        if (ok) {',
    '',
    '            setTimeout(function () {',
    '                $("#pb-save").click();',
    '            }, 100);',
    '',
    '        } else {',
    '',
    '            setTimeout(function () {',
    '                $received.focus();',
    '                $received.select();',
    '            }, 100);',
    '        }',
    '    }',
    ');')))).to_clob
,p_build_option_id=>wwv_flow_imp.id(8032859059284477852)
,p_created_on=>wwv_flow_imp.dz('20260914115032Z')
,p_updated_on=>wwv_flow_imp.dz('20261015164008Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
