wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15309683437803527)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ADD_TO_CART_PRODUCT'
,p_static_id=>'add-to-cart-product'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_DATA CLOB;',
'BEGIN',
'',
'    SELECT JSON_ARRAYAGG(',
'               JSON_OBJECT(',
'                   ''PRODUCT_NO'' VALUE P.PRODUCT_NO,',
'                   ''PRODUCT_CODE'' VALUE P.PRODUCT_CODE,',
'                   ''PRODUCT_NAME'' VALUE P.PRODUCT_NAME,',
'                   ''DESCRIPTION'' VALUE P.DESCRIPTION,',
'',
'                   /* =========================================',
'                      PRODUCT BASE UOM',
'                      Example: KG',
'                      ========================================= */',
'                   ''UOM_NAME'' VALUE BU.UOM_NAME,',
'',
'                   /* =========================================',
'                      DEFAULT SALES UOM',
unistr('                      Product select \0995\09B0\09B2\09C7 Base UOM \0986\09B8\09AC\09C7'),
'                      Example: KG',
'                      ========================================= */',
'                   ''UOM_NO'' VALUE P.UOM_NO,',
'',
'                   /* =========================================',
'                      DEFAULT QUANTITY',
'                      ========================================= */',
'                   ''ORDER_QTY'' VALUE 1,',
'',
'                   /* =========================================',
'                      BASE UOM SELECTED',
unistr('                      \09A4\09BE\0987 factor = 1'),
'                      Example: KG = 1',
'                      ========================================= */',
'                   ''PACK_QTY'' VALUE 1,',
'',
'                   /* =========================================',
'                      BASE STOCK QUANTITY',
'                      ========================================= */',
'                   ''BASE_QTY'' VALUE 1,',
'',
'                   /* =========================================',
'                      BASE UOM SALES PRICE',
'                      Example: KG = 80',
'                      ========================================= */',
'                   ''TOTAL_AMOUNT'' VALUE NVL(CP.SALES_RATE,0),',
'',
'                   ''SALES_RATE'' VALUE NVL(CP.SALES_RATE,0),',
'',
'                   ''BASE_RATE'' VALUE NVL(CP.SALES_RATE,0),',
'',
'                   /* =========================================',
'                      CURRENT STOCK',
'                      Stock maintained in Base UOM',
'                      Example: KG',
'                      ========================================= */',
'                   ''STOCK_QTY'' VALUE NVL(S.STOCK_QTY,0),',
'',
'                   /* =========================================',
'                      DISCOUNT PERCENT',
'                      ========================================= */',
'                   ''DISCOUNT_PERCENT'' VALUE',
'                       NVL(',
'                           (',
'                               SELECT DC.DISCOUNT_PERCENT',
'                                 FROM MST_DISCOUNT_CONFIG DC',
'                                WHERE DC.ACTIVE_FLAG = ''1''',
'                                  AND SYSDATE >= DC.EFFECTIVE_FROM',
'                                  AND (',
'                                         DC.EFFECTIVE_TO IS NULL',
'                                         OR SYSDATE <= DC.EFFECTIVE_TO',
'                                      )',
'                                  AND (',
'                                         DC.PRODUCT_NO = P.PRODUCT_NO',
'                                         OR DC.PRODUCT_NO IS NULL',
'                                      )',
'                                  AND (',
'                                         DC.CATEGORY_NO = P.CATEGORY_NO',
'                                         OR DC.CATEGORY_NO IS NULL',
'                                      )',
'                                  AND (',
'                                         DC.CUSTOMER_NO =',
'                                             APEX_APPLICATION.G_X02',
'                                         OR DC.CUSTOMER_NO IS NULL',
'                                      )',
'                                ORDER BY',
'                                    CASE',
'                                        WHEN DC.PRODUCT_NO IS NOT NULL THEN 3',
'                                        WHEN DC.CATEGORY_NO IS NOT NULL THEN 2',
'                                        WHEN DC.CUSTOMER_NO IS NOT NULL THEN 1',
'                                        ELSE 0',
'                                    END DESC,',
'                                    DC.PRIORITY DESC,',
'                                    DC.DISCOUNT_CONFIG_NO DESC',
'                                FETCH FIRST 1 ROW ONLY',
'                           ),',
'                           0',
'                       ),',
'',
'                   /* =========================================',
'                      DISCOUNT AMOUNT',
'                      ========================================= */',
'                   ''DISCOUNT_AMOUNT'' VALUE',
'                       ROUND(',
'                           NVL(CP.SALES_RATE,0)',
'                           *',
'                           NVL(',
'                               (',
'                                   SELECT DC.DISCOUNT_PERCENT',
'                                     FROM MST_DISCOUNT_CONFIG DC',
'                                    WHERE DC.ACTIVE_FLAG = ''1''',
'                                      AND SYSDATE >= DC.EFFECTIVE_FROM',
'                                      AND (',
'                                             DC.EFFECTIVE_TO IS NULL',
'                                             OR SYSDATE <= DC.EFFECTIVE_TO',
'                                          )',
'                                      AND (',
'                                             DC.PRODUCT_NO = P.PRODUCT_NO',
'                                             OR DC.PRODUCT_NO IS NULL',
'                                          )',
'                                      AND (',
'                                             DC.CATEGORY_NO = P.CATEGORY_NO',
'                                             OR DC.CATEGORY_NO IS NULL',
'                                          )',
'                                      AND (',
'                                             DC.CUSTOMER_NO =',
'                                                 APEX_APPLICATION.G_X02',
'                                             OR DC.CUSTOMER_NO IS NULL',
'                                          )',
'                                    ORDER BY',
'                                        CASE',
'                                            WHEN DC.PRODUCT_NO IS NOT NULL THEN 3',
'                                            WHEN DC.CATEGORY_NO IS NOT NULL THEN 2',
'                                            WHEN DC.CUSTOMER_NO IS NOT NULL THEN 1',
'                                            ELSE 0',
'                                        END DESC,',
'                                        DC.PRIORITY DESC,',
'                                        DC.DISCOUNT_CONFIG_NO DESC',
'                                    FETCH FIRST 1 ROW ONLY',
'                               ),',
'                               0',
'                           ) / 100,',
'                           2',
'                       ),',
'',
'                   /* =========================================',
'                      NET AMOUNT',
'                      ========================================= */',
'                   ''NET_AMOUNT'' VALUE',
'                       ROUND(',
'                           NVL(CP.SALES_RATE,0)',
'                           -',
'                           (',
'                               NVL(CP.SALES_RATE,0)',
'                               *',
'                               NVL(',
'                                   (',
'                                       SELECT DC.DISCOUNT_PERCENT',
'                                         FROM MST_DISCOUNT_CONFIG DC',
'                                        WHERE DC.ACTIVE_FLAG = ''1''',
'                                          AND SYSDATE >= DC.EFFECTIVE_FROM',
'                                          AND (',
'                                                 DC.EFFECTIVE_TO IS NULL',
'                                                 OR SYSDATE <= DC.EFFECTIVE_TO',
'                                              )',
'                                          AND (',
'                                                 DC.PRODUCT_NO =',
'                                                     P.PRODUCT_NO',
'                                                 OR DC.PRODUCT_NO IS NULL',
'                                              )',
'                                          AND (',
'                                                 DC.CATEGORY_NO =',
'                                                     P.CATEGORY_NO',
'                                                 OR DC.CATEGORY_NO IS NULL',
'                                              )',
'                                          AND (',
'                                                 DC.CUSTOMER_NO =',
'                                                     APEX_APPLICATION.G_X02',
'                                                 OR DC.CUSTOMER_NO IS NULL',
'                                              )',
'                                        ORDER BY',
'                                            CASE',
'                                                WHEN DC.PRODUCT_NO IS NOT NULL THEN 3',
'                                                WHEN DC.CATEGORY_NO IS NOT NULL THEN 2',
'                                                WHEN DC.CUSTOMER_NO IS NOT NULL THEN 1',
'                                                ELSE 0',
'                                            END DESC,',
'                                            DC.PRIORITY DESC,',
'                                            DC.DISCOUNT_CONFIG_NO DESC',
'                                        FETCH FIRST 1 ROW ONLY',
'                                   ),',
'                                   0',
'                               ) / 100',
'                           ),',
'                           2',
'                       )',
'',
'                   RETURNING CLOB',
'               )',
'               RETURNING CLOB',
'           )',
'      INTO V_DATA',
'',
'      FROM MST_PRODUCT P',
'',
'      /* =========================================',
'         PRODUCT BASE UOM',
'         Example: KG',
'         ========================================= */',
'      JOIN MST_UOM BU',
'        ON BU.UOM_NO = P.UOM_NO',
'       AND BU.ACTIVE_FLAG = ''1''',
'',
'      /* =========================================',
'         CURRENT SALES PRICE',
'         ',
'         IMPORTANT:',
unistr('         Populate time Base UOM price \09A8\09C7\0993\09DF\09BE \09B9\09AC\09C7\0964'),
'         ',
'         Product Base UOM = KG',
unistr('         \09A4\09BE\0987 KG price \0986\09B8\09AC\09C7\0964'),
'         ',
unistr('         Bag price \098F\0996\09BE\09A8\09C7 \0986\09B8\09AC\09C7 \09A8\09BE\0964'),
unistr('         User \09AA\09B0\09C7 Bag select \0995\09B0\09B2\09C7'),
'         separate UOM change process',
unistr('         Bag price \0986\09A8\09AC\09C7\0964'),
'         ========================================= */',
'      LEFT JOIN',
'      (',
'          SELECT PRODUCT_NO,',
'                 UOM_NO,',
'                 SALES_RATE,',
'                 ROW_NUMBER() OVER(',
'                     PARTITION BY PRODUCT_NO, UOM_NO',
'                     ORDER BY EFFECTIVE_DATE DESC,',
'                              SALES_PRICE_NO DESC',
'                 ) RN',
'            FROM MST_SALES_PRICE',
'           WHERE ACTIVE_FLAG = ''1''',
'             AND EFFECTIVE_DATE <= SYSDATE',
'      ) CP',
'        ON CP.PRODUCT_NO = P.PRODUCT_NO',
'       AND CP.UOM_NO = P.UOM_NO',
'       AND CP.RN = 1',
'',
'      /* =========================================',
'         CURRENT STOCK',
'         ',
'         Stock is always maintained in Base UOM.',
'         Example: KG',
'         ========================================= */',
'      LEFT JOIN',
'      (',
'          SELECT PRODUCT_NO,',
'                 SUM(NVL(QTY_IN,0))',
'                 -',
'                 SUM(NVL(QTY_OUT,0)) STOCK_QTY',
'            FROM TRN_STOCK_LEDGER',
'           GROUP BY PRODUCT_NO',
'      ) S',
'        ON S.PRODUCT_NO = P.PRODUCT_NO',
'',
'     WHERE P.PRODUCT_NO = APEX_APPLICATION.G_X01',
'       AND P.ACTIVE_FLAG = 1;',
'',
'    /* =========================================',
'       RETURN JSON',
'       ========================================= */',
'    HTP.PRN(',
'        NVL(V_DATA,''[]'')',
'    );',
'',
'EXCEPTION',
'',
'    WHEN NO_DATA_FOUND THEN',
'',
'        HTP.PRN(''[]'');',
'',
'    WHEN OTHERS THEN',
'',
'        HTP.PRN(',
'            ''{"ERROR":"'' ||',
'            REPLACE(SQLERRM,''"'',''\"'') ||',
'            ''"}''',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15309683437803527
,p_updated_on=>wwv_flow_imp.dz('20260915133336Z')
