wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15160183944336121)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PRODUCT_DISCOUNT'
,p_static_id=>'get-product-discount'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 2:43:29 PM (QP5 v5.388) */',
'DECLARE',
'    V_DISCOUNT_PERCENT   NUMBER := 0;',
'BEGIN',
'    SELECT DISCOUNT_PERCENT',
'      INTO V_DISCOUNT_PERCENT',
'      FROM (  SELECT D.DISCOUNT_PERCENT',
'                FROM MST_DISCOUNT_CONFIG D',
'                     JOIN MST_PRODUCT P',
'                         ON P.PRODUCT_NO = APEX_APPLICATION.G_X01',
'               WHERE     D.ACTIVE_FLAG = 1',
'                     AND SYSDATE >= D.EFFECTIVE_FROM',
'                     AND (D.EFFECTIVE_TO IS NULL OR SYSDATE <= D.EFFECTIVE_TO)',
'                     AND (   D.PRODUCT_NO IS NULL',
'                          OR D.PRODUCT_NO = APEX_APPLICATION.G_X01)',
'                     AND (   D.CATEGORY_NO IS NULL',
'                          OR D.CATEGORY_NO = P.CATEGORY_NO)',
'                     AND (   D.CUSTOMER_NO IS NULL',
'                          OR D.CUSTOMER_NO = APEX_APPLICATION.G_X02)',
'            ORDER BY D.PRIORITY DESC, D.DISCOUNT_CONFIG_NO DESC)',
'     WHERE ROWNUM = 1;',
'',
'    HTP.P (V_DISCOUNT_PERCENT);',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        HTP.P (''0'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>15160183944336121
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(16479057007293917)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_SALES_UOM_PRICE'
,p_static_id=>'get-sales-uom-price'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    L_PRODUCT_NO  NUMBER := TO_NUMBER(APEX_APPLICATION.G_X01);',
'    L_UOM_NO      NUMBER := TO_NUMBER(APEX_APPLICATION.G_X02);',
'    L_RATE        NUMBER := 0;',
'    L_FACTOR      NUMBER := 1;',
'BEGIN',
'',
'    /* Get Sales Rate for Selected UOM */',
'    BEGIN',
'        SELECT SALES_RATE',
'          INTO L_RATE',
'          FROM (',
'                SELECT SALES_RATE',
'                  FROM MST_SALES_PRICE',
'                 WHERE PRODUCT_NO = L_PRODUCT_NO',
'                   AND UOM_NO = L_UOM_NO',
'                   AND ACTIVE_FLAG = ''1''',
'                   AND EFFECTIVE_DATE <= SYSDATE',
'                 ORDER BY EFFECTIVE_DATE DESC,',
'                          SALES_PRICE_NO DESC',
'               )',
'         WHERE ROWNUM = 1;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            L_RATE := 0;',
'    END;',
'',
'',
'    /* Get Pack / Conversion Quantity */',
'    BEGIN',
'        SELECT CASE',
'                   /* Base UOM = KG',
'                      1 KG = 1 Base Qty */',
'                   WHEN L_UOM_NO = C.BASE_UOM_NO',
'                   THEN 1',
'',
'                   /* Convert UOM = BAG',
'                      1 BAG = 25 KG */',
'                   WHEN L_UOM_NO = C.CONVERT_UOM_NO',
'                   THEN C.CONVERSION_FACTOR',
'',
'                   ELSE 1',
'               END',
'          INTO L_FACTOR',
'          FROM MST_UOM_CONVERSION C',
'         WHERE C.PRODUCT_NO = L_PRODUCT_NO',
'           AND C.ACTIVE_FLAG = ''1''',
'           AND (',
'                  C.BASE_UOM_NO = L_UOM_NO',
'                  OR C.CONVERT_UOM_NO = L_UOM_NO',
'               )',
'           AND ROWNUM = 1;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            L_FACTOR := 1;',
'    END;',
'',
'',
'    /* Return JSON */',
'    HTP.P(',
'        ''{"SALES_RATE":'' || NVL(L_RATE, 0) ||',
'        '',"PACK_QTY":'' || NVL(L_FACTOR, 1) ||',
'        ''}''',
'    );',
'',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'',
'        HTP.P(',
'            ''{"SALES_RATE":0'' ||',
'            '',"PACK_QTY":1'' ||',
'            '',"ERROR":"'' ||',
'            REPLACE(SQLERRM, ''"'', ''\"'') ||',
'            ''"}''',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>16479057007293917
,p_updated_on=>wwv_flow_imp.dz('20260915133131Z')
,p_updated_by=>'ADMIN'
);
