,p_plug_name=>'SALES INVOICE LIST'
,p_static_id=>'register_1'
,p_region_name=>'invoice_list'
,p_parent_plug_id=>wwv_flow_imp.id(17766677118782521016)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/10/2026 4:44:04 PM (QP5 v5.388) */',
'  SELECT ROWNUM',
'             AS SL,',
'         I.INVOICE_NO,',
'         I.INVOICE_CODE,',
'         I.INVOICE_DATE,',
'         O.ORDER_CODE,',
'         C.CUSTOMER_NAME,',
'         C.MOBILE_NO,',
'         NVL (IDT.INVOICE_QTY, 0)',
'             AS TOTAL_INVOICE_QTY,',
'         NVL (DLV.DELIVERY_QTY, 0)',
'             AS TOTAL_DELIVERY_QTY,',
'         GREATEST (NVL (IDT.INVOICE_QTY, 0) - NVL (DLV.DELIVERY_QTY, 0), 0)',
'             AS DELIVERY_BALANCE_QTY,',
'         NVL (DC.DELIVERY_COUNT, 0)',
'             AS DELIVERY_COUNT,',
'         I.TOTAL_AMOUNT,',
'         I.NET_AMOUNT,',
'         CASE',
'             WHEN NVL (IDT.INVOICE_QTY, 0) = 0',
'             THEN',
'                 ''<span class="t-Badge t-Badge--danger">No Quantity</span>''',
'             WHEN NVL (DLV.DELIVERY_QTY, 0) = 0',
'             THEN',
'                 ''<span class="t-Badge t-Badge--warning">Waiting Delivery</span>''',
'             WHEN NVL (DLV.DELIVERY_QTY, 0) < NVL (IDT.INVOICE_QTY, 0)',
'             THEN',
'                 ''<span class="t-Badge t-Badge--primary">Partial Delivery</span>''',
'             ELSE',
'                 ''<span class="t-Badge t-Badge--success">Delivered</span>''',
'         END',
'             AS DELIVERY_STATUS,',
'         NULL',
'             AS PRINT_BTN,',
'         CASE',
'             WHEN NVL (DLV.DELIVERY_QTY, 0) < NVL (IDT.INVOICE_QTY, 0)',
'             THEN',
'                 NULL',
'         END',
'             AS DELIVERY_BTN,',
'         CASE',
'             WHEN NVL (DC.DELIVERY_COUNT, 0) > 0',
'             THEN',
'                    ''<a href="f?p=&APP_ID.:106:&SESSION.::NO::P106_INVOICE_NO:''',
'                 || I.INVOICE_NO',
'                 || ''" class="t-Button t-Button--info t-Button--tiny">''',
'                 || ''<span class="fa fa-truck"></span>&nbsp; View Delivery''',
'                 || ''</a>''',
'         END',
'             AS DELIVERY_VIEW_BTN,',
'         I.CREATED_BY,',
'         I.CREATED_DATE',
'    FROM TRN_SALES_INVOICE_MST I',
'         JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'         JOIN TRN_SALES_ORDER_MST O ON O.ORDER_NO = I.ORDER_NO',
'         /* Invoice Quantity */',
'         LEFT JOIN (  SELECT INVOICE_NO, SUM (SALES_QTY) AS INVOICE_QTY',
'                        FROM TRN_SALES_INVOICE_DTL',
'                    GROUP BY INVOICE_NO) IDT',
'             ON IDT.INVOICE_NO = I.INVOICE_NO',
'         /* Approved Delivery Quantity */',
'         LEFT JOIN',
'         (  SELECT M.INVOICE_NO, SUM (D.DELIVERY_QTY) AS DELIVERY_QTY',
'              FROM TRN_DELIVERY_MST M',
'                   JOIN TRN_DELIVERY_DTL D ON D.DELIVERY_NO = M.DELIVERY_NO',
'             WHERE M.APPROVAL_STATUS = ''A''',
'          GROUP BY M.INVOICE_NO) DLV',
'             ON DLV.INVOICE_NO = I.INVOICE_NO',
'         /* Delivery Challan Count */',
'         LEFT JOIN (  SELECT INVOICE_NO, COUNT (*) AS DELIVERY_COUNT',
'                        FROM TRN_DELIVERY_MST',
'                    GROUP BY INVOICE_NO) DC',
'             ON DC.INVOICE_NO = I.INVOICE_NO',
'   WHERE I.APPROVAL_STATUS = ''A''',
'ORDER BY I.INVOICE_NO DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P19_STATUS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
