wwv_flow_imp_page.create_page(
 p_id=>21
,p_name=>'Invoice Entry'
,p_alias=>'INVOICE-ENTRY'
,p_step_title=>'Invoice Entry'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function generateInvoice(orderNo) {',
'',
'    if (confirm(''Generate Invoice?'')) {',
'',
'        apex.server.process(',
'            ''GENERATE_INVOICE'',',
'            {',
'                x01: orderNo',
'            },',
'            {',
'                success: function (pData) {',
'',
'                    apex.message.showPageSuccess(pData);',
'',
'                    apex.region(''sales_order_list'').refresh();',
'',
'                }',
'            }',
'        );',
'',
'    }',
'}',
'function populateInvoice() {',
'',
'    if (!$v(''P21_ORDER_NO'')) {',
'        apex.message.alert(''Please select order.'');',
'        return;',
'    }',
'',
'    var model = apex.region("invoice-dtl")',
'        .widget()',
'        .interactiveGrid("getViews", "grid")',
'        .model;',
'',
unistr('    // \0986\0997\09C7 \09A5\09C7\0995\09C7\0987 Data \0986\099B\09C7 \0995\09BF\09A8\09BE'),
'    if (model.getTotalRecords() > 0) {',
'        apex.message.alert(''Invoice details already exist.'');',
'        return;',
'    }',
'',
'    apex.server.process(',
'        ''INVOICE_POPULATE'',',
'        {',
'            x01: $v(''P21_ORDER_NO'')',
'        },',
'        {',
'            success: function (pData) {',
'',
'                var json = JSON.parse(pData);',
'',
unistr('                // Data \09A8\09BE \09A5\09BE\0995\09B2\09C7'),
'                if (!json || json.length === 0) {',
'                    apex.message.alert(',
'                        ''No pending order items found for invoice.''',
'                    );',
'                    return;',
'                }',
'',
'                for (var key in json) {',
'',
'                    if (json.hasOwnProperty(key)) {',
'',
'                        var rec = model.insertNewRecord();',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "ORDER_DTL_NO",',
'                            json[key].ORDER_DTL_NO.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "PRODUCT_NO",',
'                            json[key].PRODUCT_NO.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "ORDER_QTY",',
'                            json[key].ORDER_QTY.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "PREVIOUS_INVOICE_QTY",',
'                            json[key].PREVIOUS_INVOICE_QTY.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "BALANCE_QTY",',
'                            json[key].BALANCE_QTY.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "SALES_QTY",',
'                            json[key].SALES_QTY.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "SALES_RATE",',
'                            json[key].SALES_RATE.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "TOTAL_AMOUNT",',
'                            json[key].TOTAL_AMOUNT.toString()',
'                        );',
'                           model.setRecordValue(',
'                            rec,',
'                            "NET_AMOUNT",',
'                            json[key].NET_AMOUNT.toString()',
'                        );',
'                        model.setRecordValue(',
'    rec,',
'    "DISCOUNT_PERCENT",',
'    (json[key].DISCOUNT_PERCENT || 0).toString()',
');',
'',
'model.setRecordValue(',
'    rec,',
'    "DISCOUNT_AMOUNT",',
'    (json[key].DISCOUNT_AMOUNT || 0).toString()',
');',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "PRODUCT_NAME",',
'                            json[key].PRODUCT_NAME.toString()',
'                        );',
'',
'                        model.setRecordValue(',
'                            rec,',
'                            "PRODUCT_CODE",',
'                            json[key].PRODUCT_CODE.toString()',
'                        );',
'                        model.setRecordValue(',
'    rec,',
'    "UOM_NO",',
'    json[key].UOM_NO.toString()',
');',
'',
'model.setRecordValue(',
'    rec,',
'    "PACK_QTY",',
'    json[key].PACK_QTY.toString()',
');',
'',
'model.setRecordValue(',
'    rec,',
'    "BASE_QTY",',
'    json[key].BASE_QTY.toString()',
');',
'',
'model.setRecordValue(',
'    rec,',
'    "BASE_RATE",',
'    json[key].BASE_RATE.toString()',
');',
'                    }',
'                }',
'',
'                apex.message.showPageSuccess(',
'                    json.length +',
'                    '' item(s) loaded successfully.''',
'                );',
'            },',
'            error: function () {',
'                apex.message.alert(',
'                    ''Error loading invoice details.''',
'                );',
'            },',
'            dataType: "text"',
'        }',
'    );',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
,p_last_updated_on=>wwv_flow_imp.dz('20260910162907Z')
,p_last_updated_by=>'A-0001'
);
