,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       D.INVOICE_DTL_NO,',
'',
'       D.ORDER_DTL_NO,',
'',
'       D.PRODUCT_NO,',
'',
'       P.PRODUCT_CODE,',
'',
'       P.PRODUCT_NAME,',
'',
'       P.DESCRIPTION,',
'',
'       P.BRAND_NO,',
'',
'       D.UOM_NO,',
'',
'       U.UOM_NAME,',
'',
'       D.PACK_QTY,',
'',
'       D.ORDER_QTY,',
'',
'       D.BASE_QTY,',
'',
'       NVL(',
'           (',
'               SELECT SUM(X.SALES_QTY)',
'                 FROM TRN_SALES_INVOICE_DTL X',
'                WHERE X.ORDER_DTL_NO=D.ORDER_DTL_NO',
'                  AND X.INVOICE_DTL_NO<>D.INVOICE_DTL_NO',
'           ),',
'           0',
'       ) PREVIOUS_INVOICE_QTY,',
'',
'       (',
'           D.ORDER_QTY-',
'           NVL(',
'               (',
'                   SELECT SUM(X.SALES_QTY)',
'                     FROM TRN_SALES_INVOICE_DTL X',
'                    WHERE X.ORDER_DTL_NO=D.ORDER_DTL_NO',
'                      AND X.INVOICE_DTL_NO<>D.INVOICE_DTL_NO',
'               ),',
'               0',
'           )',
'       ) BALANCE_QTY,',
'',
'       D.SALES_QTY,',
'',
'       D.SALES_RATE,',
'',
'       D.BASE_RATE,',
'',
'       D.TOTAL_AMOUNT,',
'',
'       D.NET_AMOUNT,',
'',
'       D.REMARKS,',
'              D.DISCOUNT_PERCENT,',
'       D.DISCOUNT_AMOUNT',
'',
'FROM TRN_SALES_INVOICE_DTL D',
'',
'JOIN MST_PRODUCT P',
'ON P.PRODUCT_NO=D.PRODUCT_NO',
'',
'LEFT JOIN MST_UOM U',
'ON U.UOM_NO=D.UOM_NO',
'',
'WHERE D.INVOICE_NO=:P21_INVOICE_NO;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P21_INVOICE_NO'
,p_prn_units=>'INCHES'
