wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37198169233666231736)
,p_plug_name=>'SALES INVOICE MST'
,p_static_id=>'register_1'
,p_region_name=>'sales_order_list'
,p_parent_plug_id=>wwv_flow_imp.id(20175731778287080737)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:t-Form--large:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       I.INVOICE_NO,',
'       I.INVOICE_CODE,',
'       I.INVOICE_DATE,',
'',
'       I.ORDER_NO,',
'',
'       I.CUSTOMER_NO,',
'',
'       C.CUSTOMER_NAME,',
'',
'       C.MOBILE_NO,',
'',
'       C.ADDRESS,',
'',
'       I.TOTAL_AMOUNT,',
'',
'       I.DELIVERY_STATUS,',
'',
'       I.CREATED_BY,',
'',
'       I.CREATED_DATE,',
'',
'       I.UPDATED_BY,',
'',
'       I.UPDATED_DATE,',
'',
'       I.DELIVERY_BY,',
'',
'       I.DELIVERY_DATE',
'',
'',
'FROM TRN_SALES_INVOICE_MST I',
'',
'JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'',
'WHERE I.INVOICE_NO = :P21_INVOICE_NO;'))
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_plug_source_type=>'NATIVE_FORM'
,p_updated_on=>wwv_flow_imp.dz('20260907150621Z')
,p_updated_by=>'ADMIN'
);
