wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11471338484512832921)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE'
,p_static_id=>'delete'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_count NUMBER;',
'',
'BEGIN',
'',
'    SELECT COUNT(*)',
'      INTO v_count',
'      FROM TRN_DELIVERY_MST',
'     WHERE INVOICE_NO = :P21_INVOICE_NO',
'       AND APPROVAL_STATUS = ''A'';',
'',
'    IF v_count > 0 THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Delivery already exists. Invoice cannot be deleted.''',
'        );',
'',
'    END IF;',
'',
'    SELECT COUNT(*)',
'      INTO v_count',
'      FROM TRN_CUSTOMER_RETURN_MST',
'     WHERE INVOICE_NO = :P21_INVOICE_NO',
'       AND APPROVAL_STATUS = ''A'';',
'',
'    IF v_count > 0 THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Customer return exists. Invoice cannot be deleted.''',
'        );',
'',
'    END IF;',
'',
'    DELETE',
'      FROM TRN_SALES_INVOICE_DTL',
'     WHERE INVOICE_NO = :P21_INVOICE_NO;',
'',
'    DELETE',
'      FROM TRN_SALES_INVOICE_MST',
'     WHERE INVOICE_NO = :P21_INVOICE_NO;',
'',
'    UPDATE TRN_SALES_ORDER_MST',
'       SET ORDER_STATUS = ''P''',
'     WHERE ORDER_NO = :P21_ORDER_NO;',
'',
'    :P21_INVOICE_NO := null;',
'',
'    apex_application.g_print_success_message :=',
'        ''Invoice deleted successfully.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11427223540371783629)
,p_internal_uid=>11471338484512832921
,p_updated_on=>wwv_flow_imp.dz('20260825181630Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11471337673643832913)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(11401338208760981831)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INVOICE DETAILS - Save Interactive Grid Data'
,p_static_id=>'invoice-details-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/7/2026 3:13:03 PM (QP5 v5.388) */',
'DECLARE',
'    V_COUNT             NUMBER := 0;',
'    V_TOTAL_ORDER       NUMBER := 0;',
'    V_TOTAL_INVOICE     NUMBER := 0;',
'    V_INVOICE_TOTAL     NUMBER := 0;',
'    V_GROSS_AMOUNT      NUMBER := 0;',
'    V_DISCOUNT_AMOUNT   NUMBER := 0;',
'    V_NET_AMOUNT        NUMBER := 0;',
'BEGIN',
'    ------------------------------------------------',
'    -- Delete Validation',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS = ''D''',
'    THEN',
'        SELECT COUNT (*)',
'          INTO V_COUNT',
'          FROM TRN_DELIVERY_DTL  D',
'               JOIN TRN_DELIVERY_MST M ON M.DELIVERY_NO = D.DELIVERY_NO',
'         WHERE     D.PRODUCT_NO = :PRODUCT_NO',
'               AND M.INVOICE_NO = :P21_INVOICE_NO',
'               AND M.APPROVAL_STATUS = ''A'';',
'',
'        IF V_COUNT > 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Delivery already completed. Delete not allowed.'');',
'        END IF;',
'',
'',
'        SELECT COUNT (*)',
'          INTO V_COUNT',
'          FROM TRN_CUSTOMER_RETURN_DTL  R',
'               JOIN TRN_CUSTOMER_RETURN_MST M ON M.RETURN_NO = R.RETURN_NO',
'         WHERE     R.PRODUCT_NO = :PRODUCT_NO',
'               AND M.INVOICE_NO = :P21_INVOICE_NO',
'               AND M.APPROVAL_STATUS = ''A'';',
'',
'        IF V_COUNT > 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Customer return exists. Delete not allowed.'');',
'        END IF;',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Calculate Gross, Discount and Net Amount',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS IN (''C'', ''U'')',
'    THEN',
'        V_GROSS_AMOUNT := NVL ( :SALES_QTY, 0) * NVL ( :SALES_RATE, 0);',
'',
'        V_DISCOUNT_AMOUNT :=',
'            V_GROSS_AMOUNT * NVL ( :DISCOUNT_PERCENT, 0) / 100;',
'',
'        V_NET_AMOUNT := V_GROSS_AMOUNT - V_DISCOUNT_AMOUNT;',
'',
'        IF V_NET_AMOUNT < 0',
'        THEN',
'            RAISE_APPLICATION_ERROR (',
'                -20001,',
'                ''Discount cannot be greater than sales amount.'');',
'        END IF;',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- INSERT',
'    ------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS = ''C''',
'    THEN',
'        INSERT INTO TRN_SALES_INVOICE_DTL (INVOICE_DTL_NO,',
'                                           INVOICE_NO,',
'                                           ORDER_DTL_NO,',
'                                           PRODUCT_NO,',
'                                           UOM_NO,',
'                                           PACK_QTY,',
'                                           ORDER_QTY,',
'                                           SALES_QTY,',
'                                           BASE_QTY,',
'                                           SALES_RATE,',
'                                           BASE_RATE,',
'                                           TOTAL_AMOUNT,',
'                                           NET_AMOUNT,',
'                                           DISCOUNT_PERCENT,',
'                                           DISCOUNT_AMOUNT,',
'                                           CREATED_BY,',
'                                           CREATED_DATE)',
'             VALUES (SEQ_INVOICE_DTL_NO.NEXTVAL,',
'                     :P21_INVOICE_NO,',
'                     :ORDER_DTL_NO,',
'                     :PRODUCT_NO,',
'                     :UOM_NO,',
'                     :PACK_QTY,',
'                     :ORDER_QTY,',
'                     :SALES_QTY,',
'                     :BASE_QTY,',
'                     :SALES_RATE,',
'                     :BASE_RATE,',
'                     :TOTAL_AMOUNT,',
'                     :NET_AMOUNT,--V_NET_AMOUNT,',
'                     NVL ( :DISCOUNT_PERCENT, 0),',
'                     NVL(:DISCOUNT_AMOUNT,0),',
'                     :APP_USER,',
'                     SYSDATE);',
'    ------------------------------------------------',
'    -- UPDATE',
'    ------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''U''',
'    THEN',
'        UPDATE TRN_SALES_INVOICE_DTL',
'           SET UOM_NO = :UOM_NO,',
'               PACK_QTY = :PACK_QTY,',
'               ORDER_QTY = :ORDER_QTY,',
'               SALES_QTY = :SALES_QTY,',
'               BASE_QTY = :BASE_QTY,',
'               SALES_RATE = :SALES_RATE,',
'               BASE_RATE = :BASE_RATE,',
'               TOTAL_AMOUNT = V_NET_AMOUNT,',
'               DISCOUNT_PERCENT = NVL ( :DISCOUNT_PERCENT, 0),',
'               DISCOUNT_AMOUNT = V_DISCOUNT_AMOUNT,',
'               UPDATED_BY = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE INVOICE_DTL_NO = :INVOICE_DTL_NO;',
'    ------------------------------------------------',
'    -- DELETE',
'    ------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''D''',
'    THEN',
'        DELETE FROM TRN_SALES_INVOICE_DTL',
'              WHERE INVOICE_DTL_NO = :INVOICE_DTL_NO;',
'    END IF;',
'',
'',
'    ------------------------------------------------',
'    -- Update Invoice Total',
'    ------------------------------------------------',
'',
'    SELECT NVL (SUM (D.TOTAL_AMOUNT), 0),NVL (SUM (D.NET_AMOUNT), 0)',
'      INTO V_INVOICE_TOTAL,V_NET_AMOUNT',
'      FROM TRN_SALES_INVOICE_DTL D',
'     WHERE D.INVOICE_NO = :P21_INVOICE_NO;',
'',
'',
'    UPDATE TRN_SALES_INVOICE_MST I',
'       SET TOTAL_AMOUNT = V_INVOICE_TOTAL,',
'           NET_AMOUNT   = V_NET_AMOUNT,',
'           DUE_AMOUNT = V_NET_AMOUNT - NVL (I.RECEIVED_AMOUNT, 0),',
'           UPDATED_BY = :APP_USER,',
'           UPDATED_DATE = SYSDATE',
'     WHERE I.INVOICE_NO = :P21_INVOICE_NO;',
'',
'',
'    ------------------------------------------------',
'    -- Calculate Order Quantity',
'    ------------------------------------------------',
'',
'    SELECT NVL (SUM (BASE_QTY), 0)',
'      INTO V_TOTAL_ORDER',
'      FROM TRN_SALES_ORDER_DTL',
'     WHERE ORDER_NO = :P21_ORDER_NO;',
'',
'',
'    ------------------------------------------------',
'    -- Calculate Invoiced Quantity',
'    ------------------------------------------------',
'',
'    SELECT NVL (SUM (D.BASE_QTY), 0)',
'      INTO V_TOTAL_INVOICE',
'      FROM TRN_SALES_INVOICE_DTL  D',
'           JOIN TRN_SALES_INVOICE_MST M ON M.INVOICE_NO = D.INVOICE_NO',
'     WHERE M.ORDER_NO = :P21_ORDER_NO;',
'',
'',
'    ------------------------------------------------',
'    -- Update Order Status',
'    ------------------------------------------------',
'',
'    UPDATE TRN_SALES_ORDER_MST',
'       SET ORDER_STATUS =',
'               CASE',
'                   WHEN V_TOTAL_INVOICE = 0 THEN ''P''',
'                   WHEN V_TOTAL_INVOICE < V_TOTAL_ORDER THEN ''PI''',
'                   ELSE ''I''',
'               END,',
'           UPDATED_BY = :APP_USER,',
'           UPDATED_DATE = SYSDATE',
'     WHERE ORDER_NO = :P21_ORDER_NO;',
'',
'',
'    APEX_APPLICATION.g_print_success_message :=',
'        ''Invoice details saved successfully.'';',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        RAISE_APPLICATION_ERROR (-20001, SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11427224892692783630)
,p_internal_uid=>11471337673643832913
,p_updated_on=>wwv_flow_imp.dz('20260910162800Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11471337375671832910)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INVOICE_POPULATE'
,p_static_id=>'invoice-populate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_DATA CLOB;',
'BEGIN',
'    SELECT JSON_ARRAYAGG(',
'             JSON_OBJECT(',
'               ''ORDER_DTL_NO'' VALUE D.ORDER_DTL_NO,',
'               ''PRODUCT_NO'' VALUE D.PRODUCT_NO,',
'               ''PRODUCT_CODE'' VALUE P.PRODUCT_CODE,',
'               ''PRODUCT_NAME'' VALUE P.PRODUCT_NAME,',
'               ''UOM_NO'' VALUE D.UOM_NO,',
'               ''PACK_QTY'' VALUE D.PACK_QTY,',
'               ''BASE_QTY'' VALUE D.BASE_QTY,',
'               ''BASE_RATE'' VALUE D.BASE_RATE,',
'               ''ORDER_QTY'' VALUE D.ORDER_QTY,',
'',
'               ''PREVIOUS_INVOICE_QTY'' VALUE NVL(X.INVOICED_QTY, 0),',
'',
'               ''BALANCE_QTY'' VALUE',
'                   D.ORDER_QTY - NVL(X.INVOICED_QTY, 0),',
'',
'               ''SALES_QTY'' VALUE',
'                   D.ORDER_QTY - NVL(X.INVOICED_QTY, 0),',
'',
'               ''SALES_RATE'' VALUE D.SALES_RATE,',
'',
'               ''DISCOUNT_PERCENT'' VALUE',
'                   NVL(D.DISCOUNT_PERCENT, 0),',
'',
'               ''DISCOUNT_AMOUNT'' VALUE',
'                   NVL(D.DISCOUNT_AMOUNT, 0),',
'',
'               ''TOTAL_AMOUNT'' VALUE',
'                   NVL(D.TOTAL_AMOUNT, 0),',
'                   ',
'                   ''NET_AMOUNT'' VALUE',
'                   NVL(D.NET_AMOUNT, 0)',
'',
'             RETURNING CLOB)',
'           RETURNING CLOB',
'           )',
'    INTO V_DATA',
'    FROM TRN_SALES_ORDER_DTL D',
'         JOIN MST_PRODUCT P',
'           ON P.PRODUCT_NO = D.PRODUCT_NO',
'         LEFT JOIN',
'         (',
'             SELECT ORDER_DTL_NO,',
'                    SUM(SALES_QTY) AS INVOICED_QTY',
'               FROM TRN_SALES_INVOICE_DTL',
'              GROUP BY ORDER_DTL_NO',
'         ) X',
'           ON X.ORDER_DTL_NO = D.ORDER_DTL_NO',
'   WHERE D.ORDER_NO = APEX_APPLICATION.G_X01',
'     AND D.ORDER_QTY - NVL(X.INVOICED_QTY, 0) > 0;',
'',
'    HTP.PRN(NVL(V_DATA, ''[]''));',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11471337375671832910
,p_updated_on=>wwv_flow_imp.dz('20260910162800Z')
,p_updated_by=>'ADMIN'
);
