wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11401339484150981843)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form SALES INVOICE MST'
,p_static_id=>'process-form-sales-invoice-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_invoice_no      NUMBER;',
'    v_invoice_code    VARCHAR2(30);',
'',
'    v_total_order     NUMBER;',
'    v_total_invoice   NUMBER;',
'',
'BEGIN',
'',
'    --------------------------------------------------',
'    -- Header Validation',
'    --------------------------------------------------',
'',
'    IF :P21_ORDER_NO IS NULL THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select sales order.''',
'        );',
'',
'    END IF;',
'',
'    IF :P21_INVOICE_DATE IS NULL THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter invoice date.''',
'        );',
'',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- New Invoice',
'    --------------------------------------------------',
'',
'    IF :P21_INVOICE_NO IS NULL THEN',
'',
'        SELECT SEQ_INVOICE_NO.NEXTVAL',
'          INTO v_invoice_no',
'          FROM DUAL;',
'',
'        v_invoice_code :=',
'            ''INV-'' || LPAD(v_invoice_no,6,''0'');',
'',
'        INSERT INTO TRN_SALES_INVOICE_MST',
'        (',
'            INVOICE_NO,',
'            INVOICE_CODE,',
'            INVOICE_DATE,',
'            ORDER_NO,',
'            CUSTOMER_NO,',
'            TOTAL_AMOUNT,',
'            DELIVERY_STATUS,',
'            PAYMENT_STATUS,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            v_invoice_no,',
'            v_invoice_code,',
'            :P21_INVOICE_DATE,',
'            :P21_ORDER_NO,',
'            :P21_CUSTOMER_NO,',
'            0,',
'            ''P'',  --Pending Delivery',
'            ''UP'' ,  --UnPaid',
'            ''P'',',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        :P21_INVOICE_NO := v_invoice_no;',
'',
'    --------------------------------------------------',
'    -- Update Invoice',
'    --------------------------------------------------',
'',
'    ELSE',
'',
'        UPDATE TRN_SALES_INVOICE_MST',
'           SET INVOICE_DATE = :P21_INVOICE_DATE,',
'               CUSTOMER_NO  = :P21_CUSTOMER_NO,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE INVOICE_NO = :P21_INVOICE_NO;',
'',
'    END IF;',
'',
'   ',
'',
'    --------------------------------------------------',
'    -- Success Message',
'    --------------------------------------------------',
'',
'    apex_application.g_print_success_message :=',
'        ''Invoice saved successfully.'';',
'',
'EXCEPTION',
'',
'    WHEN OTHERS THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            SQLERRM',
'        );',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(11427224892692783630)
,p_internal_uid=>11401339484150981843
,p_updated_on=>wwv_flow_imp.dz('20260901182043Z')
,p_updated_by=>'ADMIN'
);
end;
