,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT C.CONVERSION_NO,',
'       C.PRODUCT_NO,',
'       P.PRODUCT_NAME,',
'       C.BASE_UOM_NO,',
'       B.UOM_NAME AS BASE_UOM_NAME,',
'       C.CONVERT_UOM_NO,',
'       V.UOM_NAME AS CONVERT_UOM_NAME,',
