,p_region_id=>wwv_flow_imp.id(16187226390616734301)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Supplier Setup'
,p_static_id=>'initialize-form-supplier-setup'
,p_internal_uid=>11760515692204298
,p_created_on=>wwv_flow_imp.dz('20260828205916Z')
