,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var due = parseFloat($v("P27_DUE_AMOUNT")) || 0;',
    'var payment = parseFloat($v("P27_PAYMENT_AMOUNT")) || 0;',
    '',
    'if (payment <= 0) {',
    '',
    '    apex.message.showErrors([',
    '        {',
    '            type: "error",',
    '            location: ["inline"],',
    '            pageItem: "P27_PAYMENT_AMOUNT",',
    '            message: "Please enter a valid payment amount.",',
    '            unsafe: false',
    '        }',
    '    ]);',
    '',
    '    apex.item("P27_PAYMENT_AMOUNT").setValue("");',
    '',
    '    return false;',
    '}',
    '',
    'if (payment > due) {',
    '',
    '    apex.message.showErrors([',
    '        {',
    '            type: "error",',
    '            location: ["inline"],',
    '            pageItem: "P27_PAYMENT_AMOUNT",',
    '            message: "Payment cannot be greater than Due Amount.",',
    '            unsafe: false',
    '        }',
    '    ]);',
    '',
    '    apex.item("P27_PAYMENT_AMOUNT").setValue("");',
    '',
    '    return false;',
    '}',
    '',
    'apex.message.clearErrors();')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260830173053Z')
,p_updated_on=>wwv_flow_imp.dz('20260830173053Z')
