 p_id=>wwv_flow_imp.id(12206537194808787)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P29_SUPPLIER_NO IS NULL THEN',
'',
'        INSERT INTO MST_SUPPLIER',
'        (',
'            SUPPLIER_NO,',
'            SUPPLIER_CODE,',
'            SUPPLIER_NAME,',
'            CONTACT_PERSON,',
'            MOBILE_NO,',
'            EMAIL_ADDRESS,',
'            ADDRESS,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_SUPPLIER_NO.NEXTVAL,',
'           ''SUP'' || LPAD(SEQ_SUPPLIER_NO.NEXTVAL,4,''0''),',
'            :P29_SUPPLIER_NAME,',
'            :P29_CONTACT_PERSON,',
'            :P29_MOBILE_NO,',
'            :P29_EMAIL_ADDRESS,',
'            :P29_ADDRESS,',
'            NVL(:P29_ACTIVE_FLAG,''Y''),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Supplier saved successfully.'';',
'',
'    ELSE',
'',
'        UPDATE MST_SUPPLIER',
'           SET ',
'               SUPPLIER_NAME  = :P29_SUPPLIER_NAME,',
'               CONTACT_PERSON = :P29_CONTACT_PERSON,',
'               MOBILE_NO      = :P29_MOBILE_NO,',
'               EMAIL_ADDRESS  = :P29_EMAIL_ADDRESS,',
'               ADDRESS        = :P29_ADDRESS,',
'               ACTIVE_FLAG    = :P29_ACTIVE_FLAG,',
'               UPDATED_BY     = :APP_USER,',
'               UPDATED_DATE   = SYSDATE',
'         WHERE SUPPLIER_NO = :P29_SUPPLIER_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Supplier updated successfully.'';',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(12190015493808717)
,p_internal_uid=>12206537194808787
,p_created_on=>wwv_flow_imp.dz('20260831110803Z')
,p_updated_on=>wwv_flow_imp.dz('20260831110803Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
