wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(16717675257233108623)
,p_plug_name=>'SALES-REGISTER'
,p_static_id=>'register'
,p_region_name=>'purchase-register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (/* Formatted on 9/10/2026 4:31:24 PM (QP5 v5.388) */',
'  SELECT M.INVOICE_NO,',
'         M.INVOICE_CODE,',
'         M.INVOICE_DATE,',
'         C.CUSTOMER_NAME,',
'         NVL (D.TOTAL_AMOUNT, 0)     AS TOTAL_AMOUNT,',
'         NVL (D.NET_AMOUNT, 0)       AS NET_AMOUNT,',
'         ''Pending''                   AS APPROVAL_STATUS,',
'         M.CREATED_BY,',
'         M.CREATED_DATE',
'    FROM TRN_SALES_INVOICE_MST M',
'         JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = M.CUSTOMER_NO',
'         LEFT JOIN',
'         (  SELECT INVOICE_NO,',
'                   SUM (TOTAL_AMOUNT)     AS TOTAL_AMOUNT,',
'                   SUM (NET_AMOUNT)       AS NET_AMOUNT',
'              FROM TRN_SALES_INVOICE_DTL',
'          GROUP BY INVOICE_NO) D',
'             ON D.INVOICE_NO = M.INVOICE_NO',
'   WHERE M.APPROVAL_STATUS = ''P''',
'ORDER BY M.INVOICE_NO DESC);'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
