,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(12464614091822407)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Product Detail'
,p_static_id=>'initialize-form-product-detail'
,p_internal_uid=>12464799639822408
,p_created_on=>wwv_flow_imp.dz('20260903114713Z')
,p_updated_on=>wwv_flow_imp.dz('20260903114713Z')
