'        CREATED_BY,',
'        CREATED_DATE',
'    )',
'    VALUES',
'    (',
'        :P33_PRODUCT_NO,',
'        :P33_CATEGORY_NO,',
'        :P33_CUSTOMER_NO,',
'        :P33_DISCOUNT_PERCENT,',
'        NVL(:P33_PRIORITY, 1),',
'        NVL(:P33_EFFECTIVE_FROM, SYSDATE),',
'        :P33_EFFECTIVE_TO,',
'        NVL(:P33_ACTIVE_FLAG, 1),',
