,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SP.SALES_PRICE_NO,',
'       SP.PRODUCT_NO,',
'       P.PRODUCT_NAME,',
'       SP.CUSTOMER_NO,',
'       C.CUSTOMER_NAME,',
'       SP.UOM_NO,',
'       U.UOM_NAME,',
'       SP.SALES_RATE,',
'       SP.EFFECTIVE_DATE,',
'       SP.ACTIVE_FLAG,',
'       SP.CREATED_BY,',
'       SP.CREATED_DATE,',
'       SP.UPDATED_BY,',
'       SP.UPDATED_DATE',
