wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(15307498817803505)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(16735952323429778132)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Product Price Setup'
,p_static_id=>'initialize-form-product-price-setup'
,p_internal_uid=>15307498817803505
,p_created_on=>wwv_flow_imp.dz('20260907172222Z')
,p_updated_on=>wwv_flow_imp.dz('20260907172222Z')
