,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form UOM Conversion '
,p_static_id=>'initialize-form-uom-conversion'
,p_internal_uid=>15634981674708950
,p_created_on=>wwv_flow_imp.dz('20260913114821Z')
,p_updated_on=>wwv_flow_imp.dz('20260913114821Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(16478428711293911)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form UOM Conversion'
,p_static_id=>'process-form-uom-conversion'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_base_uom  NUMBER;',
'    l_count     NUMBER;',
'BEGIN',
'    -- Product validation',
'    IF :P36_PRODUCT_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please save product information first.''',
'        );',
'    END IF;',
'',
'    -- Get product base UOM',
'    BEGIN',
'        SELECT UOM_NO',
'          INTO l_base_uom',
'          FROM MST_PRODUCT',
'         WHERE PRODUCT_NO = :P36_PRODUCT_NO;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Product information not found.''',
'            );',
'    END;',
'',
'    -- Conversion UOM validation',
'    IF :P36_CONVERT_UOM_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select conversion UOM.''',
'        );',
'    END IF;',
'',
'    -- Base UOM cannot be conversion UOM',
'    IF :P36_CONVERT_UOM_NO = l_base_uom THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Base UOM cannot be used as conversion UOM.''',
'        );',
'    END IF;',
'',
'    -- Conversion factor validation',
'    IF NVL(:P36_CONVERSION_FACTOR, 0) <= 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Conversion factor must be greater than zero.''',
'        );',
'    END IF;',
'',
'    -- Duplicate conversion UOM check',
'    SELECT COUNT(*)',
'      INTO l_count',
'      FROM MST_UOM_CONVERSION',
'     WHERE PRODUCT_NO = :P36_PRODUCT_NO',
'       AND CONVERT_UOM_NO = :P36_CONVERT_UOM_NO',
'       AND CONVERSION_NO <> NVL(:P36_CONVERSION_NO, -1);',
'',
'    IF l_count > 0 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''This UOM conversion already exists for this product.''',
'        );',
'    END IF;',
'',
'    -- Insert',
'    IF :P36_CONVERSION_NO IS NULL THEN',
'',
'        INSERT INTO MST_UOM_CONVERSION',
'        (',
'            CONVERSION_NO,',
'            PRODUCT_NO,',
'            BASE_UOM_NO,',
'            CONVERT_UOM_NO,',
'            CONVERSION_FACTOR,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            SEQ_UOM_CONVERSION_NO.NEXTVAL,',
'            :P36_PRODUCT_NO,',
'            l_base_uom,',
'            :P36_CONVERT_UOM_NO,',
'            :P36_CONVERSION_FACTOR,',
'            NVL(:P36_ACTIVE_FLAG, ''1''),',
'            :APP_USER,',
'            SYSDATE',
'        )',
'        RETURNING CONVERSION_NO',
'        INTO :P36_CONVERSION_NO;',
'',
'    -- Update',
'    ELSE',
'',
'        UPDATE MST_UOM_CONVERSION',
'           SET BASE_UOM_NO = l_base_uom,',
'               CONVERT_UOM_NO = :P36_CONVERT_UOM_NO,',
'               CONVERSION_FACTOR = :P36_CONVERSION_FACTOR,',
'               ACTIVE_FLAG = NVL(:P36_ACTIVE_FLAG, ''1''),',
'               UPDATED_BY = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE CONVERSION_NO = :P36_CONVERSION_NO;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Conversion record not found.''',
'            );',
'        END IF;',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,UPDATE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>16478428711293911
,p_created_on=>wwv_flow_imp.dz('20260913114821Z')
,p_updated_on=>wwv_flow_imp.dz('20260913114821Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
end;
