,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Entry'
,p_static_id=>'process-form-entry'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P40_PRODUCT_NO IS NULL THEN',
'        INSERT INTO MST_PRODUCT (',
'            PRODUCT_NO,',
'            CATEGORY_NO,',
'            PRODUCT_CODE,',
'            PRODUCT_NAME,',
'            PURCHASE_RATE,',
'            SALES_RATE,',
'            MIN_STOCK_QTY,',
'            ACTIVE_FLAG,',
'            UOM_NO,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            SEQ_PRODUCT_NO.NEXTVAL,',
'            :P40_CATEGORY_NO,',
'           ''PRD'' || LPAD(SEQ_PRODUCT_NO.NEXTVAL,4,''0''),',
'            :P40_PRODUCT_NAME,',
'            :P40_PURCHASE_RATE,',
'            :P40_SALES_RATE,',
'            :P40_MIN_STOCK_QTY,',
'            :P40_ACTIVE_FLAG,',
'            :P40_UOM_NO,',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'          APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been saved successfully.'';',
'    ELSE',
'        UPDATE MST_PRODUCT',
'           SET CATEGORY_NO   = :P40_CATEGORY_NO,',
'               PRODUCT_NAME  = :P40_PRODUCT_NAME,',
'               PURCHASE_RATE = :P40_PURCHASE_RATE,',
'               SALES_RATE    = :P40_SALES_RATE,',
'               MIN_STOCK_QTY = :P40_MIN_STOCK_QTY,',
'               ACTIVE_FLAG   = :P40_ACTIVE_FLAG,',
'               UOM_NO        = :P40_UOM_NO,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE PRODUCT_NO    = :P40_PRODUCT_NO;',
'',
'         ',
'        APEX_APPLICATION.g_print_success_message :=',
'            ''Product has been updated successfully.'';',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(13652861265417500)
