,p_process_name=>'SAVE'
,p_static_id=>'save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P41_ROLE_NO IS NOT NULL THEN',
'',
'        INSERT INTO SA_ROLE (',
'            ROLE_NO,',
'            ROLE_CODE,',
'            ROLE_NAME,',
'            ACTIVE_FLAG,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            S_SA_ROLE.NEXTVAL,',
'            :P41_ROLE_CODE,',
'            :P41_ROLE_NAME,',
'            NVL(:P41_ACTIVE_FLAG, 1),',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
