,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE'
,p_static_id=>'save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_photo BLOB;',
'BEGIN',
'',
unistr('    /* Convert Base64 \2192 BLOB */'),
'    -- IF :P43_PHOTO IS NOT NULL THEN',
'    --     l_photo := apex_web_service.clobbase642blob(',
'    --         :P43_PHOTO',
'    --     );',
'    -- END IF;',
'',
'',
'    /* Save User */',
'    INSERT INTO SA_USER (',
'        USER_NO,',
'        USER_ID,',
'        USER_NAME,',
'        MOBILE_NO,',
'        DOB,',
'        USER_TYPE,',
'        EMAIL,',
'        PHOTO,',
'        USER_PWD,',
'        ACTIVE_STAT,',
'        AUTH_TYPE,',
'        ROLE_NO',
'    )',
'    VALUES (',
'        S_SA_USER.NEXTVAL,',
'        :P43_USER_ID,',
'        :P43_USER_NAME,',
'        :P43_MOBILE_NO,',
'        :P43_DOB,',
'        NVL(:P43_USER_TYPE, ''U''),',
'        :P43_EMAIL,',
'        :P43_PHOTO,--  l_photo,',
'        :P43_USER_PWD,',
'        NVL(:P43_ACTIVE_STAT, 1),',
'        :P43_AUTH_TYPE,',
'        :P43_ROLE_NO',
'    );',
'',
'',
'    apex_application.g_print_success_message :=',
'        ''User created successfully.'';',
'',
'',
'EXCEPTION',
'',
'    WHEN DUP_VAL_ON_INDEX THEN',
'        raise_application_error(',
'            -20001,',
'            ''User ID or User No already exists.''',
'        );',
'',
'END;',
'',
''))
