wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(14709690902244039)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'AJX_GRANT_OBJ'
,p_static_id=>'ajx-grant-obj'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/6/2026 5:44:58 PM (QP5 v5.388) */',
'DECLARE',
'    V_MSG   VARCHAR2 (100);',
'    V_PK    NUMBER;',
'',
'    CURSOR CUR_ROLE IS',
'        SELECT ROLE_NO',
'          FROM SA_ROLE',
'         WHERE     INSTR ('','' || APEX_APPLICATION.G_X01 || '','',',
'                          '','' || ROLE_NO || '','') >',
'                   0',
'               AND ACTIVE_FLAG = 1;',
'',
'    CURSOR CUR_MENU IS',
'        SELECT SUBMENU_NO',
'          FROM SA_SUBMENU',
'         WHERE INSTR ('','' || APEX_APPLICATION.G_X02 || '','',',
'                      '','' || SUBMENU_NO || '','') >',
'               0;',
'BEGIN',
'    APEX_JSON.OPEN_OBJECT;',
'',
'    FOR I IN CUR_ROLE',
'    LOOP',
'        FOR K IN CUR_MENU',
'        LOOP',
'            SELECT NVL (MAX (TO_NUMBER (GR_OBJECT_NO)), 0) + 1',
'              INTO V_PK',
'              FROM SA_GRANTOBJECT;',
'',
'            INSERT INTO SA_GRANTOBJECT (GR_OBJECT_NO,',
'                                        SUBMENU_NO,',
'                                        ROLE_NO,',
'                                        CAN_VIEW,',
'                                        CAN_MODIFY,',
'                                        CAN_REMOVE,',
'                                        CAN_SHARE,',
'                                        CAN_CREATE,',
'                                        ACTIVE_FLAG,',
'                                        USER_NO)',
'                 VALUES (V_PK,',
'                         K.SUBMENU_NO,',
'                         I.ROLE_NO,',
'                         1,',
'                         1,',
'                         1,',
'                         1,',
'                         1,',
'                         1,',
'                         -1);',
'        END LOOP;',
'    END LOOP;',
'',
'    V_MSG := ''Role Permission Granted Successfully'';',
'',
'    APEX_JSON.WRITE (''stat'', ''200'');',
'    APEX_JSON.WRITE (''message'', V_MSG);',
'    APEX_JSON.CLOSE_ALL;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN',
'        APEX_JSON.WRITE (''stat'', ''400'');',
'        APEX_JSON.WRITE (''message'', SQLERRM);',
'        APEX_JSON.CLOSE_ALL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14709690902244039
,p_created_on=>wwv_flow_imp.dz('20260906173227Z')
,p_updated_on=>wwv_flow_imp.dz('20260906175216Z')
,p_created_by=>'ADMIN'
,p_updated_by=>'ADMIN'
);
