wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(9121103063560444302)
,p_event_id=>wwv_flow_imp.id(9121102918437444301)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'apex.message.clearErrors();',
    '',
    'var returnQty  = parseFloat($v("RETURN_QTY")) || 0;',
    'var balanceQty = parseFloat($v("BALANCE_QTY")) || 0;',
    'var salesRate  = parseFloat($v("SALES_RATE")) || 0;',
    'var packQty    = parseFloat($v("PACK_QTY")) || 1;',
    '',
    'if (packQty <= 0) {',
    '    packQty = 1;',
    '}',
    '',
    'if (returnQty > balanceQty) {',
    '',
    '    apex.message.alert("Return quantity exceeds balance quantity.");',
    '',
    '    $s("RETURN_QTY", "");',
    '    $s("BASE_QTY", "");',
    '    $s("BASE_RATE", "");',
    '    $s("TOTAL_AMOUNT", "");',
    '',
    '    return;',
    '}',
    '',
    '/* Calculate */',
    '',
    'var baseQty  = returnQty * packQty;',
    'var baseRate = salesRate / packQty;',
    'var totalAmt = returnQty * salesRate;',
    '',
    '$s("BASE_QTY", baseQty.toFixed(3));',
    '$s("BASE_RATE", baseRate.toFixed(6));',
    '$s("TOTAL_AMOUNT", totalAmt.toFixed(2));')))).to_clob
);
