wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9054123658283761037)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form CUSTOMER RETURN MST'
,p_static_id=>'process-form-customer-return-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_status VARCHAR2(1);',
'',
'BEGIN',
'',
'    --------------------------------------------------',
'    -- Invoice Validation',
'    --------------------------------------------------',
'    IF :P102_INVOICE_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select an invoice.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- Return Date Validation',
'    --------------------------------------------------',
'    IF :P102_RETURN_DATE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter return date.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- Update Validation',
'    --------------------------------------------------',
'    IF :P102_RETURN_NO IS NOT NULL THEN',
'',
'        SELECT APPROVAL_STATUS',
'          INTO v_status',
'          FROM TRN_CUSTOMER_RETURN_MST',
'         WHERE RETURN_NO = :P102_RETURN_NO;',
'',
'        IF v_status <> ''P'' THEN',
'',
'            RAISE_APPLICATION_ERROR(',
'                -20001,',
'                ''Only pending return can be modified.''',
'            );',
'',
'        END IF;',
'',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- Insert',
'    --------------------------------------------------',
'    IF :P102_RETURN_NO IS NULL THEN',
'',
'        :P102_RETURN_NO := SEQ_RETURN_NO.NEXTVAL;',
'',
'        INSERT INTO TRN_CUSTOMER_RETURN_MST',
'        (',
'            RETURN_NO,',
'            RETURN_CODE,',
'            RETURN_DATE,',
'            INVOICE_NO,',
'            CUSTOMER_NO,',
'            RETURN_REASON,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            :P102_RETURN_NO,',
'            ''RET-'' || LPAD(:P102_RETURN_NO,6,''0''),',
'            :P102_RETURN_DATE,',
'            :P102_INVOICE_NO,',
'            :P102_CUSTOMER_NO,',
'            :P102_RETURN_REASON,',
'            ''P'',',
'            :APP_USER,',
'            SYSDATE',
'        );',
'',
'        apex_application.g_print_success_message :=',
'            ''Customer Return saved successfully.'';',
'',
'    --------------------------------------------------',
'    -- Update',
'    --------------------------------------------------',
'    ELSE',
'',
'        UPDATE TRN_CUSTOMER_RETURN_MST',
'           SET RETURN_DATE   = :P102_RETURN_DATE,',
'               INVOICE_NO    = :P102_INVOICE_NO,',
'               CUSTOMER_NO   = :P102_CUSTOMER_NO,',
'               RETURN_REASON = :P102_RETURN_REASON,',
'               UPDATED_BY    = :APP_USER,',
'               UPDATED_DATE  = SYSDATE',
'         WHERE RETURN_NO = :P102_RETURN_NO;',
'',
'        apex_application.g_print_success_message :=',
'            ''Customer Return updated successfully.'';',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9093637667389698777)
,p_internal_uid=>9054123658283761037
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11193744412514922921)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'RETURN_POPULATE'
,p_static_id=>'return-populate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    V_DATA CLOB;',
'BEGIN',
'',
'    SELECT JSON_ARRAYAGG',
'           (',
'               JSON_OBJECT(',
'',
'                   ''INVOICE_DTL_NO'' VALUE D.INVOICE_DTL_NO,',
'',
'                   ''ORDER_DTL_NO'' VALUE D.ORDER_DTL_NO,',
'',
'                   ''PRODUCT_NO'' VALUE D.PRODUCT_NO,',
'',
'                   ''PRODUCT_CODE'' VALUE P.PRODUCT_CODE,',
'',
'                   ''PRODUCT_NAME'' VALUE P.PRODUCT_NAME,',
'',
'                   ''DESCRIPTION'' VALUE P.DESCRIPTION,',
'',
'                   ''BRAND_NO'' VALUE P.BRAND_NO,',
'',
'                   ''UOM_NO'' VALUE D.UOM_NO,',
'',
'                   ''PACK_QTY'' VALUE D.PACK_QTY,',
'',
'                   ''BASE_QTY'' VALUE D.BASE_QTY,',
'',
'                   ''BASE_RATE'' VALUE D.BASE_RATE,',
'',
'                   ''INVOICE_QTY'' VALUE D.SALES_QTY,',
'',
'                   ''PREVIOUS_RETURN_QTY''',
'                       VALUE NVL',
'                       (',
'                           (',
'                               SELECT SUM(R.RETURN_QTY)',
'                                 FROM TRN_CUSTOMER_RETURN_DTL R',
'                                 JOIN TRN_CUSTOMER_RETURN_MST M',
'                                   ON M.RETURN_NO = R.RETURN_NO',
'                                WHERE R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                                  AND M.APPROVAL_STATUS = ''A''',
'                           ),',
'                           0',
'                       ),',
'',
'                   ''BALANCE_QTY''',
'                       VALUE',
'                       D.SALES_QTY',
'                       -',
'                       NVL',
'                       (',
'                           (',
'                               SELECT SUM(R.RETURN_QTY)',
'                                 FROM TRN_CUSTOMER_RETURN_DTL R',
'                                 JOIN TRN_CUSTOMER_RETURN_MST M',
'                                   ON M.RETURN_NO = R.RETURN_NO',
'                                WHERE R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                                  AND M.APPROVAL_STATUS = ''A''',
'                           ),',
'                           0',
'                       ),',
'',
'                   ''RETURN_QTY''',
'                       VALUE',
'                       D.SALES_QTY',
'                       -',
'                       NVL',
'                       (',
'                           (',
'                               SELECT SUM(R.RETURN_QTY)',
'                                 FROM TRN_CUSTOMER_RETURN_DTL R',
'                                 JOIN TRN_CUSTOMER_RETURN_MST M',
'                                   ON M.RETURN_NO = R.RETURN_NO',
'                                WHERE R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                                  AND M.APPROVAL_STATUS = ''A''',
'                           ),',
'                           0',
'                       ),',
'',
'                   ''SALES_RATE'' VALUE D.SALES_RATE,',
'',
'                   ''TOTAL_AMOUNT''',
'                       VALUE',
'                       (',
'                           D.SALES_QTY',
'                           -',
'                           NVL',
'                           (',
'                               (',
'                                   SELECT SUM(R.RETURN_QTY)',
'                                     FROM TRN_CUSTOMER_RETURN_DTL R',
'                                     JOIN TRN_CUSTOMER_RETURN_MST M',
'                                       ON M.RETURN_NO = R.RETURN_NO',
'                                    WHERE R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                                      AND M.APPROVAL_STATUS = ''A''',
'                               ),',
'                               0',
'                           )',
'                       )',
'                       * D.SALES_RATE',
'',
'               )',
'               RETURNING CLOB',
'           )',
'    INTO V_DATA',
'    FROM TRN_SALES_INVOICE_DTL D',
'         JOIN MST_PRODUCT P',
'           ON P.PRODUCT_NO = D.PRODUCT_NO',
'    WHERE D.INVOICE_NO = APEX_APPLICATION.G_X01',
'      AND D.SALES_QTY >',
'          NVL',
'          (',
'              (',
'                  SELECT SUM(R.RETURN_QTY)',
'                    FROM TRN_CUSTOMER_RETURN_DTL R',
'                    JOIN TRN_CUSTOMER_RETURN_MST M',
'                      ON M.RETURN_NO = R.RETURN_NO',
'                   WHERE R.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'                     AND M.APPROVAL_STATUS = ''A''',
'              ),',
'              0',
'          );',
'',
'    HTP.PRN(NVL(V_DATA,''[]''));',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.PRN(''[]'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>11193744412514922921
);
end;
/
prompt --application/pages/page_00103
begin
wwv_flow_imp_page.create_page(
 p_id=>103
,p_name=>'Sales Return Approval'
,p_alias=>'SALES-RETURN-APPROVAL'
,p_step_title=>'Sales Return Approval'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function f_openModal (returnNo){',
'  $s(''P103_RETURN_NO'',returnNo);',
'  openModal (''return_approve'');',
'  apex.region(''return-detail'').refresh();',
'}',
'',
'function approveReturn(returnNo) {',
'',
'    apex.message.confirm(',
'        "Are you sure you want to approve this Customer Return?",',
'        function (okPressed) {',
'',
'            if (okPressed) {',
'',
'                apex.server.process(',
'                    "APPROVE_RETURN",',
'                    {',
'                        x01: returnNo',
'                    },',
'                    {',
'                        dataType: "json",',
'',
'                        success: function (pData) {',
'',
'                            if (pData.status === "SUCCESS") {',
'',
'                                apex.message.showPageSuccess(pData.message);',
'',
'                                apex.region("return_list").refresh();',
'',
'                            } else {',
'',
'                                apex.message.alert(pData.message);',
'',
'                            }',
'                        },',
'',
'                        error: function (xhr, status, error) {',
'',
'                            apex.message.alert(',
'                                "Approval failed.<br>" + error',
'                            );',
'',
'                        }',
'                    }',
'                );',
'',
'            }',
'',
'        }',
'    );',
'',
'}',
'function rejectReturn(returnNo) {',
'',
'    apex.message.confirm(',
'        "Are you sure you want to reject this Customer Return?",',
'        function (okPressed) {',
'',
'            if (!okPressed) {',
'                return;',
'            }',
'',
'            apex.server.process(',
'                "RETURN_REJECT",',
'                {',
'                    x01: returnNo',
'                },',
'                {',
'                    dataType: "json",',
'',
'                    success: function (pData) {',
'',
'                        if (pData.status === "SUCCESS") {',
'',
'                            apex.message.showPageSuccess(pData.message);',
'',
'                            apex.region("return_list").refresh();',
'',
'                        } else {',
'',
'                            apex.message.alert(pData.message);',
'',
'                        }',
'                    },',
'',
'                    error: function (jqXHR) {',
'',
'                        apex.message.alert(',
'                            "Error: " + jqXHR.responseText',
'                        );',
'',
'                    }',
'                }',
'            );',
'',
'        }',
'    );',
'',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_last_updated_on=>wwv_flow_imp.dz('20260823162810Z')
