wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(25830576712421724617)
,p_plug_name=>'REGISTER'
,p_static_id=>'register'
,p_region_name=>'return_list'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       M.RETURN_NO,',
'       M.RETURN_CODE,',
'       M.RETURN_DATE,',
'       I.INVOICE_CODE,',
'       I.INVOICE_DATE,',
'       C.CUSTOMER_NAME,',
'       C.MOBILE_NO,',
'       M.RETURN_REASON,',
'       (',
'           SELECT NVL(SUM(D.RETURN_QTY),0)',
'             FROM TRN_CUSTOMER_RETURN_DTL D',
'            WHERE D.RETURN_NO = M.RETURN_NO',
'       ) TOTAL_QTY,',
'       (',
'           SELECT NVL(SUM(D.TOTAL_AMOUNT),0)',
'             FROM TRN_CUSTOMER_RETURN_DTL D',
'            WHERE D.RETURN_NO = M.RETURN_NO',
'       ) TOTAL_AMOUNT,',
'       CASE M.APPROVAL_STATUS',
'           WHEN ''P'' THEN',
'               ''<span class="t-Badge t-Badge--warning">',
'                Pending',
'                </span>''',
'',
'           WHEN ''A'' THEN',
'               ''<span class="t-Badge t-Badge--success">',
'                Approved',
'                </span>''',
'',
'           WHEN ''R'' THEN',
'               ''<span class="t-Badge t-Badge--danger">',
'                Rejected',
'                </span>''',
'       END APPROVAL_STATUS,',
'       M.CREATED_BY,',
'       M.CREATED_DATE,',
'         0 DETAILS_BTN',
'FROM TRN_CUSTOMER_RETURN_MST M',
'JOIN TRN_SALES_INVOICE_MST I',
'  ON I.INVOICE_NO = M.INVOICE_NO',
'JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = M.CUSTOMER_NO',
'WHERE  M.APPROVAL_STATUS = ''P''',
'ORDER BY M.RETURN_NO DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
