,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET INVOICE DATA'
,p_static_id=>'new'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/31/2026 3:51:00 PM (QP5 v5.388) */',
'BEGIN',
'      SELECT I.INVOICE_DATE,',
'             C.CUSTOMER_NAME,',
'             C.MOBILE_NO,',
'             C.ADDRESS,',
'             c.CUSTOMER_NO',
'        INTO :P105_INVOICE_DATE,',
'             :P105_CUSTOMER_NAME,',
'             :P105_MOBILE_NO,',
'             :P105_DELIVERY_ADDRESS,',
'             :P105_CUSTOMER_NO',
'        FROM TRN_SALES_INVOICE_MST I',
'             JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'       WHERE INVOICE_NO = :P105_INVOICE_NO',
'    ORDER BY I.INVOICE_NO DESC;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        NULL;',
'END;'))
