wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10326851552040576604)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form DELIVERY MST'
,p_static_id=>'process-form-delivery-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    BEGIN',
'',
'    IF :P105_INVOICE_NO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select invoice.''',
'        );',
'    END IF;',
'',
'END;',
'',
'',
'    IF :P105_DELIVERY_NO IS NULL THEN',
'        -- INSERT',
'                :P105_DELIVERY_NO := SEQ_DELIVERY_NO.NEXTVAL;',
'        INSERT INTO TRN_DELIVERY_MST (',
'            DELIVERY_NO,',
'            DELIVERY_CODE,',
'            DELIVERY_DATE,',
'            INVOICE_NO,',
'            CUSTOMER_NO,',
'            DELIVERY_ADDRESS,',
'            DELIVERY_PERSON,',
'            VEHICLE_NO,',
'            CONTACT_NO,',
'            REMARKS,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES (',
'            :P105_DELIVERY_NO,',
'            ''DEL-''||LPAD(:P105_DELIVERY_NO,4,''0''),',
'            :P105_DELIVERY_DATE,',
'            :P105_INVOICE_NO,',
'            :P105_CUSTOMER_NO,',
'            :P105_DELIVERY_ADDRESS,',
'            :P105_DELIVERY_PERSON,',
'            :P105_VEHICLE_NO,',
'            :P105_CONTACT_NO,',
'            :P105_REMARKS,',
'            ''P'',',
'            :APP_USER,',
'            SYSDATE',
'        );',
'        apex_application.g_print_success_message :=',
'            ''Delivery Created Successfully!'';',
'    ',
'    ELSE',
'        -- UPDATE',
'        UPDATE TRN_DELIVERY_MST',
'           SET',
'               DELIVERY_DATE     = :P105_DELIVERY_DATE,',
'               INVOICE_NO        = :P105_INVOICE_NO,',
'               CUSTOMER_NO       = :P105_CUSTOMER_NO,',
'               DELIVERY_ADDRESS  = :P105_DELIVERY_ADDRESS,',
'               DELIVERY_PERSON   = :P105_DELIVERY_PERSON,',
'               VEHICLE_NO        = :P105_VEHICLE_NO,',
'               CONTACT_NO        = :P105_CONTACT_NO,',
'               REMARKS           = :P105_REMARKS,',
'               UPDATED_BY        = :APP_USER,',
'               UPDATED_DATE      = SYSDATE',
'         WHERE DELIVERY_NO = :P105_DELIVERY_NO;',
'             apex_application.g_print_success_message :=',
'            ''Delivery Updated Successfully!'';',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10327105834897918512)
,p_internal_uid=>10326851552040576604
);
end;
