,p_step_title=>'Delivery Challan Approval'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function f_openModal(deliveryNo) {',
'',
'    apex.item("P106_DELIVERY_NO").setValue(deliveryNo);',
'',
'    openModal(''challan_approve'');',
'',
'    apex.region(''challan-detail'').refresh();',
'',
'}',
'',
'',
'function approveDelivery(pdeliveryNo) {',
'            if (!confirm(''Are you sure you want to Delivery this Invoice ?'')) {',
'        return;',
'    }',
'    apex.server.process(',
unistr('        ''APPROVE_DELIVERY'',   // Callback process \09A8\09BE\09AE'),
'        {',
unistr('            x01: pdeliveryNo  // delivery no \09AA\09BE\09A0\09BE\099A\09CD\099B\09BF'),
'        },',
'        {',
'            success: function (data) {',
'                if (data.status === ''SUCCESS'') {',
'                    apex.message.showPageSuccess(data.message);',
unistr('                    // \09AA\09CD\09B0\09AF\09BC\09CB\099C\09A8\09C7 region refresh \0995\09B0\09CB'),
'                    apex.region(''challan-detail'').refresh();',
'                } else {',
'                    apex.message.showErrors([{',
'                        type: ''error'',',
'                        location: ''page'',',
'                        message: data.message,',
'                        unsafe: false',
'                    }]);',
'                }',
'            },',
'            error: function (err) {',
'                apex.message.showErrors([{',
'                    type: ''error'',',
'                    location: ''page'',',
'                    message: ''Unexpected error occurred.'',',
'                    unsafe: false',
'                }]);',
'            }',
'        }',
'    );',
'',
'}',
'',
'',
'function rejectPurchase(pPurchaseNo) {',
'',
'    if (!confirm(''Are you sure you want to reject this purchase?'')) {',
'        return;',
'    }',
'',
'    apex.server.process(',
'        "REJECT_PURCHASE",',
'        {',
'            x01: pPurchaseNo',
'        },',
'        {',
'            dataType: "text",',
'            success: function (pData) {',
'',
'                if (pData === "SUCCESS") {',
'',
'                    apex.message.showPageSuccess(',
'                        "Challan rejected successfully."',
'                    );',
'',
'                    apex.region("challan-detail").refresh();',
'',
'                } else {',
'',
'                    apex.message.alert(pData);',
'',
'                }',
'            },',
'            error: function () {',
'',
'                apex.message.alert(',
'                    "Unable to process request."',
'                );',
'',
'            }',
'        }',
'    );',
'',
'}'))
