,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ROW_NUMBER() OVER (',
'           ORDER BY D.DELIVERY_DTL_NO',
'       ) AS SL,',
'       P.PRODUCT_CODE,',
'       P.PRODUCT_NAME,',
'       D.PACK_QTY,',
'       D.BASE_QTY,',
'       D.INVOICE_QTY,',
'       D.PREVIOUS_DELIVERY_QTY,',
'       D.DELIVERY_QTY,',
'       D.BALANCE_QTY,',
'       D.SALES_RATE,',
'       NVL(ID.DISCOUNT_PERCENT, 0) AS DISCOUNT_PERCENT,',
'       D.TOTAL_AMOUNT,',
'       D.NET_AMOUNT,',
'       D.REMARKS',
'FROM TRN_DELIVERY_DTL D',
'JOIN MST_PRODUCT P',
'  ON P.PRODUCT_NO = D.PRODUCT_NO',
'LEFT JOIN TRN_SALES_INVOICE_DTL ID',
'  ON ID.INVOICE_DTL_NO = D.INVOICE_DTL_NO',
'WHERE D.DELIVERY_NO = :P106_DELIVERY_NO',
'ORDER BY D.DELIVERY_DTL_NO;'))
