wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(61537974166152823)
,p_plug_name=>'Stock Report'
,p_static_id=>'sales-report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/6/2026 12:00:22 PM (QP5 v5.388) */',
'WITH',
'    STOCK_SUMMARY',
'    AS',
'        (  SELECT P.PRODUCT_NO,',
'                  P.PRODUCT_CODE,',
'                  P.PRODUCT_NAME,',
'                  C.CATEGORY_NAME,',
'                  NVL (P.PURCHASE_RATE, 0)',
'                      AS PURCHASE_RATE,',
'                  NVL (P.SALES_RATE, 0)',
'                      AS SALES_RATE,',
'                  NVL (P.MIN_STOCK_QTY, 0)',
'                      AS MINIMUM_STOCK,',
'                  NVL (SUM (L.QTY_IN), 0)',
'                      AS STOCK_RECEIVED,',
'                  NVL (SUM (L.QTY_OUT), 0)',
'                      AS STOCK_SOLD,',
'                  NVL (SUM (L.QTY_IN), 0) - NVL (SUM (L.QTY_OUT), 0)',
'                      AS CURRENT_STOCK,',
'                  ROUND (',
'                        (NVL (SUM (L.QTY_IN), 0) - NVL (SUM (L.QTY_OUT), 0))',
'                      * NVL (P.PURCHASE_RATE, 0),',
'                      2)',
'                      AS STOCK_VALUE',
'             FROM MST_PRODUCT P',
'                  LEFT JOIN MST_PRODUCT_CATEGORY C',
'                      ON C.CATEGORY_NO = P.CATEGORY_NO',
'                  LEFT JOIN TRN_STOCK_LEDGER L ON L.PRODUCT_NO = P.PRODUCT_NO',
'            WHERE     (   :P204_CATEGORY_NO IS NULL',
'                       OR P.CATEGORY_NO = :P204_CATEGORY_NO)',
'                  AND ( :P204_PRODUCT_NO IS NULL OR P.PRODUCT_NO = :P204_PRODUCT_NO)',
'         GROUP BY P.PRODUCT_NO,',
'                  P.PRODUCT_CODE,',
'                  P.PRODUCT_NAME,',
'                  C.CATEGORY_NAME,',
'                  P.PURCHASE_RATE,',
'                  P.SALES_RATE,',
'                  P.MIN_STOCK_QTY)',
'  SELECT PRODUCT_CODE      AS "Product Code",',
'         PRODUCT_NAME      AS "Product Name",',
'         CATEGORY_NAME     AS "Category",',
'         PURCHASE_RATE     AS "Purchase Rate",',
'         SALES_RATE        AS "Sales Rate",',
'         MINIMUM_STOCK     AS "Minimum Stock",',
'         STOCK_RECEIVED    AS "Stock Received",',
'         STOCK_SOLD        AS "Stock Sold",',
'         CURRENT_STOCK     AS "Available Stock",',
'         STOCK_VALUE       AS "Stock Value",',
'         CASE',
'             WHEN CURRENT_STOCK <= 0 THEN ''Out of Stock''',
'             WHEN CURRENT_STOCK < MINIMUM_STOCK THEN ''Low Stock''',
'             ELSE ''Available''',
'         END               AS "Stock Status"',
'    FROM STOCK_SUMMARY',
'   WHERE (   :P204_STATUS IS NULL',
'          OR :P204_STATUS = ''ALL''',
'          OR ( :P204_STATUS = ''A'' AND CURRENT_STOCK >= MINIMUM_STOCK)',
'          OR (    :P204_STATUS = ''L''',
'              AND CURRENT_STOCK > 0',
'              AND CURRENT_STOCK < MINIMUM_STOCK)',
'          OR ( :P204_STATUS = ''O'' AND CURRENT_STOCK <= 0))',
'ORDER BY PRODUCT_NAME;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P204_CATEGORY_NO,P204_PRODUCT_NO,P204_STATUS'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
