wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(23523479038388334)
,p_plug_name=>'customer ladger'
,p_static_id=>'sales-report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH LEDGER_ENTRIES AS (',
'    /* Sales Invoice = Debit */',
'    SELECT I.INVOICE_DATE AS TXN_DATE,',
'           I.INVOICE_NO AS DOCUMENT_NO,',
'           I.INVOICE_CODE AS DOCUMENT_CODE,',
'           I.CUSTOMER_NO,',
'           C.CUSTOMER_NAME,',
'           ''INVOICE'' AS TRANSACTION_TYPE,',
'           NVL(I.NET_AMOUNT,0) AS DEBIT_AMOUNT,',
'           0 AS CREDIT_AMOUNT',
'      FROM TRN_SALES_INVOICE_MST I',
'      JOIN MST_CUSTOMER C',
'        ON C.CUSTOMER_NO=I.CUSTOMER_NO',
'     WHERE I.APPROVAL_STATUS=''A''',
'       AND (:P205_CUSTOMER IS NULL OR I.CUSTOMER_NO=:P205_CUSTOMER)',
'',
'    UNION ALL',
'',
'    /* Customer Receipt = Credit */',
'    SELECT T.TRANSACTION_DATE AS TXN_DATE,',
'           T.TRANSACTION_NO AS DOCUMENT_NO,',
'           T.TRANSACTION_CODE AS DOCUMENT_CODE,',
'           T.PARTY_NO AS CUSTOMER_NO,',
'           C.CUSTOMER_NAME,',
'           ''RECEIPT'' AS TRANSACTION_TYPE,',
'           0 AS DEBIT_AMOUNT,',
'           NVL(SUM(D.ALLOCATE_AMOUNT),0) AS CREDIT_AMOUNT',
'      FROM TRN_TRANSACTION_MST T',
'      JOIN TRN_TRANSACTION_DTL D',
'        ON D.TRANSACTION_NO=T.TRANSACTION_NO',
'      JOIN MST_CUSTOMER C',
'        ON C.CUSTOMER_NO=T.PARTY_NO',
'     WHERE T.TRANSACTION_TYPE=''R''',
'       AND T.APPROVAL_STATUS=''A''',
'       AND (:P205_CUSTOMER IS NULL OR T.PARTY_NO=:P205_CUSTOMER)',
'     GROUP BY T.TRANSACTION_DATE,',
'              T.TRANSACTION_NO,',
'              T.TRANSACTION_CODE,',
'              T.PARTY_NO,',
'              C.CUSTOMER_NAME',
'),',
'OPENING_BALANCE AS (',
'    SELECT CUSTOMER_NO,',
'           SUM(DEBIT_AMOUNT)-SUM(CREDIT_AMOUNT) AS OPENING_BALANCE',
'      FROM LEDGER_ENTRIES',
'     WHERE TXN_DATE<TO_DATE(:P205_FROM_DATE,''MM/DD/YYYY'')',
'     GROUP BY CUSTOMER_NO',
'),',
'PERIOD_ENTRIES AS (',
'    SELECT *',
'      FROM LEDGER_ENTRIES',
'     WHERE TXN_DATE>=TO_DATE(:P205_FROM_DATE,''MM/DD/YYYY'')',
'       AND TXN_DATE<TO_DATE(:P205_T0_DATE,''MM/DD/YYYY'')+1',
')',
'SELECT P.TXN_DATE,',
'       P.DOCUMENT_NO,',
'       P.DOCUMENT_CODE,',
'       P.CUSTOMER_NO,',
'       P.CUSTOMER_NAME,',
'       P.TRANSACTION_TYPE,',
'       NVL(O.OPENING_BALANCE,0) AS OPENING_BALANCE,',
'       P.DEBIT_AMOUNT,',
'       P.CREDIT_AMOUNT,',
'       NVL(O.OPENING_BALANCE,0)',
'       + SUM(P.DEBIT_AMOUNT-P.CREDIT_AMOUNT)',
'         OVER(',
'             PARTITION BY P.CUSTOMER_NO',
'             ORDER BY P.TXN_DATE,P.DOCUMENT_NO',
'             ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW',
'         ) AS RUNNING_BALANCE',
'  FROM PERIOD_ENTRIES P',
'  LEFT JOIN OPENING_BALANCE O',
'    ON O.CUSTOMER_NO=P.CUSTOMER_NO',
' ORDER BY P.CUSTOMER_NO,',
'          P.TXN_DATE,',
'          P.DOCUMENT_NO;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P205_FROM_DATE,P205_T0_DATE,P205_CUSTOMER'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
