wwv_flow_imp_page.create_page(
 p_id=>207
,p_name=>'Daily Invoice'
,p_alias=>'DAILY-INVOICE1'
,p_step_title=>'Daily Invoice'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function printSingleInvoice(btn) {',
'',
'    var invoice = btn.closest(".inv-report-card");',
'',
'    if (!invoice) return;',
'',
'    var printWindow = window.open("", "_blank", "width=950,height=750");',
'',
'    if (!printWindow) {',
'        apex.message.alert("Please allow pop-ups for this site.");',
'        return;',
'    }',
'',
'    var styles = "";',
'',
'    document.querySelectorAll("link[rel=''stylesheet''], style")',
'        .forEach(function(el) {',
'            styles += el.outerHTML;',
'        });',
'',
'    printWindow.document.write(`',
'        <html>',
'        <head>',
'            <title>Invoice</title>',
'',
'            ${styles}',
'',
'            <style>',
'                @page {',
'                    size: A4;',
'                    margin: 10mm;',
'                }',
'',
'                .invoice-print-btn {',
'                    display: none !important;',
'                }',
'            </style>',
'        </head>',
'',
'        <body>',
'            ${invoice.outerHTML}',
'        </body>',
'        </html>',
'    `);',
'',
'    printWindow.document.close();',
'',
'    setTimeout(function () {',
'        printWindow.print();',
'        printWindow.close();',
'    }, 700);',
'}'))
,p_step_template=>4073832297226169690
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'25'
,p_created_on=>wwv_flow_imp.dz('20260829130906Z')
,p_last_updated_on=>wwv_flow_imp.dz('20260914142050Z')
,p_created_by=>'ADMIN'
,p_last_updated_by=>'ADMIN'
);
