wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(34683897350730295)
,p_plug_name=>'Daily Invoice Register'
,p_static_id=>'sales-report'
,p_parent_plug_id=>wwv_flow_imp.id(11823936281848531)
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>70
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 9/14/2026 1:47:13 PM (QP5 v5.388) */',
'  SELECT I.INVOICE_CODE                             AS "Invoice No",',
'         TO_CHAR (I.INVOICE_DATE, ''DD-MON-YYYY'')    AS "Date",',
'         C.CUSTOMER_NAME                            AS "Customer",',
'         C.MOBILE_NO                                AS "Mobile No",',
'         /* Products */',
'          (SELECT LISTAGG (P.PRODUCT_NAME, '', '')',
'                      WITHIN GROUP (ORDER BY D2.INVOICE_DTL_NO)',
'           FROM TRN_SALES_INVOICE_DTL D2',
'                JOIN MST_PRODUCT P ON P.PRODUCT_NO = D2.PRODUCT_NO',
'          WHERE D2.INVOICE_NO = I.INVOICE_NO)       AS "Products",',
'         /* Quantity */',
'          (SELECT LISTAGG (TO_CHAR (NVL (D2.SALES_QTY, 0)), '', '')',
'                      WITHIN GROUP (ORDER BY D2.INVOICE_DTL_NO)',
'           FROM TRN_SALES_INVOICE_DTL D2',
'          WHERE D2.INVOICE_NO = I.INVOICE_NO)       AS "Qty",',
'         /* Gross */',
'          (SELECT NVL (SUM (NVL (D2.SALES_QTY, 0) * NVL (D2.SALES_RATE, 0)), 0)',
'             FROM TRN_SALES_INVOICE_DTL D2',
'            WHERE D2.INVOICE_NO = I.INVOICE_NO)     AS "Gross",',
'         /* Discount */',
'          (SELECT NVL (SUM (NVL (D2.DISCOUNT_AMOUNT, 0)), 0)',
'             FROM TRN_SALES_INVOICE_DTL D2',
'            WHERE D2.INVOICE_NO = I.INVOICE_NO)     AS "Discount",',
'         /* Net */',
'         NVL (I.TOTAL_AMOUNT, 0)                    AS "Net",',
'         /* Payment */',
'         NVL (I.RECEIVED_AMOUNT, 0)                 AS "Received",',
'         NVL (I.DUE_AMOUNT, 0)                      AS "Due",',
'         CASE I.PAYMENT_STATUS',
'             WHEN ''UP'' THEN ''Unpaid''',
'             WHEN ''PP'' THEN ''Partial''',
'             WHEN ''P'' THEN ''Paid''',
'             ELSE I.PAYMENT_STATUS',
'         END                                        AS "Payment",',
'         /* Delivery */',
'         CASE I.DELIVERY_STATUS',
'             WHEN ''P'' THEN ''Pending''',
'             WHEN ''D'' THEN ''Delivered''',
'             ELSE I.DELIVERY_STATUS',
'         END                                        AS "Delivery",',
'         /* Return */',
'         NVL (',
'             (SELECT SUM (NVL (RD.RETURN_QTY, 0))',
'               FROM TRN_CUSTOMER_RETURN_DTL RD',
'                    JOIN TRN_CUSTOMER_RETURN_MST RM',
'                        ON RM.RETURN_NO = RD.RETURN_NO',
'                    JOIN TRN_SALES_INVOICE_DTL SD',
'                        ON SD.INVOICE_DTL_NO = RD.INVOICE_DTL_NO',
'              WHERE RM.APPROVAL_STATUS = ''A'' AND SD.INVOICE_NO = I.INVOICE_NO),',
'             0)                                     AS "Return"',
'    FROM TRN_SALES_INVOICE_MST I',
'         LEFT JOIN MST_CUSTOMER C ON C.CUSTOMER_NO = I.CUSTOMER_NO',
'   WHERE     I.INVOICE_DATE >=',
'             NVL (TO_DATE ( :P207_FROM_DATE, ''MM/DD/YYYY''), TRUNC (SYSDATE))',
'         AND I.INVOICE_DATE <',
'             NVL (TO_DATE ( :P207_TO_DATE, ''MM/DD/YYYY''), TRUNC (SYSDATE)) + 1',
'         AND ( :P207_CUSTOMER_NO IS NULL OR I.CUSTOMER_NO = :P207_CUSTOMER_NO)',
'         AND ( :P207_INVOICE_NO IS NULL OR I.INVOICE_NO = :P207_INVOICE_NO)',
'ORDER BY I.INVOICE_DATE DESC, I.INVOICE_NO DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P207_FROM_DATE,P207_TO_DATE,P207_CUSTOMER_NO,P207_INVOICE_NO'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
