wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13145828349600698126)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form VOUCHER MST'
,p_static_id=>'process-form-voucher-mst'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_code VARCHAR2(30);',
'',
'BEGIN',
'',
'    IF :P301_VOUCHER_DATE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter voucher date.''',
'        );',
'    END IF;',
'',
'    IF :P301_VOUCHER_TYPE IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please select voucher type.''',
'        );',
'    END IF;',
'',
'    --------------------------------------------------',
'    -- INSERT',
'    --------------------------------------------------',
'',
'    IF :P301_VOUCHER_NO IS NULL THEN',
'',
'        :P301_VOUCHER_NO :=',
'            SEQ_VOUCHER_NO.NEXTVAL;',
'',
'        v_code :=',
'            :P301_VOUCHER_TYPE',
'            || ''-''',
'            || LPAD(:P301_VOUCHER_NO,6,''0'');',
'',
'        INSERT INTO ACC_VOUCHER_MST',
'        (',
'            VOUCHER_NO,',
'            VOUCHER_CODE,',
'            VOUCHER_DATE,',
'            VOUCHER_TYPE,',
'            NARRATION,',
'            APPROVAL_STATUS,',
'            CREATED_BY,',
'            CREATED_DATE',
'        )',
'        VALUES',
'        (',
'            :P301_VOUCHER_NO,',
'            v_code,',
'            :P301_VOUCHER_DATE,',
'            :P301_VOUCHER_TYPE,',
'            :P301_NARRATION,',
'            ''A'',',
'            :APP_USER,',
'            SYSDATE',
'        ) RETURNING VOUCHER_NO INTO :P301_VOUCHER_NO ;',
'',
'    --------------------------------------------------',
'    -- UPDATE',
'    --------------------------------------------------',
'',
'    ELSE',
'',
'        UPDATE ACC_VOUCHER_MST',
'           SET VOUCHER_DATE = :P301_VOUCHER_DATE,',
'               VOUCHER_TYPE = :P301_VOUCHER_TYPE,',
'               NARRATION    = :P301_NARRATION,',
'               UPDATED_BY   = :APP_USER,',
'               UPDATED_DATE = SYSDATE',
'         WHERE VOUCHER_NO = :P301_VOUCHER_NO;',
'',
'    END IF;',
'',
'    apex_application.g_print_success_message :=',
'        ''Voucher saved successfully.'';',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(13144158047371654372)
,p_internal_uid=>13145828349600698126
,p_updated_on=>wwv_flow_imp.dz('20260825135134Z')
,p_updated_by=>'ADMIN'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13145828678709698129)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(13145827558607698118)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'VOUCHER MST - Save Interactive Grid Data'
,p_static_id=>'voucher-mst-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'    v_status VARCHAR2(1);',
'',
'BEGIN',
'',
'    -------------------------------------------------',
'    -- Approved Check',
'    -------------------------------------------------',
'begin',
'    SELECT APPROVAL_STATUS',
'      INTO v_status',
'      FROM ACC_VOUCHER_MST',
'     WHERE VOUCHER_NO = :P301_VOUCHER_NO;',
'    IF v_status = ''A'' THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Approved voucher cannot be modified.''',
'        );',
'    END IF;',
'    EXCEPTION ',
'    WHEN NO_DATA_FOUND THEN NULL;',
'    ',
'end;',
'    -------------------------------------------------',
'    -- Validation',
'    -------------------------------------------------',
'',
'    IF NVL(:DEBIT_AMOUNT,0) = 0',
'       AND NVL(:CREDIT_AMOUNT,0) = 0',
'    THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Please enter debit or credit amount.''',
'        );',
'',
'    END IF;',
'',
'    IF NVL(:DEBIT_AMOUNT,0) > 0',
'       AND NVL(:CREDIT_AMOUNT,0) > 0',
'    THEN',
'',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''Both debit and credit are not allowed.''',
'        );',
'',
'    END IF;',
'',
'    -------------------------------------------------',
'    -- INSERT',
'    -------------------------------------------------',
'',
'    IF :APEX$ROW_STATUS = ''C'' THEN',
'',
'        INSERT INTO ACC_VOUCHER_DTL',
'        (',
'            VOUCHER_DTL_NO,',
'            VOUCHER_NO,',
'            ACCOUNT_NO,',
'            PARTICULARS,',
'            DEBIT_AMOUNT,',
'            CREDIT_AMOUNT',
'        )',
'        VALUES',
'        (',
'            SEQ_VOUCHER_DTL_NO.NEXTVAL,',
'            :P301_VOUCHER_NO,',
'            :ACCOUNT_NO,',
'            :PARTICULARS,',
'            NVL(:DEBIT_AMOUNT,0),',
'            NVL(:CREDIT_AMOUNT,0)',
'        );',
'',
'    -------------------------------------------------',
'    -- UPDATE',
'    -------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''U'' THEN',
'',
'        UPDATE ACC_VOUCHER_DTL',
'           SET ACCOUNT_NO   = :ACCOUNT_NO,',
'               PARTICULARS  = :PARTICULARS,',
'               DEBIT_AMOUNT = NVL(:DEBIT_AMOUNT,0),',
'               CREDIT_AMOUNT= NVL(:CREDIT_AMOUNT,0)',
'         WHERE VOUCHER_DTL_NO =',
'               :VOUCHER_DTL_NO;',
'',
'    -------------------------------------------------',
'    -- DELETE',
'    -------------------------------------------------',
'',
'    ELSIF :APEX$ROW_STATUS = ''D'' THEN',
'',
'        DELETE',
'          FROM ACC_VOUCHER_DTL',
'         WHERE VOUCHER_DTL_NO =',
'               :VOUCHER_DTL_NO;',
'',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(13144158047371654372)
,p_internal_uid=>13145828678709698129
,p_updated_on=>wwv_flow_imp.dz('20260901130027Z')
,p_updated_by=>'ADMIN'
);
end;
