wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(27187647865163699380)
,p_plug_name=>'VOUCHER '
,p_static_id=>'voucher-mst'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_html           CLOB;',
'',
'    v_voucher_no     VARCHAR2(100);',
'    v_voucher_code   VARCHAR2(100);',
'    v_voucher_date   VARCHAR2(50);',
'    v_voucher_type   VARCHAR2(100);',
'    v_narration      VARCHAR2(4000);',
'    v_created_by     VARCHAR2(200);',
'',
'    v_total_dr       NUMBER := 0;',
'    v_total_cr       NUMBER := 0;',
'',
'',
'    /* =========================================================',
'       NUMBER TO WORDS',
'       Bangladesh / Indian Numbering System',
'       Crore -> Lakh -> Thousand -> Hundred',
'       ========================================================= */',
'',
'    FUNCTION number_to_words(p_num NUMBER)',
'        RETURN VARCHAR2',
'    IS',
'        v_num   NUMBER := TRUNC(NVL(p_num, 0));',
'        v_words VARCHAR2(4000);',
'',
'',
'        /* =====================================================',
'           TWO DIGIT WORDS',
'           ===================================================== */',
'',
'        FUNCTION two_digit_words(p NUMBER)',
'            RETURN VARCHAR2',
'        IS',
'            v_result VARCHAR2(200);',
'            v_tens   NUMBER;',
'            v_ones   NUMBER;',
'        BEGIN',
'',
'            IF p < 20 THEN',
'',
'                v_result :=',
'                    CASE p',
'                        WHEN 0  THEN ''Zero''',
'                        WHEN 1  THEN ''One''',
'                        WHEN 2  THEN ''Two''',
'                        WHEN 3  THEN ''Three''',
'                        WHEN 4  THEN ''Four''',
'                        WHEN 5  THEN ''Five''',
'                        WHEN 6  THEN ''Six''',
'                        WHEN 7  THEN ''Seven''',
'                        WHEN 8  THEN ''Eight''',
'                        WHEN 9  THEN ''Nine''',
'                        WHEN 10 THEN ''Ten''',
'                        WHEN 11 THEN ''Eleven''',
'                        WHEN 12 THEN ''Twelve''',
'                        WHEN 13 THEN ''Thirteen''',
'                        WHEN 14 THEN ''Fourteen''',
'                        WHEN 15 THEN ''Fifteen''',
'                        WHEN 16 THEN ''Sixteen''',
'                        WHEN 17 THEN ''Seventeen''',
'                        WHEN 18 THEN ''Eighteen''',
'                        WHEN 19 THEN ''Nineteen''',
'                    END;',
'',
'            ELSE',
'',
'                v_tens := TRUNC(p / 10);',
'                v_ones := MOD(p, 10);',
'',
'                v_result :=',
'                    CASE v_tens',
'                        WHEN 2 THEN ''Twenty''',
'                        WHEN 3 THEN ''Thirty''',
'                        WHEN 4 THEN ''Forty''',
'                        WHEN 5 THEN ''Fifty''',
'                        WHEN 6 THEN ''Sixty''',
'                        WHEN 7 THEN ''Seventy''',
'                        WHEN 8 THEN ''Eighty''',
'                        WHEN 9 THEN ''Ninety''',
'                    END;',
'',
'                IF v_ones > 0 THEN',
'',
'                    v_result :=',
'                        v_result || '' '' ||',
'                        CASE v_ones',
'                            WHEN 1 THEN ''One''',
'                            WHEN 2 THEN ''Two''',
'                            WHEN 3 THEN ''Three''',
'                            WHEN 4 THEN ''Four''',
'                            WHEN 5 THEN ''Five''',
'                            WHEN 6 THEN ''Six''',
'                            WHEN 7 THEN ''Seven''',
'                            WHEN 8 THEN ''Eight''',
'                            WHEN 9 THEN ''Nine''',
'                        END;',
'',
'                END IF;',
'',
'            END IF;',
'',
'            RETURN v_result;',
'',
'        END two_digit_words;',
'',
'',
'        /* =====================================================',
'           THREE DIGIT WORDS',
'           ===================================================== */',
'',
'        FUNCTION three_digit_words(p NUMBER)',
'            RETURN VARCHAR2',
'        IS',
'            v_result   VARCHAR2(300);',
'            v_hundreds NUMBER;',
'            v_rem      NUMBER;',
'        BEGIN',
'',
'            v_hundreds := TRUNC(p / 100);',
'            v_rem      := MOD(p, 100);',
'',
'            IF v_hundreds > 0 THEN',
'',
'                v_result :=',
'                    CASE v_hundreds',
'                        WHEN 1 THEN ''One''',
'                        WHEN 2 THEN ''Two''',
'                        WHEN 3 THEN ''Three''',
'                        WHEN 4 THEN ''Four''',
'                        WHEN 5 THEN ''Five''',
'                        WHEN 6 THEN ''Six''',
'                        WHEN 7 THEN ''Seven''',
'                        WHEN 8 THEN ''Eight''',
'                        WHEN 9 THEN ''Nine''',
'                    END || '' Hundred'';',
'',
'                IF v_rem > 0 THEN',
'',
'                    v_result :=',
'                        v_result || '' '' ||',
'                        two_digit_words(v_rem);',
'',
'                END IF;',
'',
'            ELSE',
'',
'                v_result := two_digit_words(v_rem);',
'',
'            END IF;',
'',
'            RETURN v_result;',
'',
'        END three_digit_words;',
'',
'',
'        /* =====================================================',
'           CONVERT NUMBER',
'           ===================================================== */',
'',
'        FUNCTION convert_number(p NUMBER)',
'            RETURN VARCHAR2',
'        IS',
'            v_result VARCHAR2(4000);',
'            v_part   NUMBER;',
'        BEGIN',
'',
'            IF p >= 10000000 THEN',
'',
'                v_part := TRUNC(p / 10000000);',
'',
'                v_result :=',
'                    convert_number(v_part) || '' Crore'';',
'',
'                IF MOD(p, 10000000) > 0 THEN',
'',
'                    v_result :=',
'                        v_result || '' '' ||',
'                        convert_number(MOD(p, 10000000));',
'',
'                END IF;',
'',
'',
'            ELSIF p >= 100000 THEN',
'',
'                v_part := TRUNC(p / 100000);',
'',
'                v_result :=',
'                    convert_number(v_part) || '' Lakh'';',
'',
'                IF MOD(p, 100000) > 0 THEN',
'',
'                    v_result :=',
'                        v_result || '' '' ||',
'                        convert_number(MOD(p, 100000));',
'',
'                END IF;',
'',
'',
'            ELSIF p >= 1000 THEN',
'',
'                v_part := TRUNC(p / 1000);',
'',
'                v_result :=',
'                    convert_number(v_part) || '' Thousand'';',
'',
'                IF MOD(p, 1000) > 0 THEN',
'',
'                    v_result :=',
'                        v_result || '' '' ||',
'                        convert_number(MOD(p, 1000));',
'',
'                END IF;',
'',
'',
'            ELSIF p >= 100 THEN',
'',
'                v_result := three_digit_words(p);',
'',
'',
'            ELSE',
'',
'                v_result := two_digit_words(p);',
'',
'            END IF;',
'',
'            RETURN v_result;',
'',
'        END convert_number;',
'',
'    BEGIN',
'',
'        IF v_num = 0 THEN',
'            RETURN ''Zero'';',
'        END IF;',
'',
'        RETURN convert_number(v_num);',
'',
'    END number_to_words;',
'',
'',
'BEGIN',
'',
'    /* =========================================================',
'       GET VOUCHER MASTER',
'       ========================================================= */',
'',
'    BEGIN',
'',
'        SELECT',
'            M.VOUCHER_NO,',
'            M.VOUCHER_CODE,',
'            TO_CHAR(M.VOUCHER_DATE, ''DD-Mon-YYYY''),',
'            M.VOUCHER_TYPE,',
'            M.NARRATION,',
'            M.CREATED_BY',
'',
'        INTO',
'            v_voucher_no,',
'            v_voucher_code,',
'            v_voucher_date,',
'            v_voucher_type,',
'            v_narration,',
'            v_created_by',
'',
'        FROM ACC_VOUCHER_MST M',
'',
'        WHERE M.VOUCHER_NO = :P302_VOUCHER_TYPE;',
'',
'',
'    EXCEPTION',
'',
'        WHEN NO_DATA_FOUND THEN',
'',
'            RETURN TO_CLOB(',
'                ''<div style="',
'                    padding:30px;',
'                    text-align:center;',
'                    color:#b91c1c;',
'                    font-family:Arial,sans-serif;',
'                    font-size:16px;',
'                ">',
'                    Voucher not found.',
'                </div>''',
'            );',
'',
'    END;',
'',
'',
'    /* =========================================================',
'       GET TOTAL DEBIT / CREDIT',
'       ========================================================= */',
'',
'    SELECT',
'        NVL(SUM(DEBIT_AMOUNT), 0),',
'        NVL(SUM(CREDIT_AMOUNT), 0)',
'',
'    INTO',
'        v_total_dr,',
'        v_total_cr',
'',
'    FROM ACC_VOUCHER_DTL',
'',
'    WHERE VOUCHER_NO = :P302_VOUCHER_TYPE;',
'',
'',
'    /* =========================================================',
'       HTML START',
'       ========================================================= */',
'',
'    v_html := TO_CLOB(''',
'',
'<style>',
'',
'/* =========================================================',
'   GLOBAL',
'   ========================================================= */',
'',
'* {',
'    box-sizing: border-box;',
'}',
'',
'',
'/* =========================================================',
'   MAIN VOUCHER',
'   ========================================================= */',
'',
'.voucher-print {',
'',
'    width: 100%;',
'    max-width: 1050px;',
'',
'    margin: 0 auto;',
'',
'    padding: 25px 35px;',
'',
'    background: #ffffff;',
'',
'    color: #111111;',
'',
'    font-family:',
'        Arial,',
'        "Noto Sans Bengali",',
'        sans-serif;',
'',
'    font-size: 13px;',
'',
'}',
'',
'',
'/* =========================================================',
'   HEADER',
'   ========================================================= */',
'',
'.voucher-top {',
'',
'    width: 100%;',
'',
'    display: grid;',
'',
'    grid-template-columns:',
'        22%',
'        56%',
'        22%;',
'',
'    align-items: start;',
'',
'    margin-bottom: 18px;',
'',
'}',
'',
'',
'.bank-left {',
'',
'    font-size: 12px;',
'',
'    padding-top: 8px;',
'',
'}',
'',
'',
'.bank-center {',
'',
'    text-align: center;',
'',
'}',
'',
'',
'.bank-logo {',
'',
'    width: 55px;',
'',
'    height: 55px;',
'',
'    margin:',
'        0 auto 4px auto;',
'',
'    border:',
'        1px solid #555;',
'',
'    border-radius: 50%;',
'',
'    display: flex;',
'',
'    align-items: center;',
'',
'    justify-content: center;',
'',
'    font-size: 24px;',
'',
'}',
'',
'',
'.bank-name {',
'',
'    font-size: 22px;',
'',
'    font-weight: 700;',
'',
'}',
'',
'',
'.branch-name {',
'',
