'',
'    /* =========================================================',
'       DETAIL DATA',
'       DEBIT + CREDIT SIDE BY SIDE',
'       ========================================================= */',
'',
'    FOR r IN (',
'',
'        SELECT',
'',
'            NVL(',
'                dr.rn,',
'                cr.rn',
'            ) AS rn,',
'',
'',
'            dr.account_code',
'                AS dr_account_code,',
'',
'            dr.account_name',
'                AS dr_account_name,',
'',
'            dr.amount',
'                AS dr_amount,',
'',
'',
'            cr.account_code',
'                AS cr_account_code,',
'',
'            cr.account_name',
'                AS cr_account_name,',
'',
'            cr.amount',
'                AS cr_amount,',
'',
'',
'            NVL(',
'                dr.particulars,',
'                cr.particulars',
'            ) AS particulars',
'',
'',
'        FROM',
'        (',
'',
'            /* =================================================',
'               DEBIT',
'               ================================================= */',
'',
'            SELECT',
'',
'                ROW_NUMBER() OVER (',
'                    ORDER BY',
'                        D.VOUCHER_DTL_NO',
'                ) AS rn,',
'',
'',
'                A.ACCOUNT_CODE,',
'',
'                A.ACCOUNT_NAME,',
'',
'                D.DEBIT_AMOUNT',
'                    AS amount,',
'',
'                D.PARTICULARS',
'',
'',
'            FROM ACC_VOUCHER_DTL D',
'',
'',
'            JOIN MST_ACCOUNT_HEAD A',
'',
'                ON A.ACCOUNT_NO =',
'                   D.ACCOUNT_NO',
'',
'',
'            WHERE D.VOUCHER_NO =',
'                  :P302_VOUCHER_TYPE',
'',
'              AND NVL(',
'                    D.DEBIT_AMOUNT,',
'                    0',
'                  ) > 0',
'',
'        ) dr',
'',
'',
'        FULL OUTER JOIN',
'',
'',
'        (',
'',
'            /* =================================================',
'               CREDIT',
'               ================================================= */',
'',
'            SELECT',
'',
'                ROW_NUMBER() OVER (',
'                    ORDER BY',
'                        D.VOUCHER_DTL_NO',
'                ) AS rn,',
'',
'',
'                A.ACCOUNT_CODE,',
'',
'                A.ACCOUNT_NAME,',
'',
'                D.CREDIT_AMOUNT',
'                    AS amount,',
'',
'                D.PARTICULARS',
'',
'',
'            FROM ACC_VOUCHER_DTL D',
'',
'',
'            JOIN MST_ACCOUNT_HEAD A',
'',
'                ON A.ACCOUNT_NO =',
'                   D.ACCOUNT_NO',
'',
'',
'            WHERE D.VOUCHER_NO =',
'                  :P302_VOUCHER_TYPE',
'',
'              AND NVL(',
'                    D.CREDIT_AMOUNT,',
'                    0',
'                  ) > 0',
'',
'        ) cr',
'',
'',
'        ON dr.rn = cr.rn',
'',
'',
'        ORDER BY',
'            NVL(',
'                dr.rn,',
'                cr.rn',
'            )',
'',
'    )',
'',
'    LOOP',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'            <tr class="voucher-row">',
'',
'',
'                <!-- =========================================',
'                     DEBIT AMOUNT',
'                     ========================================= -->',
'',
'                <td class="amount-col">',
'        '');',
'',
'',
'        IF r.dr_amount IS NOT NULL THEN',
'',
'            v_html :=',
'                v_html ||',
'',
'                TO_CHAR(',
'                    r.dr_amount,',
'                    ''FM999G999G999G999G990D00''',
'                );',
'',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'                </td>',
'',
'',
'                <!-- =========================================',
'                     DEBIT ACCOUNT',
'                     ========================================= -->',
'',
'                <td class="account-col">',
'        '');',
'',
'',
'        IF r.dr_account_name IS NOT NULL THEN',
'',
'            v_html :=',
'                v_html ||',
'',
'                ''<div class="account-name">'' ||',
'',
'                apex_escape.html(',
'                    r.dr_account_name',
'                ) ||',
'',
'                ''</div>'' ||',
'',
'',
'                ''<div class="account-code">'' ||',
'',
'                apex_escape.html(',
'                    NVL(',
'                        r.dr_account_code,',
'                        ''''',
'                    )',
'                ) ||',
'',
'                ''</div>'';',
'',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'                </td>',
'',
'',
'                <!-- =========================================',
'                     PARTICULARS',
'                     ========================================= -->',
'',
'                <td class="particular-col">',
'',
'                    <div class="particular-text">',
'        '');',
'',
'',
'        IF r.particulars IS NOT NULL THEN',
'',
'            v_html :=',
'                v_html ||',
'',
'                apex_escape.html(',
'                    r.particulars',
'                );',
'',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'                    </div>',
'',
'                </td>',
'',
'',
'                <!-- =========================================',
'                     CREDIT ACCOUNT',
'                     ========================================= -->',
'',
'                <td class="account-col">',
'        '');',
'',
'',
'        IF r.cr_account_name IS NOT NULL THEN',
'',
'            v_html :=',
'                v_html ||',
'',
'                ''<div class="account-name">'' ||',
'',
'                apex_escape.html(',
'                    r.cr_account_name',
'                ) ||',
'',
'                ''</div>'' ||',
'',
'',
'                ''<div class="account-code">'' ||',
'',
'                apex_escape.html(',
'                    NVL(',
'                        r.cr_account_code,',
'                        ''''',
'                    )',
'                ) ||',
'',
'                ''</div>'';',
'',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'                </td>',
'',
'',
'                <!-- =========================================',
'                     CREDIT AMOUNT',
'                     ========================================= -->',
'',
'                <td class="amount-col">',
'        '');',
'',
'',
'        IF r.cr_amount IS NOT NULL THEN',
'',
'            v_html :=',
'                v_html ||',
'',
'                TO_CHAR(',
'                    r.cr_amount,',
'                    ''FM999G999G999G999G990D00''',
'                );',
'',
'        END IF;',
'',
'',
'        v_html :=',
'            v_html ||',
'            TO_CLOB(''',
'',
'                </td>',
'',
'            </tr>',
'',
'        '');',
'',
'',
'    END LOOP;',
'',
