wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11521450767620436)
,p_plug_name=>'VOUCHER REGISTER'
,p_static_id=>'voucher-mst_1'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (SELECT',
'       M.VOUCHER_NO,',
'',
'       M.VOUCHER_CODE,',
'',
'       M.VOUCHER_DATE,',
'',
'       M.VOUCHER_TYPE,',
'',
'       M.NARRATION,',
'',
'       (',
'           SELECT NVL(SUM(DEBIT_AMOUNT),0)',
'           FROM ACC_VOUCHER_DTL D',
'           WHERE D.VOUCHER_NO = M.VOUCHER_NO',
'       ) TOTAL_DEBIT,',
'',
'       (',
'           SELECT NVL(SUM(CREDIT_AMOUNT),0)',
'           FROM ACC_VOUCHER_DTL D',
'           WHERE D.VOUCHER_NO = M.VOUCHER_NO',
'       ) TOTAL_CREDIT,',
'',
'       CASE M.APPROVAL_STATUS',
'',
'           WHEN ''A'' THEN',
'               ''<span class="t-Badge t-Badge--success">',
'                Approved',
'                </span>''',
'',
'           WHEN ''P'' THEN',
'               ''<span class="t-Badge t-Badge--warning">',
'                Pending',
'                </span>''',
'',
'           WHEN ''R'' THEN',
'               ''<span class="t-Badge t-Badge--danger">',
'                Rejected',
'                </span>''',
'',
'       END STATUS,',
'',
'       M.CREATED_BY,',
'',
'       M.CREATED_DATE,',
'NULL VIEW_BTN',
'',
'FROM ACC_VOUCHER_MST M',
'',
'WHERE (:P302_FROM_DATE IS NULL',
'       OR M.VOUCHER_DATE >= :P302_FROM_DATE)',
'',
'AND (:P302_TO_DATE IS NULL',
'     OR M.VOUCHER_DATE <= :P302_TO_DATE)',
'',
'AND (:P302_VOUCHER_TYPE IS NULL',
'     OR M.VOUCHER_TYPE = :P302_VOUCHER_TYPE)',
'',
'AND (:P302_STATUS IS NULL',
'     OR M.APPROVAL_STATUS = :P302_STATUS)',
'',
'ORDER BY M.VOUCHER_NO DESC)'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P302_FROM_DATE,P302_TO_DATE'
,p_prn_content_disposition=>'ATTACHMENT'
