wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(31493537650511512466)
,p_plug_name=>'TRANSACTION-REGISTER'
,p_static_id=>'register'
,p_region_name=>'purchase-register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT T.TRANSACTION_NO,',
'       T.TRANSACTION_CODE,',
'       T.TRANSACTION_DATE,',
'       T.TRANSACTION_TYPE,',
'       CASE T.TRANSACTION_TYPE',
'           WHEN ''R'' THEN ''Receive''',
'           WHEN ''P'' THEN ''Payment''',
'           ELSE ''Unknown''',
'       END AS TRAN_TYPE,',
'       T.PARTY_NO,',
'       CASE T.TRANSACTION_TYPE',
'           WHEN ''R'' THEN C.CUSTOMER_NAME',
'           WHEN ''P'' THEN S.SUPPLIER_NAME',
'           ELSE NULL',
'       END AS PARTY_NAME,',
'       CASE T.PAY_MODE',
'           WHEN ''C'' THEN ''Cash''',
'           WHEN ''B'' THEN ''Bank''',
'           ELSE ''Other''',
'       END AS PAYMENT_MODE,',
'       NVL(T.TOTAL_AMOUNT, 0) AS TOTAL_AMOUNT,',
'       NVL(T.NET_AMOUNT, 0) AS NET_AMOUNT,',
'       CASE T.APPROVAL_STATUS',
'           WHEN ''P'' THEN',
'               ''<span class="t-Badge t-Badge--warning">Pending</span>''',
'           WHEN ''A'' THEN',
'               ''<span class="t-Badge t-Badge--success">Approved</span>''',
'           WHEN ''R'' THEN',
'               ''<span class="t-Badge t-Badge--danger">Rejected</span>''',
'           ELSE',
'               ''<span class="t-Badge">Unknown</span>''',
'       END AS APPROVAL_STATUS,',
'       CASE T.APPROVAL_STATUS',
'           WHEN ''P'' THEN ''Pending''',
'           WHEN ''A'' THEN ''Approved''',
'           WHEN ''R'' THEN ''Rejected''',
'           ELSE ''Unknown''',
'       END AS STATUS_NAME,',
'       T.VOUCHER_NO,',
'       V.VOUCHER_CODE,',
'       T.CREATED_BY,',
'       T.CREATED_DATE,',
'       T.APPROVED_BY,',
'       T.APPROVED_DATE,',
'       NULL AS DETAILS',
'FROM TRN_TRANSACTION_MST T',
'LEFT JOIN MST_CUSTOMER C',
'  ON C.CUSTOMER_NO = T.PARTY_NO',
' AND T.TRANSACTION_TYPE = ''R''',
'LEFT JOIN MST_SUPPLIER S',
'  ON S.SUPPLIER_NO = T.PARTY_NO',
' AND T.TRANSACTION_TYPE = ''P''',
'LEFT JOIN ACC_VOUCHER_MST V',
'  ON V.VOUCHER_NO = T.VOUCHER_NO',
'ORDER BY T.TRANSACTION_NO DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
