wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10866988310388840)
,p_plug_name=>'Summery Balance Sheet HTM'
,p_static_id=>'voucher-mst_1'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Formatted on 8/25/2026 3:50:57 PM (QP5 v5.388) */',
'DECLARE',
'    v_html   CLOB;',
'BEGIN',
'    WITH',
'        OPENING_BALANCE',
'        AS',
'            (  SELECT ACCOUNT_NO,',
'                      NVL (SUM (OPENING_DEBIT), 0)      AS OPENING_DEBIT,',
'                      NVL (SUM (OPENING_CREDIT), 0)     AS OPENING_CREDIT',
'                 FROM ACC_OPENING_BALANCE',
'                WHERE APPROVAL_STATUS = ''A''',
'             GROUP BY ACCOUNT_NO),',
'        VOUCHER_BALANCE',
'        AS',
'            (  SELECT D.ACCOUNT_NO,',
'                      NVL (SUM (D.DEBIT_AMOUNT), 0)      AS VOUCHER_DEBIT,',
'                      NVL (SUM (D.CREDIT_AMOUNT), 0)     AS VOUCHER_CREDIT',
'                 FROM ACC_VOUCHER_DTL D',
'                      JOIN ACC_VOUCHER_MST M ON M.VOUCHER_NO = D.VOUCHER_NO',
'                WHERE     M.APPROVAL_STATUS = ''A''',
'                      AND M.VOUCHER_DATE <= TO_DATE(:P306_AS_OF_DATE, ''MM/DD/YYYY'')',
'             GROUP BY D.ACCOUNT_NO),',
'        ACCOUNT_BALANCE',
'        AS',
'            (SELECT H.ACCOUNT_NO,',
'                    H.ACCOUNT_TYPE,',
'                    NVL (O.OPENING_DEBIT, 0) + NVL (V.VOUCHER_DEBIT, 0)',
'                        AS TOTAL_DEBIT,',
'                    NVL (O.OPENING_CREDIT, 0) + NVL (V.VOUCHER_CREDIT, 0)',
'                        AS TOTAL_CREDIT',
'               FROM MST_ACCOUNT_HEAD  H',
'                    LEFT JOIN OPENING_BALANCE O',
'                        ON O.ACCOUNT_NO = H.ACCOUNT_NO',
'                    LEFT JOIN VOUCHER_BALANCE V',
'                        ON V.ACCOUNT_NO = H.ACCOUNT_NO',
'              WHERE H.IS_POSTING = ''Y'' AND H.ACTIVE_STATUS = ''Y''),',
'        ACCOUNT_TOTAL',
'        AS',
'            (  SELECT ACCOUNT_TYPE,',
'                      SUM (',
'                          CASE',
'                              WHEN ACCOUNT_TYPE = ''A''',
'                              THEN',
'                                  TOTAL_DEBIT - TOTAL_CREDIT',
'                              WHEN ACCOUNT_TYPE IN (''L'', ''C'')',
'                              THEN',
'                                  TOTAL_CREDIT - TOTAL_DEBIT',
'                              ELSE',
'                                  0',
'                          END)    AS AMOUNT',
'                 FROM ACCOUNT_BALANCE',
'             GROUP BY ACCOUNT_TYPE),',
'        TOTALS',
'        AS',
'            (SELECT NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''A'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_ASSETS,',
'                    NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''L'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_LIABILITIES,',
'                    NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''C'' THEN AMOUNT',
'                                ELSE 0',
'                            END),',
'                        0)    AS TOTAL_CAPITAL',
'               FROM ACCOUNT_TOTAL),',
'        PROFIT_LOSS',
'        AS',
'            (SELECT NVL (',
'                        SUM (',
'                            CASE',
'                                WHEN ACCOUNT_TYPE = ''I''',
'                                THEN',
'                                    TOTAL_CREDIT - TOTAL_DEBIT',
'                                WHEN ACCOUNT_TYPE = ''E''',
'                                THEN',
'                                    TOTAL_DEBIT - TOTAL_CREDIT',
'                                ELSE',
'                                    0',
'                            END),',
'                        0)    AS NET_PROFIT',
'               FROM ACCOUNT_BALANCE',
'              WHERE ACCOUNT_TYPE IN (''I'', ''E''))',
'    SELECT    ''<div id="balance_sheet_summary" style="',
'            width:100%;',
'            max-width:320px;',
'            box-sizing:border-box;',
'            padding:10px;',
'            border:1px solid #e1e5e9;',
'            border-radius:8px;',
'            background:#fff;',
'            font-size:12px;',
'            line-height:1.6;',
'        ">',
'',
'        <!-- ================= HEADER ================= -->',
'',
'        <div style="',
'            text-align:center;',
'            font-size:14px;',
'            font-weight:700;',
'            color:#2c3e50;',
'            margin-bottom:2px;',
'        ">',
'            Balance Sheet Summary',
'        </div>',
'',
'        <div style="',
'            text-align:center;',
'            font-size:10px;',
'            color:#7f8c8d;',
'            margin-bottom:8px;',
'        ">',
'            As of ''',
'           || NVL (TO_CHAR ( TO_DATE(:P306_AS_OF_DATE, ''MM/DD/YYYY''), ''DD Mon YYYY''),',
'                   ''Current Date'')',
'           || ''',
'        </div>',
'',
'',
'        <!-- ================= ASSETS ================= -->',
'',
'        <div style="',
'            margin-top:4px;',
'            margin-bottom:4px;',
'            padding:4px 7px;',
'            border-left:4px solid #2980b9;',
'            background:#f4f8fb;',
'            color:#2471a3;',
'            font-size:11px;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.4px;',
'        ">',
'            Assets',
'        </div>',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px 2px;',
'        ">',
'            <span>Total Assets</span>',
'',
'            <b style="',
'                color:#2980b9;',
'                font-size:13px;',
'            ">',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_ASSETS, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= LIABILITIES ================= -->',
'',
'        <div style="',
'            margin-top:8px;',
'            margin-bottom:4px;',
'            padding:4px 7px;',
'            border-left:4px solid #e67e22;',
'            background:#fdf6ee;',
'            color:#d35400;',
'            font-size:11px;',
'            font-weight:700;',
'            text-transform:uppercase;',
'            letter-spacing:.4px;',
'        ">',
'            Liabilities & Equity',
'        </div>',
'',
'',
'        <!-- Liability -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>Total Liabilities</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_LIABILITIES, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- Capital -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>Capital</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (NVL (T.TOTAL_CAPITAL, 0), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- Profit / Loss -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            padding:2px;',
'        ">',
'            <span>''',
'           || CASE',
'                  WHEN P.NET_PROFIT >= 0 THEN ''Current Period Profit''',
'                  ELSE ''Current Period Loss''',
'              END',
'           || ''</span>',
'',
'            <b style="',
'                color:''',
'           || CASE WHEN P.NET_PROFIT >= 0 THEN ''#27ae60'' ELSE ''#c0392b'' END',
'           || '';',
'            ">',
unistr('                \09F3 '''),
'           || TO_CHAR (ABS (NVL (P.NET_PROFIT, 0)), ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= TOTAL ================= -->',
'',
'        <div style="',
'            display:flex;',
'            justify-content:space-between;',
'            align-items:center;',
'            border-top:1px solid #ddd;',
'            margin-top:6px;',
'            padding-top:5px;',
'            font-weight:700;',
'        ">',
'            <span>Liabilities + Equity</span>',
'',
'            <b>',
unistr('                \09F3 '''),
'           || TO_CHAR (',
'                  NVL (T.TOTAL_LIABILITIES + T.TOTAL_CAPITAL + P.NET_PROFIT,',
'                       0),',
'                  ''FM999G999G999G990D00'')',
'           || ''',
'            </b>',
'        </div>',
'',
'',
'        <!-- ================= BALANCE STATUS ================= -->',
'',
'        <div style="',
'            margin-top:8px;',
'            padding:5px 7px;',
'            border-radius:4px;',
'            text-align:center;',
'            font-size:11px;',
'            font-weight:700;',
'            background:''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
'                      ''#eaf7ef''',
'                  ELSE',
'                      ''#fdeeee''',
'              END',
'           || '';',
'            color:''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
'                      ''#27ae60''',
'                  ELSE',
'                      ''#c0392b''',
'              END',
'           || '';',
'        ">',
'            ''',
'           || CASE',
'                  WHEN ROUND (T.TOTAL_ASSETS, 2) =',
'                       ROUND (',
'                             T.TOTAL_LIABILITIES',
'                           + T.TOTAL_CAPITAL',
'                           + P.NET_PROFIT,',
'                           2)',
'                  THEN',
unistr('                      ''\2713 BALANCED'''),
'                  ELSE',
unistr('                      ''\26A0 NOT BALANCED'''),
'              END',
'           || ''',
'        </div>',
'',
'        </div>''',
'      INTO v_html',
'      FROM TOTALS T CROSS JOIN PROFIT_LOSS P;',
'',
'',
'    RETURN v_html;',
'EXCEPTION',
'    WHEN OTHERS',
'    THEN    ',
'        RETURN ''',
'        <div style="',
'            padding:10px;',
'            font-size:12px;',
'            color:#c0392b;',
'            border:1px solid #f5c6cb;',
'            border-radius:5px;',
'            background:#fff5f5;',
'        ">',
'            Balance sheet summary unavailable. ',
'        </div>'' || SQLERRM;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P306_AS_OF_DATE'
,p_required_patch=>wwv_flow_imp.id(8032859059284477852)
,p_created_on=>wwv_flow_imp.dz('20260820115742Z')
