 p_id=>wwv_flow_imp.id(44006804141996722010)
,p_plug_name=>'Breadcrumb'
,p_static_id=>'breadcrumb'
,p_region_css_classes=>'breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-ButtonRegion--stickToBottom:t-ButtonRegion--slimPadding:t-ButtonRegion--noBorder:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2127905476394690047
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_menu_id=>wwv_flow_imp.id(8032859741578477854)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4073839682315169711
,p_created_on=>wwv_flow_imp.dz('20260819120618Z')
,p_updated_on=>wwv_flow_imp.dz('20260819120618Z')
