 p_id=>wwv_flow_imp.id(11272877657542513)
,p_plug_name=>'Opening Balance Register'
,p_static_id=>'opening-balance-register'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--removeHeader js-removeLandmark:t-Form--slimPadding:margin-top-none:margin-bottom-none'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'       O.OPENING_NO,',
'       O.FIN_YEAR,',
'       H.ACCOUNT_CODE,',
'       H.ACCOUNT_NAME,',
'       H.ACCOUNT_TYPE,',
'',
'       NVL(O.OPENING_DEBIT, 0)  AS OPENING_DEBIT,',
'       NVL(O.OPENING_CREDIT, 0) AS OPENING_CREDIT,',
'',
'       CASE',
'           WHEN NVL(O.OPENING_DEBIT, 0)',
'              - NVL(O.OPENING_CREDIT, 0) >= 0',
'           THEN NVL(O.OPENING_DEBIT, 0)',
'              - NVL(O.OPENING_CREDIT, 0)',
'           ELSE NVL(O.OPENING_CREDIT, 0)',
'              - NVL(O.OPENING_DEBIT, 0)',
'       END AS BALANCE,',
'',
'       CASE',
'           WHEN NVL(O.OPENING_DEBIT, 0)',
'              - NVL(O.OPENING_CREDIT, 0) >= 0',
'           THEN ''DR''',
'           ELSE ''CR''',
'       END AS BALANCE_TYPE,',
'',
'       CASE O.APPROVAL_STATUS',
'           WHEN ''P'' THEN ''Pending''',
'           WHEN ''A'' THEN ''Approved''',
'           WHEN ''R'' THEN ''Rejected''',
'           ELSE O.APPROVAL_STATUS',
'       END AS APPROVAL_STATUS,',
'',
'       O.CREATED_BY,',
'       O.CREATED_DATE',
'',
'FROM ACC_OPENING_BALANCE O',
'JOIN MST_ACCOUNT_HEAD H',
'  ON H.ACCOUNT_NO = O.ACCOUNT_NO',
'',
'WHERE (',
'          :P311_FIN_YEAR IS NULL',
'          OR O.FIN_YEAR = :P311_FIN_YEAR',
'      )',
'',
'ORDER BY',
'       H.ACCOUNT_CODE;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P311_FIN_YEAR'
,p_prn_content_disposition=>'ATTACHMENT'
