,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(8268556166867693427)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Tamplate'
,p_static_id=>'initialize-form-tamplate'
,p_internal_uid=>8268556261211693428
